(النقطتان فوق N تمثلان الزوج الحر)', '["مجموع الإلكترونات 8","عدد الأزواج 4","N مركزية وH جانبية","ثلاث روابط أحادية N–H","زوج حر واحد على N","رسم صحيح للتركيب"]'::jsonb, '["مجموع إلكترونات التكافؤ = 5 + 3(1) = 8","عدد الأزواج = 8 ÷ 2 = 4","3 أزواج رابطة بين N وكل H","الزوج الرابع حر على N"]'::jsonb, '[{"element":"حساب الإلكترونات والأزواج","marks":1},{"element":"تحديد الذرة المركزية","marks":1},{"element":"الروابط الثلاث","marks":1},{"element":"الزوج الحر على N","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"خطوات كاملة ورسم صحيح يتضمن الزوج الحر"},{"level":"3 درجات","description":"رسم صحيح مع نقص خطوة واحدة في الشرح"},{"level":"2 درجتان","description":"رسم الروابط الثلاث مع إهمال الزوج الحر"},{"level":"1 درجة","description":"حساب مجموع الإلكترونات فقط"},{"level":"صفر","description":"رسم خاطئ أو لا إجابة"}]'::jsonb, '["إهمال الزوج الحر على N","جعل الهيدروجين ذرة مركزية","احتساب مجموع الإلكترونات 5 أو 11"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-10-11T13:13:22.497Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1089, null, null, null, 'NH₃: مجموع الإلكترونات 5 + 3 = 8، ثلاثة أزواج رابطة، زوج حر واحد على N، الشكل مثلث هرمي. PH₃: مجموع الإلكترونات 5 + 3 = 8، ثلاثة أزواج رابطة، زوج حر واحد على P، الشكل مثلث هرمي. التفسير: N وP يقعان في المجموعة 15 فلكل منهما 5 إلكترونات تكافؤ، فيكوّن كل منهما ثلاث روابط أحادية ويبقى عليه زوج حر.', '["مجموع الإلكترونات 8 لكليهما","3 أزواج رابطة لكليهما","زوج حر واحد على الذرة المركزية لكليهما","الشكل مثلث هرمي لكليهما","التفسير: المجموعة 15 و5 إلكترونات تكافؤ"]'::jsonb, '[]'::jsonb, '[{"element":"مجموع الإلكترونات","marks":1},{"element":"الأزواج الرابطة والحرة","marks":2},{"element":"الشكل","marks":1},{"element":"تفسير التشابه","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"مقارنة كاملة في الجوانب الأربعة مع تفسير صحيح"},{"level":"4 درجات","description":"مقارنة كاملة دون تفسير أو تفسير مع نقص جانب واحد"},{"level":"3 درجات","description":"ثلاثة جوانب صحيحة"},{"level":"2 درجتان","description":"جانبان صحيحان"},{"level":"1 درجة","description":"جانب واحد صحيح"},{"level":"صفر","description":"لا إجابة صحيحة"}]'::jsonb, '["القول إن PH₃ ليس له زوج حر","وصف الشكل بأنه مثلث مستوٍ","تفسير التشابه بالدورة بدل المجموعة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-11T13:13:22.497Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1090, null, null, null, 'حساب الطالب للإلكترونات (8) والأزواج (4) واستعمال 3 أزواج للروابط صحيح. الخطأ: وضع الزوج الرابع على ذرة الهيدروجين؛ فالهيدروجين يستقر بإلكترونين فقط (زوج الرابطة) ولا يحمل أزواجًا حرة. الصحيح أن يوضع الزوج الرابع حرًا على ذرة الفوسفور المركزية، فيحيط بالفوسفور 8 إلكترونات (ثلاثة أزواج رابطة وزوج حر) وبكل هيدروجين إلكترونان.', '["الحكم على صحة الحساب والأزواج الرابطة","تحديد الخطأ: الزوج الحر على H","تعليل: H يستقر بإلكترونين","التصحيح: الزوج الحر على P وثمانية حوله"]'::jsonb, '[]'::jsonb, '[{"element":"تقويم الخطوات الصحيحة","marks":1},{"element":"تحديد الخطأ","marks":1},{"element":"التعليل","marks":1},{"element":"التصحيح","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تقويم كامل مع تحديد الخطأ وتعليله وتصحيحه"},{"level":"3 درجات","description":"تحديد الخطأ وتصحيحه مع تعليل ناقص"},{"level":"2 درجتان","description":"تحديد الخطأ دون تصحيح واضح"},{"level":"1 درجة","description":"الحكم بوجود خطأ دون تحديده"},{"level":"صفر","description":"اعتبار الحل صحيحًا أو لا إجابة"}]'::jsonb, '["اعتبار الحل صحيحًا","تصحيح الخطأ بحذف الزوج الرابع نهائيًا","تحويل إحدى الروابط إلى رابطة ثنائية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-11T13:13:22.498Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1091, 1, 'الرنين حالة تحدث للمركب أو الأيون عندما يوجد له أكثر من تركيب لويس صحيح واحد.', '["هذا تعريف الرابطة التساهمية التناسقية.","","هذا وصف تمدد الثمانية (استثناء من قاعدة الثمانية) مثل PCl₅ وSF₆."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-11T13:13:22.501Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1092, 2, 'يمكن رسم تركيبين للأوزون O₃ تقع فيهما الرابطة الثنائية على أحد جانبي ذرة الأكسجين المركزية، فهو يظهر الرنين.', '["لـ NH₃ تركيب لويس واحد فقط (ثلاث روابط أحادية وزوج حر)، فلا رنين فيه.","لـ CH₄ تركيب لويس واحد فقط (أربع روابط أحادية)، فلا رنين فيه.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-10-11T13:13:22.501Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1093, 0, 'تتفق التراكيب الرنينية في مواقع الذرات وفي العدد الكلي للإلكترونات، وتختلف فقط في توزيع أزواج الإلكترونات (موقع الرابطة الثنائية والأزواج الحرة).', '["","تغيير مواقع الذرات ينتج مركبًا مختلفًا، لا تركيبًا رنينيًا للمركب نفسه.","العدد الكلي للإلكترونات ثابت في جميع التراكيب الرنينية لأنها تمثل الجزيء أو الأيون نفسه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-11T13:13:22.501Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1094, 2, 'لا يوجد الأيون في أي من التراكيب الرنينية منفردًا ولا يتنقل بينها؛ بل تركيبه الفعلي متوسط لها جميعًا، لذا تتساوى أطوال الروابط الثلاث.', '["هذا تصور شائع خاطئ؛ فالأيون لا يتأرجح بين التراكيب، بل له تركيب واحد هو متوسطها.","لو كانت الروابط الثلاث ثنائية لزاد عدد الإلكترونات حول N على ثمانية، وهذا لا يتفق مع تراكيب لويس للأيون.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-11T13:13:22.501Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1095, 1, 'يحدث الرنين عندما يكون للمادة أكثر من تركيب لويس صحيح؛ فلـ O₃ تركيبان ولـ NO₃⁻ ثلاثة تراكيب، أما H₂O فله تركيب واحد.', '["H₂O له تركيب لويس واحد فقط فلا يظهر الرنين.","","H₂O له تركيب لويس واحد فقط فلا يظهر الرنين، وأُهمل O₃ الذي له تركيبان."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-11T13:13:22.502Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1096, 2, 'إذا أمكن وضع الرابطة الثنائية بين الذرة المركزية وأكثر من ذرة جانبية متكافئة (كما في O₃ وSO₂ وNO₃⁻) ظهرت تراكيب لويس متعددة، وهذا هو الرنين.', '["وجود أزواج حرة على الذرة المركزية لا يعني الرنين؛ فالماء H₂O على أكسجينه زوجان حران ولا رنين فيه.","الجزيئات ذات الروابط الأحادية فقط (مثل CH₄ وNH₃) لها تركيب لويس واحد ولا رنين فيها.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-11T13:13:22.502Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1097, 0, 'ينص تعريف الرنين على أنه يحدث للمركب أو الأيون، ومن أمثلته الجزيئان O₃ وSO₂ والأيون NO₃⁻.', '["","أيون النترات NO₃⁻ سالب ويظهر الرنين، كما يظهره جزيئا O₃ وSO₂ المتعادلان.","أيون النترات NO₃⁻ يظهر الرنين مع أنه أيون غير متعادل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-10-11T13:13:22.502Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1098, null, null, null, 'الرنين: حالة تحدث للمركب أو الأيون عندما يوجد له أكثر من تركيب لويس صحيح واحد. مثال: الأوزون O₃ له تركيبان: O=O–O و O–O=O (مع الأزواج الحرة المناسبة). يتغير بين التراكيب الرنينية موقع أزواج الإلكترونات (موقع الرابطة الثنائية والأزواج الحرة)، ويبقى ثابتًا موقع الذرات والعدد الكلي لإلكترونات التكافؤ. (يقبل مثال NO₃⁻ أو SO₂).', '["التعريف","مثال صحيح","ما يتغير: مواقع أزواج الإلكترونات/الرابطة الثنائية","ما يثبت: مواقع الذرات وعدد الإلكترونات"]'::jsonb, '[]'::jsonb, '[{"element":"التعريف","marks":1},{"element":"المثال","marks":1},{"element":"ما يتغير","marks":1},{"element":"ما يثبت","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تعريف دقيق ومثال صحيح وبيان ما يتغير وما يثبت"},{"level":"3 درجات","description":"ثلاثة عناصر صحيحة"},{"level":"2 درجتان","description":"عنصران صحيحان"},{"level":"1 درجة","description":"التعريف فقط"},{"level":"صفر","description":"لا إجابة صحيحة"}]'::jsonb, '["القول إن مواقع الذرات تتغير بين التراكيب الرنينية","الخلط بين الرنين والرابطة التناسقية","ذكر NH₃ مثالًا على الرنين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-11T13:13:22.502Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1099, null, null, null, 'لأن الأوزون يظهر الرنين؛ إذ يمكن رسم تركيبين له تقع الرابطة الثنائية في أحدهما بين الذرة المركزية والذرة اليمنى، وفي الآخر بينها وبين الذرة اليسرى. والتركيب الفعلي للجزيء ليس أحدهما ولا يتنقل بينهما، بل هو متوسط للتركيبين، فتكون الرابطتان متماثلتين (وسطًا بين الأحادية والثنائية) ومتساويتين في الطول.', '["الأوزون يظهر الرنين","وجود تركيبين يختلفان في موقع الرابطة الثنائية","التركيب الفعلي متوسط للتركيبين وليس تنقلًا بينهما","النتيجة: الرابطتان متماثلتان ومتساويتان في الطول"]'::jsonb, '[]'::jsonb, '[{"element":"ذكر الرنين والتركيبين","marks":1},{"element":"التركيب الفعلي متوسط","marks":1},{"element":"الاستنتاج حول أطوال الروابط","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"تعليل كامل يتضمن التركيبين والتركيب المتوسط وتساوي الروابط"},{"level":"2 درجتان","description":"ذكر الرنين والتركيبين دون توضيح التركيب المتوسط"},{"level":"1 درجة","description":"ذكر كلمة الرنين فقط"},{"level":"صفر","description":"تعليل خاطئ أو لا إجابة"}]'::jsonb, '["القول إن الجزيء يتأرجح بسرعة بين التركيبين","القول إن الرابطتين ثنائيتان","القول إن الرابطتين أحاديتان"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-11T13:13:22.503Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1100, null, null, null, 'العبارة غير صحيحة. الشرط ليس مجرد وجود رابطة ثنائية، بل إمكانية رسم أكثر من تركيب لويس صحيح للجزيء (أي إمكانية وضع الرابطة الثنائية في أكثر من موضع مع بقاء الذرات في مواقعها). مثال يظهر الرنين: SO₂ (يمكن وضع الرابطة الثنائية بين S وأي من ذرتي الأكسجين: O=S–O و O–S=O). مثال يحتوي على رابطة ثنائية ولا يظهر الرنين: الإيثين C₂H₄ (H₂C=CH₂) له تركيب لويس واحد فقط، إذ لا يوجد موضع آخر متكافئ للرابطة الثنائية.', '["الحكم بعدم صحة العبارة","شرط الرنين: أكثر من تركيب لويس صحيح","مثال صحيح يظهر الرنين مع توضيح","مثال صحيح فيه رابطة ثنائية ولا يظهر الرنين"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم","marks":1},{"element":"ذكر شرط الرنين","marks":1},{"element":"المثال الأول","marks":1},{"element":"المثال الثاني","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حكم صحيح مع الشرط والمثالين"},{"level":"3 درجات","description":"حكم صحيح مع مثالين دون ذكر الشرط"},{"level":"2 درجتان","description":"حكم صحيح مع مثال واحد"},{"level":"1 درجة","description":"الحكم فقط"},{"level":"صفر","description":"تأييد العبارة أو لا إجابة"}]'::jsonb, '["تأييد العبارة","ذكر جزيء ليس فيه رابطة ثنائية مثالًا ثانيًا","الخلط بين الرنين وتعدد الروابط"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-10-11T13:13:22.503Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1101, 1, 'ترتبط ذرة N بثلاث ذرات أكسجين متكافئة، ويمكن وضع الرابطة الثنائية N=O مع أي منها، فينتج ثلاثة تراكيب رنينية.', '["تركيبان عدد التراكيب الرنينية لـ O₃ أو SO₂ حيث توجد ذرتان جانبيتان فقط.","","لا توجد إلا ثلاثة مواضع متكافئة للرابطة الثنائية؛ لأن حول N ثلاث ذرات أكسجين فقط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-11T13:13:22.507Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1102, 2, 'مجموع إلكترونات التكافؤ = 3 × 6 = 18 إلكترونًا، أي 9 أزواج.', '["16 ناتج 2 × 8؛ أي احتساب ذرتين فقط بثمانية إلكترونات لكل منهما بدل جمع إلكترونات تكافؤ الذرات الثلاث.","24 مجموع إلكترونات أيون النترات أو ثلاث ذرات أكسجين بثمانية إلكترونات لكل منها، لا إلكترونات التكافؤ.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (35%)"}],"at":"2026-10-11T13:13:22.507Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1103, 0, 'في التركيبين الصحيحين تبقى الذرات في مواقعها (S في الوسط) ويبقى عدد الإلكترونات 18، ويتغير فقط موقع الرابطة الثنائية بين ذرتي الأكسجين.', '["","في التركيب O–S–O لا يحيط بذرة S إلا ستة إلكترونات (رابطتان أحاديتان وزوج حر)، فلا تتحقق قاعدة الثمانية، ولذلك لا يُعد تركيبًا صحيحًا.","التركيب S=O–O يغيّر موقع الذرة المركزية، وتغيير مواقع الذرات لا ينتج تركيبًا رنينيًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-11T13:13:22.508Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1104, 1, 'مجموع الإلكترونات = 4 + 3 × 6 + 2 = 24. بعد ثلاث روابط أحادية (6 إلكترونات) وإكمال ثمانيات الأكسجين (18 إلكترونًا) يبقى حول C ستة إلكترونات، فيُحوَّل زوج حر واحد إلى رابطة ثنائية: رابطة ثنائية ورابطتان أحاديتان.', '["ثلاث روابط ثنائية تجعل حول C اثني عشر إلكترونًا، وهذا يخالف قاعدة الثمانية للكربون.","","رابطتان ثنائيتان تجعل حول C عشرة إلكترونات، وهذا يخالف قاعدة الثمانية للكربون."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-11T13:13:22.508Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1105, 2, 'مجموع إلكترونات NO₂⁻ = 5 + 2 × 6 + 1 = 18 لا 17؛ نسي الطالب إضافة الإلكترون المقابل للشحنة السالبة. أما NO₃⁻ = 5 + 18 + 1 = 24 وSO₂ = 6 + 12 = 18 فصحيحان.', '["حساب NO₃⁻ صحيح: 5 + 3 × 6 + 1 = 24.","حساب SO₂ صحيح: 6 + 2 × 6 = 18.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (35%)"}],"at":"2026-10-11T13:13:22.508Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1106, 1, 'ترتبط ذرة الأكسجين المركزية برابطة ثنائية (4 إلكترونات) ورابطة أحادية (إلكترونان)، فيلزمها زوج حر واحد ليكتمل حولها 8 إلكترونات، ويبقى المجموع 18 إلكترونًا.', '["زوجان حران مع رابطة ثنائية وأخرى أحادية يجعلان حول الذرة المركزية 10 إلكترونات، ويرفعان المجموع إلى 20.","","بدون زوج حر يحيط بالذرة المركزية 6 إلكترونات فقط، ولا يكتمل مجموع الإلكترونات (18)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-11T13:13:22.509Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1107, 2, 'تمثل التراكيب الرنينية الأيون نفسه، فتبقى مواقع الذرات (N في الوسط) والعدد الكلي للإلكترونات (18) ثابتة، ويتغير موقع الرابطة الثنائية وتوزيع الأزواج الحرة.', '["موقع الرابطة الثنائية هو بالذات ما يتغير بين التراكيب الرنينية.","عدد الأزواج الحرة على ذرة الأكسجين يتغير بحسب ارتباطها برابطة ثنائية (زوجان) أو أحادية (ثلاثة أزواج).",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-10-11T13:13:22.509Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1108, null, null, null, 'الخطوات: (1) مجموع الإلكترونات = 5 + 3 × 6 + 1 (للشحنة السالبة) = 24 إلكترونًا = 12 زوجًا. (2) N ذرة مركزية وذرات O الثلاث جانبية، نضع رابطة أحادية بين N وكل O (3 أزواج). (3) نكمل ثمانيات ذرات الأكسجين بالأزواج الحرة (9 أزواج) فتنفد الأزواج ويبقى حول N ستة إلكترونات فقط. (4) نحوّل زوجًا حرًا من إحدى ذرات الأكسجين إلى رابطة ثنائية N=O فيكتمل الثماني حول N. (5) يمكن اختيار أي ذرة أكسجين من الثلاث للرابطة الثنائية، فتنتج ثلاثة تراكيب رنينية، يُوضع كل منها بين قوسين مع الشحنة (−) ويُفصل بينها بسهم ذي رأسين ↔.
في كل تركيب: رابطة N=O واحدة (على ذرة O فيها زوجان حران)، ورابطتان N–O (على كل ذرة O فيها ثلاثة أزواج حرة)، ولا زوج حر على N.
[O=N(–O)–O]⁻ ↔ [O–N(=O)–O]⁻ ↔ [O–N(–O)=O]⁻', '["مجموع الإلكترونات 24 (مع إضافة إلكترون الشحنة)","روابط أحادية وإكمال ثمانيات O","تكوين رابطة ثنائية لإكمال ثماني N","رسم ثلاثة تراكيب تختلف في موقع الرابطة الثنائية","الأقواس والشحنة والسهم ↔"]'::jsonb, '["مجموع الإلكترونات = 5 + 3(6) + 1 = 24 (12 زوجًا)","3 روابط أحادية N–O تستعمل 3 أزواج","9 أزواج حرة تكمل ثمانيات O","تحويل زوج حر إلى رابطة ثنائية N=O","تكرار ذلك مع كل ذرة O ← 3 تراكيب"]'::jsonb, '[{"element":"حساب الإلكترونات","marks":1},{"element":"بناء التركيب الأول صحيحًا","marks":2},{"element":"رسم التراكيب الثلاثة","marks":1},{"element":"الأقواس والشحنة والسهم","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"خطوات كاملة وثلاثة تراكيب صحيحة مع الأقواس والشحنة والسهم"},{"level":"4 درجات","description":"ثلاثة تراكيب صحيحة مع إهمال الأقواس أو الشحنة"},{"level":"3 درجات","description":"تركيب واحد صحيح كامل مع حساب صحيح"},{"level":"2 درجتان","description":"حساب صحيح للإلكترونات مع تركيب ناقص الأزواج الحرة"},{"level":"1 درجة","description":"حساب مجموع الإلكترونات فقط"},{"level":"صفر","description":"لا إجابة صحيحة"}]'::jsonb, '["نسيان إضافة إلكترون الشحنة (23 إلكترونًا)","رسم تركيبين فقط","وضع زوج حر على N","تحريك الذرات بدل الإلكترونات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-11T13:13:22.509Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1109, null, null, null, 'SO₂: مجموع الإلكترونات 6 + 2 × 6 = 18، التراكيب: O=S–O ↔ O–S=O، على S زوج حر واحد، وعلى O المرتبطة برابطة ثنائية زوجان حران، وعلى O المرتبطة برابطة أحادية ثلاثة أزواج. O₃: مجموع الإلكترونات 3 × 6 = 18، التراكيب: O=O–O ↔ O–O=O، على ذرة O المركزية زوج حر واحد، والتوزيع على الذرتين الجانبيتين كما في SO₂. المقارنة: المجموع متساوٍ (18)، ولكل منهما تركيبان رنينيان، وعلى الذرة المركزية زوج حر واحد؛ والسبب أن S وO في المجموعة نفسها (6 إلكترونات تكافؤ).', '["تراكيب SO₂ الصحيحة","تراكيب O₃ الصحيحة","المجموع 18 لكليهما","تركيبان لكل منهما","زوج حر واحد على الذرة المركزية"]'::jsonb, '["SO₂: 6 + 2(6) = 18","O₃: 3(6) = 18","رابطة أحادية وأخرى ثنائية مع زوج حر على الذرة المركزية","تبديل موقع الرابطة الثنائية ← تركيبان"]'::jsonb, '[{"element":"تراكيب SO₂","marks":2},{"element":"تراكيب O₃","marks":2},{"element":"المقارنة","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"تراكيب صحيحة للجزيئين ومقارنة كاملة في النقاط الثلاث"},{"level":"5 درجات","description":"تراكيب صحيحة مع نقص نقطة في المقارنة"},{"level":"4 درجات","description":"تراكيب صحيحة للجزيئين دون مقارنة"},{"level":"3 درجات","description":"تراكيب جزيء واحد صحيحة مع مقارنة جزئية"},{"level":"2 درجتان","description":"تراكيب جزيء واحد صحيحة فقط"},{"level":"1 درجة","description":"حساب مجموع الإلكترونات فقط"},{"level":"صفر","description":"لا إجابة صحيحة"}]'::jsonb, '["إهمال الزوج الحر على الذرة المركزية","تغيير موقع ذرة S في أحد التراكيب","حساب مجموع الإلكترونات 24"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-11T13:13:22.511Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1110, null, null, null, 'مجموع الإلكترونات = 5 + 2 × 6 + 1 = 18. التركيب (أ) صحيح: N مركزية، رابطة ثنائية مع إحدى ذرتي O (عليها زوجان حران) ورابطة أحادية مع الأخرى (عليها ثلاثة أزواج حرة)، وعلى N زوج حر واحد. التركيب (ب) خطأ: غيّر الطالب ترتيب الذرات فجعل الأكسجين ذرة مركزية، والتراكيب الرنينية لا تختلف في مواقع الذرات بل في مواقع الإلكترونات فقط. التراكيب الصحيحة: [O=N–O]⁻ ↔ [O–N=O]⁻ (مع زوج حر على N في كل منهما).', '["حساب مجموع الإلكترونات 18","الحكم بصحة التركيب (أ)","الحكم بخطأ (ب) لتغيير مواقع الذرات","رسم التركيبين الصحيحين مع السهم ↔"]'::jsonb, '["مجموع الإلكترونات = 5 + 2(6) + 1 = 18"]'::jsonb, '[{"element":"حساب الإلكترونات","marks":1},{"element":"تقويم التركيب (أ)","marks":1},{"element":"تقويم التركيب (ب) مع التعليل","marks":1},{"element":"رسم التركيبين الصحيحين","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"تقويم صحيح للتركيبين مع التعليل ورسم التركيبين الصحيحين"},{"level":"4 درجات","description":"تقويم صحيح ورسم صحيح مع نقص في التعليل"},{"level":"3 درجات","description":"تقويم صحيح للتركيبين دون رسم صحيح"},{"level":"2 درجتان","description":"تقويم تركيب واحد صحيحًا"},{"level":"1 درجة","description":"حساب مجموع الإلكترونات فقط"},{"level":"صفر","description":"لا إجابة صحيحة"}]'::jsonb, '["قبول التركيب (ب) تركيبًا رنينيًا","إهمال الزوج الحر على N","نسيان إلكترون الشحنة السالبة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-10-11T13:13:22.511Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1111, 0, 'يكوّن البورون ثلاث روابط أحادية B–F (ثلاثة أزواج = 6 إلكترونات) ولا يبقى عليه زوج حر، فيستقر بستة إلكترونات أقل من الثمانية.', '["","8 إلكترونات تتحقق للذرات الجانبية (F) لا للبورون؛ فلا تتوافر أزواج إضافية حول B بعد إكمال ثمانيات الفلور.","3 هو عدد إلكترونات تكافؤ البورون، لكن كل رابطة تضيف إلكترونًا من الفلور فيصبح حوله 6."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-10-11T13:13:22.514Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1112, 1, 'في BH₃ يكوّن البورون ثلاث روابط أحادية فقط فيحيط به 6 إلكترونات، وهو من أمثلة الاستثناء من قاعدة الثمانية (أقل من 8).', '["في CH₄ يحيط بالكربون أربعة أزواج رابطة = 8 إلكترونات.","","في NH₃ يحيط بالنيتروجين ثلاثة أزواج رابطة وزوج حر = 8 إلكترونات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (39%)"}],"at":"2026-10-11T13:13:22.515Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1113, 2, 'للبورون ثلاثة إلكترونات تكافؤ فقط، فيشارك بها في ثلاث روابط أحادية مع ثلاث ذرات H، ولا تتوافر إلكترونات أخرى في الجزيء لإكمال ثمانيته (المجموع 6 فقط).', '["BH₃ مركب تساهمي ترتبط فيه الذرات بمشاركة الإلكترونات، لا بفقدها وتكوين أيونات.","تمدد الثمانية يعني أكثر من 8 إلكترونات (مثل PCl₅)، وهذا عكس حالة البورون.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-11T13:13:22.515Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1114, 1, 'مجموع الإلكترونات = 3 + 3 × 7 = 24 (12 زوجًا): ثلاثة أزواج رابطة، وتسعة أزواج حرة تُوزع ثلاثة على كل ذرة F لإكمال ثمانيتها، فلا يبقى شيء للبورون.', '["زوجان على كل F لا يكملان ثمانية الفلور (6 إلكترونات فقط حوله) ويتركان المجموع 18 فقط.","","زوج حر على B يرفع المجموع إلى 26 إلكترونًا، وهو أكثر من إلكترونات التكافؤ (24)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-10-11T13:13:22.515Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1115, 2, 'يحيط بالبريليوم في BeCl₂ أربعة إلكترونات وبالبورون في BCl₃ ستة إلكترونات، وكلاهما أقل من ثمانية.', '["NF₃ يحقق الثمانية (8)، وPCl₅ يتجاوزها (10).","BCl₃ أقل من ثمانية فعلًا، لكن NF₃ يحقق الثمانية تمامًا.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (39%)"}],"at":"2026-10-11T13:13:22.516Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1116, 1, 'ذرة البورون في BH₃ ينقصها زوج لإكمال الثمانية، والنيتروجين في NH₃ يحمل زوجًا حرًا، فيرتبطان برابطة تساهمية تناسقية H₃N–BH₃ يكتمل بها الثماني حول B.', '["ثمانية البورون في BH₃ غير مكتملة (6 إلكترونات فقط)، ولذلك يميل إلى التفاعل.","","BH₃ مركب تساهمي لا يتحول إلى أيون بفقد الإلكترونات في هذا التفاعل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-11T13:13:22.516Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1117, 2, 'المجموع = 3 + 3 × 1 = 6 إلكترونات = 3 أزواج، تُستعمل كلها في ثلاث روابط B–H.', '["افترض أن الثمانية مكتملة حول B فأضاف زوجًا غير موجود.","أهمل إلكترونات ذرات الهيدروجين أو حسب ذرة H واحدة فقط (3 + 1).",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-11T13:13:22.516Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1118, null, null, null, 'الخطوات: (1) مجموع الإلكترونات = 3 + 3 × 7 = 24 = 12 زوجًا. (2) B ذرة مركزية (الأقل كهروسالبية) وذرات F الثلاث جانبية، نضع رابطة أحادية B–F مع كل منها (3 أزواج). (3) نكمل ثمانيات ذرات F بالأزواج الحرة: 3 أزواج على كل F (9 أزواج)، فتنفد الأزواج الاثنا عشر. (4) يبقى حول B ستة إلكترونات فقط.
التركيب: B في الوسط مرتبطة بثلاث ذرات F بروابط أحادية، وعلى كل F ثلاثة أزواج حرة، ولا زوج حر على B.
سبب الاستثناء: الذرة المركزية B تستقر بستة إلكترونات فقط (أقل من ثمانية)؛ لأن لها ثلاثة إلكترونات تكافؤ فتكوّن ثلاث روابط فقط.', '["مجموع الإلكترونات 24","B مركزية بثلاث روابط أحادية","ثلاثة أزواج حرة على كل F","لا زوج حر على B","تعليل الاستثناء: 6 إلكترونات حول B"]'::jsonb, '["مجموع الإلكترونات = 3 + 3(7) = 24 (12 زوجًا)","3 أزواج رابطة B–F","9 أزواج حرة (3 على كل F)","حول B: 3 × 2 = 6 إلكترونات"]'::jsonb, '[{"element":"حساب الإلكترونات والأزواج","marks":1},{"element":"الروابط والأزواج الحرة","marks":2},{"element":"بيان الاستثناء مع التعليل","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"خطوات ورسم صحيحان مع تعليل الاستثناء"},{"level":"3 درجات","description":"رسم صحيح مع تعليل ناقص"},{"level":"2 درجتان","description":"رسم صحيح دون تعليل، أو تعليل صحيح مع رسم ناقص الأزواج"},{"level":"1 درجة","description":"حساب مجموع الإلكترونات فقط"},{"level":"صفر","description":"لا إجابة صحيحة"}]'::jsonb, '["إضافة زوج حر على B لإكمال الثمانية","وضع زوجين فقط على كل F","احتساب مجموع الإلكترونات 26"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-11T13:13:22.517Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1119, null, null, null, 'BH₃: المجموع 3 + 3 = 6، ثلاثة أزواج رابطة، لا أزواج حرة على B، حول B ستة إلكترونات. NH₃: المجموع 5 + 3 = 8، ثلاثة أزواج رابطة، زوج حر واحد على N، حول N ثمانية إلكترونات. الاستثناء: BH₃ لأن ذرته المركزية تستقر بأقل من ثمانية إلكترونات.', '["المجموع 6 مقابل 8","3 أزواج رابطة لكليهما","صفر مقابل زوج حر واحد","6 مقابل 8 حول الذرة المركزية","BH₃ هو الاستثناء"]'::jsonb, '["BH₃: 3 + 3(1) = 6","NH₃: 5 + 3(1) = 8"]'::jsonb, '[{"element":"مجموع الإلكترونات","marks":1},{"element":"الأزواج الرابطة والحرة","marks":2},{"element":"الإلكترونات حول الذرة المركزية","marks":1},{"element":"تحديد الاستثناء","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"مقارنة كاملة وتحديد صحيح للاستثناء"},{"level":"4 درجات","description":"مقارنة كاملة مع خطأ في عنصر واحد"},{"level":"3 درجات","description":"ثلاثة عناصر صحيحة"},{"level":"2 درجتان","description":"عنصران صحيحان"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"لا إجابة صحيحة"}]'::jsonb, '["وضع زوج حر على B قياسًا على NH₃","احتساب مجموع BH₃ ثمانية","اعتبار NH₃ استثناءً بسبب الزوج الحر"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-11T13:13:22.517Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1120, null, null, null, 'يحيط بالبورون في BH₃ ستة إلكترونات فقط، أي ينقصه زوج واحد لإكمال الثمانية، بينما يحمل النيتروجين في NH₃ زوجًا حرًا. يقدّم النيتروجين زوجه الحر للبورون فتتكوّن رابطة تساهمية تناسقية N→B (زوجها مقدّم من ذرة واحدة). في الناتج H₃N–BH₃: النيتروجين مرتبط بثلاث ذرات H وبذرة B (أربعة أزواج رابطة، لا زوج حر)، والبورون مرتبط بثلاث ذرات H وبذرة N (أربعة أزواج رابطة)، فيحيط بكل من N وB ثمانية إلكترونات.', '["حول B في BH₃ ستة إلكترونات (ينقصه زوج)","N في NH₃ يحمل زوجًا حرًا","تكوّن رابطة تناسقية بتقديم N الزوج الحر","تمثيل الناتج: أربعة أزواج رابطة حول كل من N وB"]'::jsonb, '[]'::jsonb, '[{"element":"بيان نقص الثمانية في BH₃","marks":1},{"element":"دور الزوج الحر على N","marks":1},{"element":"الرابطة التناسقية","marks":1},{"element":"تمثيل الناتج","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"توضيح كامل وتمثيل صحيح للناتج"},{"level":"3 درجات","description":"توضيح صحيح مع تمثيل ناقص"},{"level":"2 درجتان","description":"ذكر الرابطة التناسقية دون تحديد الذرة المانحة أو دون تمثيل"},{"level":"1 درجة","description":"ذكر أن B ينقصه زوج فقط"},{"level":"صفر","description":"لا إجابة صحيحة"}]'::jsonb, '["القول إن البورون هو الذي يقدم زوج الإلكترونات","إبقاء زوج حر على N في الناتج","القول إن الرابطة أيونية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-11T13:13:22.517Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.')
