insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check, reviewer_notes) values
(627, 1, 'الليثيوم أول عناصر الدورة الثانية، فشحنة نواته (3) هي الأقل، وإلكترون تكافئه الوحيد (2s¹) أبعد عن النواة نسبيًا، فيسهل نزعه.', '["لكل عناصر الدورة الثانية العدد نفسه من المستويات (مستويان).","","مستوى الليثيوم الخارجي فيه إلكترون واحد فقط وليس ممتلئًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-10-11T13:13:22.197Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(628, null, null, null, 'لأنه بالانتقال يمينًا في الدورة يزداد عدد البروتونات فتزداد الشحنة النووية، بينما تضاف الإلكترونات إلى المستوى الرئيسي نفسه فيبقى الحجب ثابتًا تقريبًا. لذلك تزداد قوة جذب النواة لإلكترونات التكافؤ ويقل نصف القطر، فيصبح نزع الإلكترون أصعب ويحتاج إلى طاقة أكبر.', '["زيادة الشحنة النووية","الإلكترونات في المستوى نفسه والحجب ثابت","زيادة الجذب ونقص نصف القطر","صعوبة نزع الإلكترون"]'::jsonb, '[]'::jsonb, '[{"element":"زيادة الشحنة وثبات المستوى","marks":1},{"element":"زيادة الجذب ونقص نصف القطر","marks":1},{"element":"الربط بصعوبة النزع","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"تعليل كامل"},{"level":"2 درجة","description":"تعليل دون ربط بصعوبة النزع أو دون ثبات المستوى"},{"level":"1 درجة","description":"ذكر زيادة البروتونات فقط"},{"level":"صفر","description":"تعليل خاطئ"}]'::jsonb, '["التعليل بزيادة عدد المستويات","القول إن نصف القطر يزداد في الدورة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (46%)"}],"at":"2026-10-11T13:13:22.197Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(629, null, null, null, 'Be: 1s² 2s² ، F: 1s² 2s² 2p⁵. كلاهما في الدورة الثانية (مستويان رئيسيان) ويحجب إلكتروناتهما الخارجية إلكترونا 1s² فقط. طاقة تأين F أعلى؛ لأن نواته فيها 9 بروتونات مقابل 4 في Be، فتجذب إلكترونات المستوى الثاني بقوة أكبر ويكون نصف قطره أصغر، فيحتاج نزع الإلكترون منه إلى طاقة أكبر.', '["توزيع Be","توزيع F","F أعلى طاقة تأين","التفسير بالشحنة النووية مع تساوي المستويات والحجب"]'::jsonb, '[]'::jsonb, '[{"element":"التوزيعان","marks":2},{"element":"التحديد","marks":1},{"element":"التفسير","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"جميع العناصر صحيحة"},{"level":"3–4 درجات","description":"تحديد صحيح مع تفسير ناقص"},{"level":"1–2 درجة","description":"التوزيعان فقط"},{"level":"صفر","description":"لا إجابة صحيحة"}]'::jsonb, '["اختيار Be لأن مستواه الخارجي 2s² مكتمل","إغفال تساوي عدد المستويات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-11T13:13:22.197Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(630, null, null, null, '(أ) تزداد طاقة التأين من Li (520) إلى Ne (2081) بزيادة العدد الذري. (ب) لأن الشحنة النووية تزداد والإلكترونات تضاف إلى المستوى الثاني نفسه مع ثبات الحجب، فيقوى جذب النواة لإلكترونات التكافؤ. (ج) علاقة عكسية: يقل نصف القطر في الدورة نحو اليمين بينما تزداد طاقة التأين، لأن الإلكترون الأقرب إلى النواة يكون أصعب نزعًا.', '["وصف الزيادة","التفسير بالشحنة وثبات المستوى","العلاقة العكسية مع نصف القطر","تعليل العلاقة العكسية"]'::jsonb, '[]'::jsonb, '[{"element":"(أ) الوصف","marks":1},{"element":"(ب) التفسير","marks":2},{"element":"(ج) العلاقة وتعليلها","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"جميع الأجزاء صحيحة"},{"level":"3–4 درجات","description":"خطأ أو نقص في جزء"},{"level":"1–2 درجة","description":"الوصف فقط"},{"level":"صفر","description":"لا إجابة صحيحة"}]'::jsonb, '["جعل العلاقة مع نصف القطر طردية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-10-11T13:13:22.197Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(631, 2, 'تزداد طاقة التأين في الدورة من اليسار إلى اليمين، والكلور (المجموعة 17) أبعد الخيارات إلى اليمين.', '["Na أقصى اليسار فطاقة تأينه هي الأقل.","Si يقع يسار Cl فطاقة تأينه أقل منه.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-10-11T13:13:22.200Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(632, 0, 'في الدورة تزداد طاقة التأين نحو اليمين: K (المجموعة 1) ثم Ca (2) ثم Br (17).', '["","هذا ترتيب تنازلي (معكوس).","K يسبق Ca في الدورة فطاقة تأينه أقل لا أكبر."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (35%)"}],"at":"2026-10-11T13:13:22.201Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(633, 1, 'X في المجموعة 1 وY في المجموعة 17 من الدورة الثالثة، وطاقة التأين تزداد نحو اليمين فـ Y أعلى.', '["قلة إلكترونات التكافؤ تعني موقعًا في يسار الدورة وطاقة تأين أقل.","","وجودهما في دورة واحدة لا يعني تساوي طاقتي التأين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-11T13:13:22.202Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(634, 2, 'الكربون يقع بين Li وF في الدورة الثانية، فطاقة تأينه بين القيمتين الأقل (Li = 520) والأعلى (F = 1681)، أي 1086 kJ/mol.', '["520 أقل القيم وتخص الليثيوم أقصى اليسار.","1681 أعلى القيم وتخص الفلور الأبعد إلى اليمين.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-11T13:13:22.203Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(635, 0, 'أسهل العناصر فقدًا للإلكترون هو صاحب أقل طاقة تأين، وهو الصوديوم لأنه أقصى يسار الدورة.', '["","Si يقع يمين Na فطاقة تأينه أعلى.","Ar غاز نبيل في آخر الدورة وله أعلى طاقة تأين فيها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (36%)"}],"at":"2026-10-11T13:13:22.203Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(636, 1, 'عنصر المجموعة 17 يقع يمين عنصر المجموعة 1 في الدورة نفسها، فشحنة نواته أكبر ونصف قطره أصغر وطاقة تأينه أكبر.', '["عنصر المجموعة 1 أقصى اليسار فطاقة تأينه هي الأقل في الدورة.","","الاختلاف في الشحنة النووية يجعل طاقتي التأين مختلفتين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-11T13:13:22.203Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(637, 2, 'Ar (المجموعة 18) يقع يمين Cl (المجموعة 17)، وشحنة نواته أكبر ومستواه الخارجي ممتلئ مستقر، فطاقة تأينه أعلى (1521 مقابل 1251 kJ/mol).', '["ميل الكلور لجذب الإلكترونات لا يجعل طاقة تأينه أعلى من الغاز النبيل في دورته.","الانتماء إلى الفئة نفسها لا يعني تساوي طاقة التأين.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-10-11T13:13:22.204Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(638, null, null, null, 'الترتيب: Li < C < F < Ne. التعليل: العناصر في الدورة الثانية نفسها، وبالانتقال يمينًا تزداد الشحنة النووية مع بقاء الإلكترونات في المستوى الثاني نفسه، فيقوى جذب النواة لإلكترونات التكافؤ ويقل نصف القطر، فتزداد الطاقة اللازمة لنزع الإلكترون.', '["الترتيب Li < C < F < Ne","العناصر في دورة واحدة","زيادة الشحنة النووية نحو اليمين","زيادة الجذب وصعوبة النزع"]'::jsonb, '[]'::jsonb, '[{"element":"الترتيب","marks":2},{"element":"التعليل","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"ترتيب صحيح وتعليل كامل"},{"level":"2–3 درجات","description":"ترتيب صحيح مع تعليل ناقص"},{"level":"1 درجة","description":"ترتيب معكوس أو خطأ في عنصرين"},{"level":"صفر","description":"لا إجابة صحيحة"}]'::jsonb, '["وضع Ne قبل F","الترتيب تنازليًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (35%)"}],"at":"2026-10-11T13:13:22.204Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(639, null, null, null, '(أ) A: 1s² 2s² 2p⁶ 3s¹ ، B: 1s² 2s² 2p⁶ 3s² 3p⁵. (ب) آخر مستوى رئيسي لكليهما n = 3 فهما في الدورة الثالثة. (ج) طاقة تأين B أكبر؛ لأن B (المجموعة 17) يقع يمين A (المجموعة 1)، وشحنة نواته (17) أكبر مع تساوي عدد المستويات، فيقوى جذب النواة لإلكترونات التكافؤ ويصعب نزعها.', '["التوزيعان","الدورة الثالثة لكليهما","B أعلى طاقة تأين","التعليل بالشحنة وتساوي المستويات"]'::jsonb, '[]'::jsonb, '[{"element":"(أ) التوزيعان","marks":2},{"element":"(ب) الدورة","marks":1},{"element":"(ج) المقارنة والتعليل","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"جميع الأجزاء صحيحة"},{"level":"3–4 درجات","description":"خطأ في جزء واحد"},{"level":"1–2 درجة","description":"التوزيعان فقط"},{"level":"صفر","description":"لا إجابة صحيحة"}]'::jsonb, '["اختيار A أعلى لأن إلكتروناته أقل"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-11T13:13:22.204Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(640, null, null, null, '(أ) أكبر من 1251 kJ/mol (القيمة الفعلية نحو 1521)؛ لأن Ar يقع يمين Cl في الدورة نفسها، فشحنة نواته أكبر ومستواه الخارجي ممتلئ (3s² 3p⁶)، فنزع إلكترون منه أصعب. (ب) الصوديوم؛ لأن طاقة تأينه الأقل (496 kJ/mol)، فنزع إلكترونه هو الأسهل.', '["التوقع: أكبر من 1251","التعليل بموقع Ar وشحنته وامتلاء مستواه","Na الأسهل","التعليل بأقل طاقة تأين"]'::jsonb, '[]'::jsonb, '[{"element":"(أ) التوقع","marks":1},{"element":"(أ) التعليل","marks":2},{"element":"(ب) التحديد والتعليل","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"توقع صحيح معلل وتحديد صحيح معلل"},{"level":"2–3 درجات","description":"توقع صحيح بتعليل ناقص"},{"level":"1 درجة","description":"تحديد Na فقط"},{"level":"صفر","description":"لا إجابة صحيحة"}]'::jsonb, '["توقع قيمة أقل من الكلور","اختيار Cl أسهل في تكوين أيون موجب"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-11T13:13:22.205Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(641, 1, 'تقل طاقة التأين في المجموعة من الأعلى إلى الأسفل، والليثيوم أعلى المجموعة بين الخيارات فطاقة تأينه الأكبر.', '["Na يقع أسفل Li فطاقة تأينه أقل.","","K أسفل الخيارات فطاقة تأينه الأقل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (50%)"}],"at":"2026-10-11T13:13:22.208Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(642, 0, 'في المجموعة تقل طاقة التأين نزولًا: F (الدورة 2) أعلاها ثم Cl ثم Br أقلها، فالترتيب التصاعدي Br < Cl < F.', '["","هذا ترتيب تصاعدي لنصف القطر لا لطاقة التأين.","Br أسفل Cl فطاقة تأينه أقل منه لا أكبر."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-10-11T13:13:22.208Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(643, 2, 'C في الدورة الثانية وGe في الدورة الرابعة من المجموعة نفسها، وطاقة التأين تقل نزولًا فـ C أكبر.', '["زيادة الشحنة النووية في Ge لا تعوض بعد إلكترونات تكافئه وزيادة الحجب.","تساوي إلكترونات التكافؤ لا يعني تساوي طاقة التأين.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-10-11T13:13:22.208Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(644, 1, 'طاقة التأين تقل بانتظام نزولًا في المجموعة (520 → 496 → 419)، والروبيديوم أسفل البوتاسيوم فيتوقع أن تكون طاقة تأينه أقل من 419 kJ/mol.', '["هذا يعني أن Rb أعلى من Li في طاقة التأين، وهو يخالف التدرج.","","هذا المدى بين Na وK، وRb يقع أسفل كليهما."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-11T13:13:22.209Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(645, 0, 'X وY في المجموعة 1؛ إلكترون تكافؤ X في المستوى الثاني وY في الثالث، فإلكترون X أقرب وأقل حجبًا ويصعب نزعه أكثر.', '["","زيادة الشحنة النووية في Y يغلبها بعد الإلكترون وزيادة الحجب.","تساوي إلكترونات التكافؤ يضعهما في مجموعة واحدة لكن طاقة التأين تختلف."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-10-11T13:13:22.209Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(646, 2, 'Mg يقع فوق Ca في المجموعة 2 فطاقة تأينه أكبر. أما K فيقع أسفل Na، وBr أسفل Cl، فالأول أقل في الحالتين.', '["K أسفل Na في المجموعة 1 فطاقة تأينه أقل.","Br أسفل Cl في المجموعة 17 فطاقة تأينه أقل.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-11T13:13:22.209Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(647, 0, 'الهيليوم أعلى المجموعة 18، وإلكتروناه في المستوى الأول القريب جدًا من النواة دون حجب، فطاقة تأينه هي الأعلى بين جميع العناصر.', '["","Ne يقع أسفل He فطاقة تأينه أقل.","Ar يقع أسفل Ne وHe فطاقة تأينه الأقل بين الخيارات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (50%)"}],"at":"2026-10-11T13:13:22.209Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(648, null, null, null, 'الترتيب: Cs < K < Na < Li. التعليل: العناصر في المجموعة نفسها، وكلما نزلنا فيها يزداد عدد المستويات الرئيسية ويكبر نصف القطر ويزداد الحجب، فيبتعد إلكترون التكافؤ عن النواة ويضعف جذبها له ويسهل نزعه، فتقل طاقة التأين.', '["الترتيب Cs < K < Na < Li","العناصر في مجموعة واحدة","زيادة المستويات ونصف القطر والحجب نزولًا","ضعف الجذب وسهولة النزع"]'::jsonb, '[]'::jsonb, '[{"element":"الترتيب","marks":2},{"element":"التعليل","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"ترتيب صحيح وتعليل كامل"},{"level":"2–3 درجات","description":"ترتيب صحيح مع تعليل ناقص"},{"level":"1 درجة","description":"ترتيب معكوس مع تعليل جزئي"},{"level":"صفر","description":"لا إجابة صحيحة"}]'::jsonb, '["الترتيب حسب العدد الذري تصاعديًا (Li أولًا)","التعليل بزيادة الشحنة النووية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-10-11T13:13:22.210Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(649, null, null, null, '(أ) A: 1s² 2s² 2p² ، B: 1s² 2s² 2p⁶ 3s² 3p². (ب) لكل منهما أربعة إلكترونات تكافؤ (ns² np²) فهما في المجموعة 14؛ A في الدورة 2 وB في الدورة 3. (ج) طاقة تأين A أكبر؛ لأن إلكترونات تكافئه في المستوى الثاني الأقرب إلى النواة ويحجبها عدد أقل من الإلكترونات الداخلية، فتجذبها النواة بقوة أكبر.', '["التوزيعان","المجموعة 14 لكليهما","A أعلى طاقة تأين","التعليل بالبعد والحجب"]'::jsonb, '[]'::jsonb, '[{"element":"(أ) التوزيعان","marks":2},{"element":"(ب) المجموعة","marks":1},{"element":"(ج) المقارنة والتعليل","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"جميع الأجزاء صحيحة"},{"level":"3–4 درجات","description":"خطأ في جزء واحد"},{"level":"1–2 درجة","description":"التوزيعان فقط"},{"level":"صفر","description":"لا إجابة صحيحة"}]'::jsonb, '["اختيار B لأن شحنة نواته أكبر"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-11T13:13:22.210Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(650, null, null, null, 'أعلاها C وأقلها B. مقارنة A وC (الدورة نفسها): C يقع يمين A فشحنة نواته أكبر وطاقة تأينه أكبر، أي C > A. مقارنة A وB (المجموعة نفسها): B يقع أسفل A فطاقة تأينه أقل، أي A > B. إذن الترتيب C > A > B.', '["C الأعلى","B الأقل","مقارنة الدورة بين A وC","مقارنة المجموعة بين A وB"]'::jsonb, '[]'::jsonb, '[{"element":"تحديد الأعلى والأقل","marks":2},{"element":"مقارنة الدورة","marks":1},{"element":"مقارنة المجموعة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تحديد صحيح بمقارنتين معللتين"},{"level":"2–3 درجات","description":"تحديد صحيح بمقارنة واحدة"},{"level":"1 درجة","description":"تحديد أحدهما فقط"},{"level":"صفر","description":"لا إجابة صحيحة"}]'::jsonb, '["تطبيق قاعدة المجموعة على عنصرين من دورة واحدة","اختيار B الأعلى لأن عدده الذري أكبر"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-11T13:13:22.210Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(651, 2, 'نزولًا في المجموعة يزداد عدد المستويات فيكبر الحجم وتبتعد إلكترونات التكافؤ عن النواة ويزداد الحجب، فيضعف جذبها ويسهل نزعها.', '["الشحنة النووية تزداد نزولًا في المجموعة لا تقل.","عدد إلكترونات التكافؤ ثابت في المجموعة الواحدة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (46%)"}],"at":"2026-10-11T13:13:22.213Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(652, 0, 'تزداد الإلكترونات الداخلية نزولًا فيزداد حجبها لإلكترونات التكافؤ عن النواة، فيضعف الجذب وتقل طاقة التأين.', '["","الحجب يزداد نزولًا لا يقل لأن الإلكترونات الداخلية تزداد.","زيادة الحجب تضعف الجذب ولا تقويه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-11T13:13:22.213Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(653, 1, 'كلما زاد نصف القطر ابتعد إلكترون التكافؤ عن النواة وضعف جذبه فقلّت الطاقة اللازمة لنزعه.', '["زيادة البعد عن النواة تسهل نزع الإلكترون فتقل الطاقة لا تزيد.","","نصف القطر يؤثر مباشرة في قوة جذب النواة لإلكترون التكافؤ."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-11T13:13:22.214Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(654, 2, 'C في الدورة الثانية وGe في الرابعة، فإلكترونات تكافؤ Ge أبعد عن النواة ومحجوبة بعدد أكبر من الإلكترونات الداخلية فيسهل نزعها.', '["لكليهما أربعة إلكترونات تكافؤ لأنهما في المجموعة 14.","شحنة نواة Ge (32) أكبر من شحنة نواة C (6).",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-11T13:13:22.214Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(655, 0, 'نصف القطر يزداد من Be (112) إلى Sr (215 pm) بينما تقل طاقة التأين من 899 إلى 549 kJ/mol، فالعلاقة عكسية.', '["","البيانات تبين أن طاقة التأين تقل مع زيادة نصف القطر.","قيم طاقة التأين في الجدول مختلفة وتتناقص."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-11T13:13:22.214Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(656, 1, 'زيادة عدد المستويات تبعد إلكترونات التكافؤ وتزيد الحجب، وهذان الأثران أقوى من أثر زيادة عدد البروتونات، فيضعف الجذب وتقل طاقة التأين.', '["عدد البروتونات يزداد نزولًا في المجموعة.","","عدد إلكترونات التكافؤ ثابت في المجموعة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-11T13:13:22.214Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(657, 2, 'صحيح أن شحنة نواة K أكبر، لكن إلكترون تكافئه في المستوى الرابع ويحجبه 18 إلكترونًا داخليًا مقابل 10 في Na، فجذبه أضعف وطاقة تأين K أقل.', '["K (Z = 19) له بروتونات أكثر من Na (Z = 11).","لكل منهما إلكترون تكافؤ واحد في المجموعة 1.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-11T13:13:22.215Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(658, null, null, null, 'لأنه بالنزول في المجموعة يزداد عدد مستويات الطاقة الرئيسية فيزداد الحجم الذري وتبتعد إلكترونات التكافؤ عن النواة، كما يزداد عدد الإلكترونات الداخلية التي تحجبها عن النواة. ومع أن الشحنة النووية تزداد، فإن أثر البعد والحجب هو الغالب، فيضعف جذب النواة لإلكترونات التكافؤ ويسهل نزعها، فتقل الطاقة اللازمة لذلك.', '["زيادة عدد المستويات والحجم","بعد إلكترونات التكافؤ","زيادة الحجب","ضعف الجذب وسهولة النزع"]'::jsonb, '[]'::jsonb, '[{"element":"زيادة الحجم وبعد الإلكترونات","marks":1},{"element":"زيادة الحجب","marks":1},{"element":"ضعف الجذب ونقص الطاقة اللازمة","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"تعليل كامل"},{"level":"2 درجة","description":"ذكر البعد وضعف الجذب دون الحجب"},{"level":"1 درجة","description":"ذكر زيادة الحجم فقط"},{"level":"صفر","description":"تعليل خاطئ كنقص الشحنة النووية"}]'::jsonb, '["التعليل بنقص الشحنة النووية","التعليل بزيادة إلكترونات التكافؤ"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (46%)"}],"at":"2026-10-11T13:13:22.215Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(659, null, null, null, 'Na: 1s² 2s² 2p⁶ 3s¹ ، K: 1s² 2s² 2p⁶ 3s² 3p⁶ 4s¹. كلاهما في المجموعة 1. طاقة تأين K أقل؛ لأن إلكترون تكافئه في المستوى الرابع (4s¹) الأبعد عن النواة، ويحجبه 18 إلكترونًا داخليًا مقابل 10 في Na، فيضعف جذب النواة له ويسهل نزعه رغم أن شحنة نواته أكبر.', '["توزيع Na","توزيع K","K أقل طاقة تأين","التفسير بالبعد والحجب"]'::jsonb, '[]'::jsonb, '[{"element":"التوزيعان","marks":2},{"element":"التحديد","marks":1},{"element":"التفسير","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"جميع العناصر صحيحة"},{"level":"3–4 درجات","description":"تحديد صحيح مع تفسير ناقص"},{"level":"1–2 درجة","description":"التوزيعان فقط"},{"level":"صفر","description":"لا إجابة صحيحة"}]'::jsonb, '["اختيار Na أقل لأن شحنة نواته أقل"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-11T13:13:22.215Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(660, null, null, null, 'نشاط فلزات المجموعة 1 يعتمد على سهولة فقدها لإلكترون التكافؤ الوحيد. وكلما نزلنا في المجموعة تقل طاقة التأين لأن نصف القطر يزداد وتبتعد إلكترونات التكافؤ عن النواة ويزداد الحجب فيضعف الجذب. لذلك يفقد Cs إلكترونه بسهولة أكبر من Li (طاقة تأينه أقل)، فيكون أنشط كيميائيًا.', '["النشاط مرتبط بسهولة فقد الإلكترون","طاقة التأين تقل نزولًا","سبب النقص: البعد والحجب","Cs أقل طاقة تأين فهو أنشط"]'::jsonb, '[]'::jsonb, '[{"element":"الربط بين النشاط وفقد الإلكترون","marks":1},{"element":"تدرج طاقة التأين وتعليله","marks":2},{"element":"الاستنتاج حول Cs وLi","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تفسير كامل مترابط"},{"level":"2–3 درجات","description":"تفسير صحيح دون تعليل نقص طاقة التأين"},{"level":"1 درجة","description":"ذكر أن Cs طاقة تأينه أقل فقط"},{"level":"صفر","description":"لا إجابة صحيحة"}]'::jsonb, '["الربط بين النشاط وطاقة التأين المرتفعة","إغفال سبب نقص طاقة التأين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-10-11T13:13:22.215Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(661, 1, 'القاعدة الثمانية: تميل الذرات إلى فقد الإلكترونات أو اكتسابها أو المشاركة بها للحصول على ثمانية إلكترونات تكافؤ، أي توزيع الغاز النبيل.', '["القاعدة تتعلق بإلكترونات التكافؤ لا بعدد البروتونات، والبروتونات لا تتغير في التفاعلات.","","أقصى عدد للمستويات المشغولة في الجدول سبعة، والقاعدة تخص إلكترونات المستوى الخارجي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-11T13:13:22.218Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(662, 0, 'الغازات النبيلة (عدا الهيليوم) مستواها الخارجي ns² np⁶ بثمانية إلكترونات، وهو التوزيع المستقر الذي تسعى إليه الذرات.', '["","ns² فيه إلكترونان فقط، وهو توزيع عناصر المجموعة 2 النشطة.","ns¹ توزيع الفلزات القلوية وهي من أنشط العناصر لا أكثرها استقرارًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-11T13:13:22.219Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(663, 2, 'Na⁺ فيه 10 إلكترونات بتوزيع 1s² 2s² 2p⁶ وهو توزيع النيون.', '["الأرجون فيه 18 إلكترونًا، وهو يماثل Cl⁻ لا Na⁺.","الهيليوم فيه إلكترونان فقط (1s²).",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (56%)"}],"at":"2026-10-11T13:13:22.219Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(664, 1, 'Cl⁻ فيه 18 إلكترونًا بتوزيع 1s² 2s² 2p⁶ 3s² 3p⁶، وهو توزيع الأرجون الذي يلي الكلور في الدورة نفسها.', '["النيون فيه 10 إلكترونات، والكلور يحتاج إلى فقد 7 إلكترونات ليشبهه، وهذا لا يحدث.","","الكريبتون فيه 36 إلكترونًا وهو في الدورة الرابعة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (56%)"}],"at":"2026-10-11T13:13:22.219Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(665, 0, 'للكبريت 6 إلكترونات تكافؤ، فالأسهل أن يكتسب إلكترونين ليصل إلى ثمانية، فيتكون الأيون S²⁻.', '["","فقد 6 إلكترونات أصعب كثيرًا من اكتساب إلكترونين، فاللافلزات تميل إلى الاكتساب.","فقد إلكترونين لا يوصله إلى ثمانية إلكترونات تكافؤ."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-11T13:13:22.219Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(666, 2, 'المستوى الأول لا يتسع إلا لإلكترونين، فالهيليوم مستقر بإلكترونين (وكذلك يستقر الهيدروجين بإلكترونين)، وهذا استثناء من القاعدة الثمانية.', '["المستوى الأول لا يتسع لأكثر من إلكترونين.","فقد الإلكترونين لا يعطي ثمانية إلكترونات، والهيليوم مستقر أصلًا.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-11T13:13:22.220Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(667, 1, 'هوية العنصر يحددها عدد البروتونات (11 في Na⁺)، فتشابه التوزيع مع النيون لا يحوله إلى نيون، ويبقى أيونًا موجبًا.', '["النيون له 10 بروتونات بينما Na⁺ له 11؛ التوزيع وحده لا يحدد العنصر.","","Na⁺ يحمل شحنة 1+ لأن بروتوناته أكثر من إلكتروناته بواحد."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-11T13:13:22.220Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(668, null, null, null, 'القاعدة الثمانية: تميل الذرات إلى فقد الإلكترونات أو اكتسابها أو المشاركة بها لتحصل على ثمانية إلكترونات تكافؤ (توزيع الغاز النبيل ns² np⁶). الفلزات تميل إلى فقد إلكترونات تكافئها مكونة أيونات موجبة، مثل Na → Na⁺ الذي يشبه توزيعه النيون. اللافلزات تميل إلى اكتساب الإلكترونات مكونة أيونات سالبة، مثل Cl → Cl⁻ الذي يشبه توزيعه الأرجون.', '["نص القاعدة","الفلزات تفقد ← أيونات موجبة","مثال فلز","اللافلزات تكتسب ← أيونات سالبة","مثال لافلز"]'::jsonb, '[]'::jsonb, '[{"element":"نص القاعدة","marks":2},{"element":"تطبيق الفلزات مع مثال","marks":1},{"element":"تطبيق اللافلزات مع مثال","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"نص صحيح وتطبيقان بمثالين"},{"level":"2–3 درجات","description":"نص صحيح مع تطبيق واحد"},{"level":"1 درجة","description":"نص ناقص فقط"},{"level":"صفر","description":"لا إجابة صحيحة"}]'::jsonb, '["إغفال المشاركة بالإلكترونات في النص","عكس سلوك الفلزات واللافلزات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-11T13:13:22.220Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(669, null, null, null, '(أ) Ca: 1s² 2s² 2p⁶ 3s² 3p⁶ 4s² ، O: 1s² 2s² 2p⁴. (ب) الكالسيوم يفقد إلكتروني 4s² فيتكون Ca²⁺، والأكسجين يكتسب إلكترونين فيتكون O²⁻. (ج) Ca²⁺ (18 إلكترونًا) يشبه الأرجون Ar، وO²⁻ (10 إلكترونات) يشبه النيون Ne.', '["التوزيعان","Ca يفقد 2 → Ca²⁺","O يكتسب 2 → O²⁻","Ca²⁺ يشبه Ar","O²⁻ يشبه Ne"]'::jsonb, '["Ca: 20 − 2 = 18 إلكترونًا ← توزيع Ar","O: 8 + 2 = 10 إلكترونات ← توزيع Ne"]'::jsonb, '[{"element":"(أ) التوزيعان","marks":2},{"element":"(ب) الأيونان","marks":2},{"element":"(ج) الغازان النبيلان","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"جميع الأجزاء صحيحة"},{"level":"4–5 درجات","description":"خطأ في عنصر واحد"},{"level":"2–3 درجات","description":"التوزيعان مع أيون واحد"},{"level":"1 درجة","description":"توزيع واحد صحيح"},{"level":"صفر","description":"لا إجابة صحيحة"}]'::jsonb, '["كتابة O²⁺ أو Ca²⁻","اعتبار Ca²⁺ يشبه Ne"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-11T13:13:22.221Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(670, null, null, null, '(أ) الغازات النبيلة (عدا الهيليوم) مستواها الخارجي ممتلئ بثمانية إلكترونات (ns² np⁶)، أي أنها حققت التركيب الثماني أصلًا، فلا تميل إلى فقد الإلكترونات أو اكتسابها أو المشاركة بها، فتكون مستقرة قليلة النشاط (والهيليوم مستقر بإلكترونين يملآن مستواه الأول). (ب) لأن نزع إلكترون منها يُفسد هذا التركيب المستقر، كما أن شحنة نواتها هي الأكبر في دورتها، فيلزم طاقة كبيرة جدًا لنزع الإلكترون.', '["امتلاء المستوى الخارجي بثمانية إلكترونات","عدم الميل للفقد أو الاكتساب","استثناء الهيليوم","نزع الإلكترون يفسد التركيب المستقر","أكبر شحنة نووية في الدورة"]'::jsonb, '[]'::jsonb, '[{"element":"(أ) تفسير الاستقرار","marks":2},{"element":"استثناء الهيليوم","marks":1},{"element":"(ب) تفسير ارتفاع طاقة التأين","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"تفسير كامل للجزأين مع الاستثناء"},{"level":"3–4 درجات","description":"تفسير الجزأين مع نقص بسيط"},{"level":"1–2 درجة","description":"تفسير جزء واحد"},{"level":"صفر","description":"لا إجابة صحيحة"}]'::jsonb, '["القول إن الغازات النبيلة لا تحتوي على إلكترونات تكافؤ","تعميم الثمانية على الهيليوم"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-11T13:13:22.221Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(671, 0, 'الكهروسالبية قابلية (قدرة) ذرات العنصر على جذب الإلكترونات المشتركة في الرابطة الكيميائية.', '["","هذا تعريف طاقة التأين.","هذا تعريف نصف قطر ذرة اللافلز."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-11T13:13:22.224Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(672, 2, 'الفلور هو أعلى العناصر كهروسالبية، فهو أقوى الذرات جذبًا لإلكترونات الرابطة.', '["الأكسجين يلي الفلور في الكهروسالبية لكنه أقل منه.","الكلور كهروسالبيته عالية لكنها أقل من الفلور والأكسجين.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-10-11T13:13:22.224Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(673, 1, 'الكلور أعلى كهروسالبية من الهيدروجين، فيجذب إلكترونات الرابطة نحوه أكثر ويحمل δ⁻، بينما يحمل H الشحنة δ⁺.', '["الذرة الأقل كهروسالبية تحمل δ⁺ لا δ⁻.","","اختلاف الكهروسالبية بين H وCl يجعل الرابطة قطبية ذات شحنات جزئية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-11T13:13:22.225Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(674, 0, 'أكبر قيمة كهروسالبية في الجدول للأكسجين (3.4)، فهو الأقوى جذبًا لإلكترونات الرابطة.', '["","كهروسالبية N (3.0) أقل من O.","كهروسالبية S (2.5) أقل من O وN."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-11T13:13:22.225Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(675, 2, 'الكهروسالبية تُعرّف للذرة داخل رابطة كيميائية، وتصف قدرتها على جذب الإلكترونات المشتركة فيها.', '["الذرة المنفردة الغازية تخص تعريف طاقة التأين.","التعريف لا يشترط أن تكون الذرة أيونًا.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-11T13:13:22.225Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(676, 1, 'الكهروسالبية المنخفضة (مثل Na = 0.9) صفة الفلزات التي تجذب إلكترونات الرابطة بضعف وتميل إلى فقد الإلكترونات.', '["اللافلزات كهروسالبيتها مرتفعة (مثل O = 3.4).","","الغازات النبيلة لا تُعيَّن لها قيم كهروسالبية أصلًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-11T13:13:22.225Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(677, 0, 'إلكترونات الرابطة تنزاح نحو الذرة الأعلى كهروسالبية، وهي الكلور (3.1 > 2.9).', '["","البروم أقل كهروسالبية فيجذب إلكترونات الرابطة بدرجة أقل.","التوزيع المتساوي يحدث بين ذرتين متساويتين في الكهروسالبية فقط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-10-11T13:13:22.225Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(678, null, null, null, 'الكهروسالبية: قدرة ذرة العنصر على جذب الإلكترونات في الرابطة الكيميائية. الفرق: الكهروسالبية تخص ذرة مرتبطة بذرة أخرى في رابطة، وتقيس قدرتها على جذب إلكترونات الرابطة المشتركة، وليس لها وحدة. أما طاقة التأين فتخص ذرة منفردة في الحالة الغازية، وتقيس الطاقة اللازمة لنزع إلكترون منها (بوحدة kJ/mol).', '["تعريف الكهروسالبية","الكهروسالبية: ذرة في رابطة","طاقة التأين: ذرة منفردة غازية","ما تقيسه كل منهما"]'::jsonb, '[]'::jsonb, '[{"element":"التعريف","marks":1},{"element":"الفرق في حالة الذرة","marks":1},{"element":"الفرق فيما تقيسه","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"تعريف صحيح وفرقان واضحان"},{"level":"2–3 درجات","description":"تعريف صحيح مع فرق واحد"},{"level":"1 درجة","description":"التعريف فقط"},{"level":"صفر","description":"لا إجابة صحيحة"}]'::jsonb, '["الخلط بين الكهروسالبية وطاقة التأين","إغفال كلمة «في الرابطة الكيميائية»"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-11T13:13:22.226Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(679, null, null, null, '(أ) O > Cl > N > Na. (ب) الصوديوم؛ لأن كهروسالبيته منخفضة جدًا (0.9) فجذبه للإلكترونات ضعيف، وهو فلز يميل إلى فقد إلكترون تكافئه. (ج) ذرة O تحمل δ⁻ لأن كهروسالبيتها (3.4) أكبر من N (3.0)، فتنزاح إلكترونات الرابطة نحوها.', '["الترتيب O > Cl > N > Na","Na يميل إلى فقد الإلكترونات","التعليل بانخفاض الكهروسالبية","O تحمل δ⁻ مع التعليل"]'::jsonb, '[]'::jsonb, '[{"element":"(أ) الترتيب","marks":1},{"element":"(ب) التحديد والتعليل","marks":2},{"element":"(ج) الشحنة الجزئية","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"جميع الأجزاء صحيحة"},{"level":"2–3 درجات","description":"خطأ في جزء"},{"level":"1 درجة","description":"الترتيب فقط"},{"level":"صفر","description":"لا إجابة صحيحة"}]'::jsonb, '["وضع δ⁻ على الذرة الأقل كهروسالبية","الترتيب تصاعديًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-11T13:13:22.227Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(680, null, null, null, 'الفلور أعلى كهروسالبية من الهيدروجين، فيجذب الإلكترونات المشتركة في الرابطة نحوه أكثر، فتصبح الكثافة الإلكترونية عند الفلور أكبر فيحمل شحنة جزئية سالبة δ⁻، وتقل الكثافة الإلكترونية عند الهيدروجين فيحمل شحنة جزئية موجبة δ⁺. وهي شحنات جزئية لا كاملة لأن الإلكترونات لا تنتقل كليًا بل تنزاح فقط.', '["F أعلى كهروسالبية","انزياح إلكترونات الرابطة نحو F","F: δ⁻ و H: δ⁺","الشحنة جزئية لأن الإلكترونات تنزاح ولا تنتقل كليًا"]'::jsonb, '[]'::jsonb, '[{"element":"مقارنة الكهروسالبية","marks":1},{"element":"انزياح الإلكترونات","marks":1},{"element":"تحديد δ⁺ وδ⁻","marks":1},{"element":"سبب كون الشحنة جزئية","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تفسير كامل"},{"level":"2–3 درجات","description":"تحديد صحيح للشحنات مع تفسير ناقص"},{"level":"1 درجة","description":"تحديد الشحنات فقط"},{"level":"صفر","description":"عكس الشحنات أو لا إجابة"}]'::jsonb, '["وضع δ⁻ على الهيدروجين","اعتبار الرابطة أيونية بانتقال كامل للإلكترون"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-11T13:13:22.228Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(681, 2, 'في الدورة تزداد الشحنة النووية ويقل نصف القطر، فتزداد قدرة الذرة على جذب إلكترونات الرابطة، أي تزداد الكهروسالبية.', '["الكهروسالبية تقل نزولًا في المجموعة لا في الدورة.","تغير الشحنة النووية ونصف القطر في الدورة يغير الكهروسالبية.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-10-11T13:13:22.231Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(682, 0, 'الكهروسالبية تزداد في الدورة من اليسار إلى اليمين، والكلور (المجموعة 17) يقع يمين المغنيسيوم (المجموعة 2).', '["","الوقوع يسار الدورة يعني كهروسالبية أقل.","الوقوع في دورة واحدة لا يعني تساوي الكهروسالبية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-10-11T13:13:22.231Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(683, 1, 'الكهروسالبية تقل في المجموعة من الأعلى إلى الأسفل، والأكسجين أعلى من السيلينيوم.', '["الوقوع أسفل المجموعة يعني كهروسالبية أقل.","","عناصر المجموعة الواحدة تختلف في الكهروسالبية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-10-11T13:13:22.231Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(684, 0, 'في الدورة تزداد الكهروسالبية نحو اليمين: N (المجموعة 15) ثم O (16) ثم F (17)، وهو ما يوافق ترتيب المذكرة F > O > N.', '["","هذا ترتيب تنازلي (معكوس).","O يقع يمين N فكهروسالبيته أكبر منه لا أقل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-10-11T13:13:22.232Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(685, 2, 'A وB في المجموعة 17 وA أعلى (الدورة 2) فهو أعلى كهروسالبية من B. وA وC في الدورة 2 وA يمين C فهو أعلى منه أيضًا.', '["B يقع أسفل A في المجموعة نفسها فكهروسالبيته أقل.","C في المجموعة 1 يسار الدورة فكهروسالبيته منخفضة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-11T13:13:22.232Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(686, 1, 'البوتاسيوم في المجموعة 1 وأسفل الصوديوم، والكهروسالبية تقل نزولًا في المجموعة وتكون منخفضة في يسار الجدول، فهو الأقل.', '["Na يقع فوق K في المجموعة 1 فكهروسالبيته أعلى قليلًا.","","Cl لافلز في المجموعة 17 كهروسالبيته مرتفعة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-11T13:13:22.232Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(687, 0, 'في الدورة يقل نصف القطر وتزداد طاقة التأين والكهروسالبية، وفي المجموعة يحدث العكس، كما في تلخيص المذكرة.', '["","نصف القطر يقل في الدورة لا يزداد.","الكهروسالبية تزداد في الدورة لا تقل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-10-11T13:13:22.232Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(688, null, null, null, 'الترتيب: Na < Mg < S < Cl. التفسير: العناصر في الدورة نفسها، وبالانتقال يمينًا تزداد الشحنة النووية ويقل نصف القطر، فتزداد قدرة الذرة على جذب إلكترونات الرابطة، أي تزداد الكهروسالبية.', '["الترتيب Na < Mg < S < Cl","العناصر في دورة واحدة","زيادة الشحنة ونقص نصف القطر","زيادة جذب إلكترونات الرابطة"]'::jsonb, '[]'::jsonb, '[{"element":"الترتيب","marks":2},{"element":"التفسير","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"ترتيب صحيح وتفسير كامل"},{"level":"2–3 درجات","description":"ترتيب صحيح مع تفسير ناقص"},{"level":"1 درجة","description":"ترتيب معكوس"},{"level":"صفر","description":"لا إجابة صحيحة"}]'::jsonb, '["الترتيب تنازليًا","تفسير الزيادة بزيادة نصف القطر"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-10-11T13:13:22.232Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(689, null, null, null, '(أ) Cl أعلى كهروسالبية من Mg؛ لأنهما في الدورة الثالثة وCl يقع يمين Mg، فشحنة نواته أكبر ونصف قطره أصغر فيجذب إلكترونات الرابطة بقوة أكبر. (ب) O أعلى كهروسالبية من Se؛ لأنهما في المجموعة 16 وO يقع أعلى Se، فنصف قطره أصغر وإلكتروناته الخارجية أقرب إلى النواة فيكون جذبه لإلكترونات الرابطة أقوى.', '["Cl > Mg","تعليل بتدرج الدورة","O > Se","تعليل بتدرج المجموعة"]'::jsonb, '[]'::jsonb, '[{"element":"(أ) المقارنة والتعليل","marks":2},{"element":"(ب) المقارنة والتعليل","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"المقارنتان صحيحتان ومعللتان"},{"level":"2–3 درجات","description":"مقارنتان صحيحتان بتعليل ناقص"},{"level":"1 درجة","description":"مقارنة واحدة صحيحة"},{"level":"صفر","description":"لا إجابة صحيحة"}]'::jsonb, '["اختيار Se لأن عدده الذري أكبر"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-11T13:13:22.233Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(690, null, null, null, 'في الدورة: نصف القطر يقل، وطاقة التأين تزداد، والكهروسالبية تزداد. في المجموعة: نصف القطر يزداد، وطاقة التأين تقل، والكهروسالبية تقل. العلاقة عكسية: كلما صغر نصف القطر اقتربت إلكترونات الرابطة من النواة فزاد جذبها لها وزادت الكهروسالبية.', '["تدرجات الدورة الثلاثة","تدرجات المجموعة الثلاثة","العلاقة العكسية بين نصف القطر والكهروسالبية","تعليل العلاقة"]'::jsonb, '[]'::jsonb, '[{"element":"تدرجات الدورة","marks":2},{"element":"تدرجات المجموعة","marks":2},{"element":"العلاقة وتعليلها","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"الجدول كاملًا مع العلاقة معللة"},{"level":"4–5 درجات","description":"خطأ واحد في الجدول أو نقص في التعليل"},{"level":"2–3 درجات","description":"نصف الجدول صحيح"},{"level":"1 درجة","description":"خانة أو خانتان صحيحتان"},{"level":"صفر","description":"لا إجابة صحيحة"}]'::jsonb, '["جعل الكهروسالبية تزداد في المجموعة","اعتبار العلاقة طردية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-11T13:13:22.233Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(691, 2, 'بفقد إلكترون 3s¹ يصبح توزيع Na⁺ مثل النيون (ثمانية إلكترونات في المستوى الخارجي)، وهو تركيب مستقر.', '["فقد الإلكترونات لا يغير عدد البروتونات.","فقد الإلكترون يقلل عدد المستويات المشغولة ولا يزيدها.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-11T13:13:22.236Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(692, 0, 'فلزات المجموعتين 1 و2 أنشط الفلزات لأنها تفقد إلكترونات تكافئها القليلة بسهولة لتصل إلى توزيع الغاز النبيل.', '["","عناصر المجموعة 17 تميل إلى اكتساب إلكترون لا فقده.","الغازات النبيلة مستقرة لا تميل إلى فقد الإلكترونات أو اكتسابها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (44%)"}],"at":"2026-10-11T13:13:22.236Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(693, 1, 'للوصول إلى التركيب الثماني يكفي الصوديوم أن يفقد إلكترونًا واحدًا، وهذا أسهل بكثير من اكتساب سبعة إلكترونات.', '["النواة تجذب الإلكترونات دائمًا، لكن اكتساب سبعة منها صعب جدًا.","","اكتساب الإلكترونات أو فقدها لا يغير عدد البروتونات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-11T13:13:22.236Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(694, 2, 'الفلزات القلوية لها أقل طاقات تأين في دوراتها، فنزع إلكترون تكافئها الوحيد يحتاج طاقة قليلة.', '["كهروسالبية الفلزات القلوية منخفضة لا مرتفعة.","الفلزات القلوية لها أكبر أنصاف أقطار في دوراتها.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-11T13:13:22.237Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(695, 0, 'للألومنيوم 3 إلكترونات تكافؤ، فيفقدها ليصل إلى توزيع النيون، فيتكون Al³⁺ كما في نمط الجدول (+1، +2، +3).', '["","الشحنة السالبة تنتج عن اكتساب الإلكترونات، والألومنيوم فلز يفقدها.","اكتساب 5 إلكترونات أصعب كثيرًا من فقد 3."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-11T13:13:22.237Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(696, 1, 'بفقد إلكتروني 3s² يصبح Mg²⁺ بتوزيع 1s² 2s² 2p⁶ أي توزيع النيون، بثمانية إلكترونات في المستوى الخارجي الجديد (الثاني).', '["الوصول إلى توزيع الأرجون يتطلب اكتساب ستة إلكترونات وهذا لا يحدث.","","بعد فقد الإلكترونين يصبح المستوى الثالث فارغًا لا ممتلئًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-10-11T13:13:22.237Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(697, 2, 'في المجموعة 1 تقل طاقة التأين نزولًا، والبوتاسيوم أسفل الخيارات فطاقة تأينه الأقل وميله لفقد الإلكترون الأكبر.', '["Na أعلى من K فطاقة تأينه أكبر وميله أقل.","Li أعلى المجموعة فهو الأقل ميلًا بين الخيارات.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (44%)"}],"at":"2026-10-11T13:13:22.237Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(698, null, null, null, 'لأن لكل منها إلكترون تكافؤ واحدًا (ns¹)، وبفقده تصل إلى توزيع الغاز النبيل الذي يسبقها (التركيب الثماني المستقر). كما أن طاقة تأينها منخفضة (أقل طاقات التأين في دوراتها) فيسهل نزع هذا الإلكترون، ويكون فقد إلكترون واحد أسهل بكثير من اكتساب سبعة. لذلك تتكون أيونات موجبة شحنتها 1+ مثل Na⁺ وK⁺.', '["إلكترون تكافؤ واحد ns¹","الوصول إلى توزيع الغاز النبيل","انخفاض طاقة التأين","فقد إلكترون أسهل من اكتساب سبعة","الشحنة 1+"]'::jsonb, '[]'::jsonb, '[{"element":"التكافؤ والوصول إلى التركيب الثماني","marks":2},{"element":"انخفاض طاقة التأين","marks":1},{"element":"الشحنة 1+ مع مثال","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تعليل كامل بالتركيب الثماني وطاقة التأين"},{"level":"2–3 درجات","description":"تعليل بعامل واحد كامل"},{"level":"1 درجة","description":"ذكر الشحنة فقط"},{"level":"صفر","description":"تعليل خاطئ"}]'::jsonb, '["التعليل بارتفاع الكهروسالبية","كتابة الشحنة 1−"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-11T13:13:22.237Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(699, null, null, null, '(أ) 1s² 2s² 2p⁶ 3s² 3p⁶ 4s². (ب) يفقد إلكترونين (4s²) فيتكون Ca²⁺. (ج) لأن فقد إلكترونين أسهل كثيرًا من اكتساب ستة إلكترونات للوصول إلى ثمانية، وطاقة تأينه منخفضة نسبيًا. ويصبح توزيع Ca²⁺: 1s² 2s² 2p⁶ 3s² 3p⁶ (18 إلكترونًا) مثل الأرجون Ar.', '["التوزيع الصحيح","فقد إلكترونين","Ca²⁺","فقد 2 أسهل من اكتساب 6","يشبه الأرجون"]'::jsonb, '["Ca: 20 إلكترونًا ← يفقد 2 → 18 إلكترونًا = توزيع Ar"]'::jsonb, '[{"element":"(أ) التوزيع","marks":1},{"element":"(ب) العدد والرمز","marks":2},{"element":"(ج) التفسير والغاز النبيل","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"جميع الأجزاء صحيحة"},{"level":"3–4 درجات","description":"خطأ في جزء واحد"},{"level":"1–2 درجة","description":"التوزيع فقط أو الرمز فقط"},{"level":"صفر","description":"لا إجابة صحيحة"}]'::jsonb, '["كتابة Ca²⁻","اعتبار أيونه يشبه النيون"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-11T13:13:22.238Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(700, null, null, null, 'الصوديوم (2، 8، 1) له إلكترون تكافؤ واحد وطاقة تأين منخفضة، فيسهل عليه فقده فيتكون Na⁺ بتوزيع النيون. الكلور (2، 8، 7) له سبعة إلكترونات تكافؤ وكهروسالبيته وطاقة تأينه مرتفعتان، فيسهل عليه اكتساب إلكترون واحد فيتكون Cl⁻ بتوزيع الأرجون. فكل منهما يسلك الطريق الأقل طاقة: Na يفقد إلكترونًا واحدًا بدل اكتساب سبعة، وCl يكتسب إلكترونًا واحدًا بدل فقد سبعة.', '["Na: إلكترون تكافؤ واحد وطاقة تأين منخفضة ← يفقد","Cl: سبعة إلكترونات تكافؤ ← يكتسب","Na⁺ يشبه Ne وCl⁻ يشبه Ar","مبدأ الطريق الأسهل (الأقل عددًا من الإلكترونات)"]'::jsonb, '[]'::jsonb, '[{"element":"سلوك Na وتفسيره","marks":2},{"element":"سلوك Cl وتفسيره","marks":2},{"element":"الغازان النبيلان","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"مقارنة كاملة مفسرة"},{"level":"3–4 درجات","description":"مقارنة صحيحة مع نقص في التفسير"},{"level":"1–2 درجة","description":"وصف سلوك عنصر واحد"},{"level":"صفر","description":"لا إجابة صحيحة"}]'::jsonb, '["عكس سلوك العنصرين","القول إن الكلور يفقد سبعة إلكترونات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-11T13:13:22.238Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(701, 1, 'الكهروسالبية تقيس جذب الذرة لإلكترونات الرابطة، والغازات النبيلة مستواها الخارجي ممتلئ فنادرًا ما تكوّن روابط، فلا تتوافر روابط يقاس فيها هذا الجذب.', '["عدم تعيين قيمة لا يعني أن القيمة صفر؛ هذا مفهوم خاطئ شائع.","","الفلور هو أعلى العناصر كهروسالبية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (40%)"}],"at":"2026-10-11T13:13:22.241Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(702, 0, 'الكهروسالبية قدرة الذرة على جذب الإلكترونات في الرابطة الكيميائية، فإذا لم يكوّن العنصر روابط لم يمكن تعيين قيمة لها.', '["","الذرة المنفردة ترتبط بتعريف طاقة التأين لا الكهروسالبية.","تعريف الكهروسالبية مرتبط بوجود رابطة كيميائية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-11T13:13:22.241Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(703, 2, 'الغازات النبيلة عدا الهيليوم مستواها الخارجي ممتلئ بثمانية إلكترونات (ns² np⁶)، وهذا سبب استقرارها وقلة تكوينها للروابط.', '["ns² np⁵ توزيع الهالوجينات (المجموعة 17).","ns¹ توزيع الفلزات القلوية (المجموعة 1).",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-10-11T13:13:22.242Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(704, 1, 'الأرجون لا يكوّن مركبات عمليًا، فلا تُعيَّن له قيمة كهروسالبية، وعدم تعيين القيمة يختلف عن كونها صفرًا.', '["الأرجون يملك ثمانية إلكترونات تكافؤ (3s² 3p⁶).","","لا تُعيَّن للأرجون قيمة أصلًا، فلا يصح القول إنها أعلى من الكلور."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-11T13:13:22.242Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(705, 0, 'الأرجون غاز نبيل مستواه الخارجي ممتلئ (3s² 3p⁶)، فلا يكاد يكوّن روابط، ولذلك لا تُعيَّن له قيمة كهروسالبية.', '["","عدم الكتابة ليس لصعوبة القياس، بل لعدم وجود روابط يقاس فيها الجذب.","لا تُعيَّن للأرجون قيمة، فلا يمكن مقارنتها بقيمة الصوديوم."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-11T13:13:22.242Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(706, 2, 'المستوى الأول لا يتسع إلا لإلكترونين، فالهيليوم (1s²) مستواه الخارجي ممتلئ ومستقر، ولذلك لا يكوّن مركبات ولا تُعيَّن له كهروسالبية.', '["الهيليوم له إلكترونان فقط لا ثمانية.","الهيليوم لا تُعيَّن له قيمة كهروسالبية أصلًا.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-10-11T13:13:22.242Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(707, 0, 'طاقة التأين تخص ذرة منفردة، أما الكهروسالبية فتخص الذرة في رابطة، والغازات النبيلة نادرًا ما تكوّن روابط فلا تعيَّن لها كهروسالبية.', '["","الكهروسالبية تشترط وجود رابطة، والغازات النبيلة لا تكاد تكوّن روابط.","الفلور هو الأعلى كهروسالبية، ولا تعيَّن للغازات النبيلة قيم."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-11T13:13:22.243Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(708, null, null, null, 'لأن الكهروسالبية هي قدرة الذرة على جذب الإلكترونات في الرابطة الكيميائية، والغازات النبيلة مستواها الخارجي ممتلئ بالإلكترونات (ns² np⁶، والهيليوم 1s²)، فهي مستقرة لا تميل إلى فقد الإلكترونات أو اكتسابها أو المشاركة بها، ولذلك نادرًا ما تكوّن مركبات، فلا توجد روابط يمكن قياس قدرتها على جذب الإلكترونات فيها.', '["تعريف الكهروسالبية مرتبط بالرابطة","امتلاء المستوى الخارجي","الاستقرار وعدم الميل للتفاعل","ندرة تكوين المركبات ← لا روابط تقاس فيها"]'::jsonb, '[]'::jsonb, '[{"element":"الربط بتعريف الكهروسالبية","marks":1},{"element":"امتلاء المستوى والاستقرار","marks":1},{"element":"ندرة الروابط","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"تعليل كامل"},{"level":"2 درجة","description":"ذكر الاستقرار وندرة المركبات دون الربط بالتعريف"},{"level":"1 درجة","description":"ذكر امتلاء المستوى فقط"},{"level":"صفر","description":"القول إن كهروسالبيتها صفر"}]'::jsonb, '["القول إن كهروسالبيتها صفر","القول إنها لا تملك إلكترونات تكافؤ"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-10-11T13:13:22.243Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(709, null, null, null, 'العبارة خاطئة. صحيح أن الكهروسالبية تزداد في الدورة نحو اليمين، لكن هذا التدرج يخص العناصر التي تكوّن روابط. النيون غاز نبيل مستواه الخارجي ممتلئ (2s² 2p⁶) فلا يكوّن مركبات، ولذلك لا تُعيَّن له قيمة كهروسالبية أصلًا. وأعلى عناصر الدورة الثانية كهروسالبية هو الفلور.', '["الحكم بخطأ العبارة","التدرج يخص العناصر المكوّنة للروابط","النيون لا يكوّن مركبات فلا تعين له قيمة","الفلور الأعلى كهروسالبية"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم","marks":1},{"element":"التعليل بعدم تكوين الروابط","marks":2},{"element":"تحديد الفلور","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حكم صحيح معلل مع تحديد الفلور"},{"level":"2–3 درجات","description":"حكم صحيح بتعليل ناقص"},{"level":"1 درجة","description":"الحكم فقط"},{"level":"صفر","description":"الموافقة على العبارة"}]'::jsonb, '["الموافقة على أن النيون الأعلى","الخلط بين طاقة التأين والكهروسالبية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-11T13:13:22.243Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(710, null, null, null, 'لأن بعض الغازات النبيلة الثقيلة مثل الزينون Xe أمكن تحضير عدد قليل من مركباتها، فالقول إنها لا تكوّن مركبات إطلاقًا غير دقيق. ولهذا نقول «معظم» الغازات النبيلة لا تُعيَّن لها قيم كهروسالبية؛ لأن الغازات التي لا تكوّن مركبات (مثل He وNe وAr) لا توجد لها روابط يقاس فيها جذب الإلكترونات، أما ما يكوّن منها مركبات قليلة فيمكن نظريًا تقدير قيمة له.', '["وجود مركبات قليلة لبعض الغازات النبيلة الثقيلة مثل Xe","عدم دقة التعميم المطلق","الربط بكلمة «معظم»","لا روابط ← لا قيمة كهروسالبية"]'::jsonb, '[]'::jsonb, '[{"element":"ذكر مثال Xe وعدم دقة التعميم","marks":2},{"element":"الربط بعبارة «معظم»","marks":1},{"element":"الربط بتعريف الكهروسالبية","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة دقيقة"},{"level":"2–3 درجات","description":"ذكر Xe دون ربط واضح"},{"level":"1 درجة","description":"ذكر أنها مستقرة فقط"},{"level":"صفر","description":"لا إجابة صحيحة"}]'::jsonb, '["القول إن جميع الغازات النبيلة تكوّن مركبات بسهولة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (40%)"}],"at":"2026-10-11T13:13:22.243Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(711, 1, 'الرابطة الكيميائية هي القوة التي تمسك ذرتين (أو أيونين) معًا في المادة.', '["هذا وصف لطاقة التأين وليس للرابطة الكيميائية.","","هذا تعريف إلكترونات التكافؤ وليس الرابطة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-11T13:13:22.246Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(712, 2, 'تميل الذرات إلى الترابط لتصل إلى حالة الاستقرار (أقل طاقة) بالحصول على التركيب الإلكتروني لأقرب غاز نبيل.', '["تكوين الروابط يتعلق بإلكترونات التكافؤ، ولا يتغير عدد البروتونات في التفاعل الكيميائي.","عكس الصحيح؛ الذرات المترابطة أقل طاقة وأكثر استقرارًا من الذرات المنفردة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (36%)"}],"at":"2026-10-11T13:13:22.247Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(713, 0, 'الذرة ذات المستوى الخارجي الممتلئ (كالغازات النبيلة) مستقرة أصلًا، فلا تحتاج إلى فقد إلكترونات أو اكتسابها أو المشاركة بها.', '["","الذرة ذات إلكترون التكافؤ الواحد (مثل Na) نشطة جدًا وتفقده بسهولة لتكوين روابط.","الذرة ذات السبعة إلكترونات (مثل Cl) تميل بشدة إلى اكتساب إلكترون وتكوين روابط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (36%)"}],"at":"2026-10-11T13:13:22.247Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(714, 1, 'توزيع النيون 2,8؛ مستواه الخارجي ممتلئ بثمانية إلكترونات، فهو غاز نبيل مستقر توجد ذراته منفردة.', '["الصوديوم (2,8,1) يفقد إلكترون تكافئه بسهولة، فهو نشط جدًا.","","الكلور (2,8,7) يكتسب إلكترونًا بسهولة، فهو نشط جدًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-11T13:13:22.247Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(715, 0, 'تتكون الروابط بفقد إلكترونات التكافؤ أو اكتسابها أو المشاركة بها، فالإلكترونات الخارجية هي المسؤولة عن الترابط.', '["","عدد البروتونات يحدد نوع العنصر ولا يتغير عند تكوين الرابطة.","النيوترونات في النواة لا تشارك في تكوين الروابط الكيميائية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-10-11T13:13:22.247Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(716, 2, 'A (2,8,1) تميل إلى فقد إلكترون، وD (2,8,7) تميل إلى اكتساب إلكترون، فتتكون بينهما رابطة ويصل كل منهما إلى تركيب الغاز النبيل. أما B (2,8) وC (2,8,8) فمستواهما الخارجي ممتلئ.', '["B وC كلتاهما مستقرتان بمستوى خارجي ممتلئ (غازان نبيلان) فلا تميلان للارتباط.","B مستقرة بمستوى خارجي ممتلئ فلا تكتسب الإلكترون الذي تميل A إلى فقده.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-11T13:13:22.247Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(717, 1, 'Na (2,8,1) يفقد إلكترونًا فيصبح Na⁺ بتوزيع 2,8 يشبه توزيع النيون، لكنه يبقى صوديوم لأن عدد بروتوناته 11.', '["عدد البروتونات (11) لا يتغير، وهو الذي يحدد أن الأيون صوديوم لا نيون.","","فقد الإلكترونات لا يغير عدد البروتونات إطلاقًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-11T13:13:22.248Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(718, null, null, null, 'الرابطة الكيميائية: القوة التي تربط بين ذرتين أو أيونين في المادة. تميل الذرات إلى الترابط لتصل إلى حالة أكثر استقرارًا وأقل طاقة، وذلك بالوصول إلى التوزيع الإلكتروني لأقرب غاز نبيل (ثمانية إلكترونات في المستوى الخارجي — التركيب الثماني). وتتكون الروابط بفقد إلكترونات التكافؤ أو اكتسابها أو المشاركة بها.', '["تعريف الرابطة الكيميائية بأنها قوة تربط ذرتين أو أيونين","التعليل بالوصول إلى حالة الاستقرار (أقل طاقة)","ذكر التركيب الثماني/تركيب الغاز النبيل","ذكر الفقد والاكتساب والمشاركة"]'::jsonb, '[]'::jsonb, '[{"element":"التعريف","marks":1},{"element":"التعليل بالاستقرار وتركيب الغاز النبيل","marks":2},{"element":"طرق تكوين الروابط","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تعريف دقيق وتعليل كامل وذكر الطرق الثلاث"},{"level":"3 درجات","description":"تعريف وتعليل صحيحان مع نقص في الطرق"},{"level":"2 درجتان","description":"تعريف صحيح فقط أو تعليل فقط"},{"level":"1 درجة","description":"إشارة عامة إلى الاستقرار دون تعريف"},{"level":"صفر","description":"لا إجابة أو إجابة خاطئة"}]'::jsonb, '["تعريف الرابطة بأنها «إلكترونات» بدل «قوة تجاذب»","التعليل بزيادة الطاقة بدل نقصها","إغفال المشاركة بالإلكترونات كطريقة لتكوين الرابطة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-10-11T13:13:22.248Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(719, null, null, null, 'لأن مستوى الطاقة الخارجي لذرات الغازات النبيلة ممتلئ بالإلكترونات (8 إلكترونات)، فهي في حالة استقرار أصلًا ولا تحتاج إلى فقد إلكترونات أو اكتسابها أو المشاركة بها. أما الهيليوم فتوزيعه 1s²؛ مستواه الخارجي هو المستوى الأول الذي لا يتسع إلا لإلكترونين، فهو ممتلئ ومستقر.', '["المستوى الخارجي ممتلئ في الغازات النبيلة","الاستقرار يعني عدم الحاجة إلى فقد أو اكتساب أو مشاركة","المستوى الأول يتسع لإلكترونين فقط","الهيليوم مستواه الخارجي ممتلئ بإلكترونين"]'::jsonb, '[]'::jsonb, '[{"element":"تعليل عدم ارتباط الغازات النبيلة","marks":2},{"element":"تفسير استقرار الهيليوم","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"تعليل صحيح للجزأين"},{"level":"3 درجات","description":"تعليل كامل للغازات النبيلة مع تفسير ناقص للهيليوم"},{"level":"2 درجتان","description":"تعليل أحد الجزأين فقط"},{"level":"1 درجة","description":"ذكر «مستقرة» دون تعليل"},{"level":"صفر","description":"لا إجابة أو تعليل خاطئ"}]'::jsonb, '["القول إن جميع الغازات النبيلة لها 8 إلكترونات تكافؤ بما فيها الهيليوم","تعليل الخمول بقلة عدد الإلكترونات","عدم ربط الاستقرار بامتلاء المستوى الخارجي"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-11T13:13:22.248Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(720, null, null, null, '(أ) الأرغون Ar؛ لأن مستواه الخارجي ممتلئ بثمانية إلكترونات فهو مستقر. (ب) Mg تفقد إلكتروني تكافئها، وF تكتسب إلكترونًا واحدًا. (ج) Mg²⁺: 2,8 وF⁻: 2,8، وكلاهما يشبه توزيع النيون Ne.', '["تحديد Ar وتعليل ذلك بامتلاء المستوى الخارجي","Mg تفقد إلكترونين","F تكتسب إلكترونًا","التوزيع 2,8 لكل منهما","تسمية النيون غازًا نبيلًا مشابهًا"]'::jsonb, '[]'::jsonb, '[{"element":"(أ) تحديد Ar مع التعليل","marks":2},{"element":"(ب) سلوك Mg وF","marks":2},{"element":"(ج) التوزيع الناتج والغاز النبيل","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"الأجزاء الثلاثة صحيحة مع التعليل"},{"level":"4–5 درجات","description":"جزآن صحيحان كاملان مع نقص في الثالث"},{"level":"2–3 درجات","description":"جزء واحد صحيح كامل"},{"level":"1 درجة","description":"تحديد Ar فقط دون تعليل"},{"level":"صفر","description":"لا إجابة أو إجابات خاطئة"}]'::jsonb, '["القول إن Mg تكتسب ستة إلكترونات بدل فقد إلكترونين","القول إن F يصل إلى توزيع الأرغون","القول إن Mg تتحول إلى نيون"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-11T13:13:22.249Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(721, 2, 'الكاتيون ذرة أو مجموعة ذرات تحمل شحنة موجبة، مثل Na⁺ وAl³⁺ وNH₄⁺.', '["هذا تعريف الأنيون (الأيون السالب).","فقد النيوترونات لا يكسب الذرة شحنة؛ الشحنة تنتج عن فقد الإلكترونات أو اكتسابها.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-11T13:13:22.252Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(722, 0, 'NH₄⁺ (أيون الأمونيوم) مجموعة ذرات تحمل شحنة موجبة، فهو كاتيون عديد الذرات.', '["","شحنة أيون الفوسفات سالبة فهو أنيون.","أيون الكلوريد سالب الشحنة فهو أنيون."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-11T13:13:22.252Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(723, 1, 'عندما تفقد الذرة إلكترونًا أو أكثر يصبح عدد بروتوناتها أكبر من عدد إلكتروناتها فتحمل شحنة موجبة.', '["اكتساب الإلكترونات يعطي شحنة سالبة فيتكون أنيون.","","عدد البروتونات لا يتغير عند تكوين الأيونات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-11T13:13:22.253Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(724, 2, 'ذرة Al المتعادلة فيها 13 إلكترونًا، وتفقد 3 إلكترونات لتكوين Al³⁺: 13 − 3 = 10 إلكترونات.', '["جُمعت الشحنة إلى العدد الذري (13 + 3)، والصحيح أن الذرة فقدت 3 إلكترونات.","هذا عدد إلكترونات ذرة الألومنيوم المتعادلة قبل فقد الإلكترونات.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-11T13:13:22.254Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(725, 0, 'الكاتيون نتج عن فقد إلكترونات مع بقاء البروتونات ثابتة، فيزيد عدد البروتونات على عدد الإلكترونات وتصبح الشحنة موجبة.', '["","هذه صفة الأنيون الذي اكتسب إلكترونات.","تساوي البروتونات والإلكترونات صفة الذرة المتعادلة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-11T13:13:22.254Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(726, 1, 'عناصر المجموعة 13 لها 3 إلكترونات تكافؤ تفقدها لتكوين كاتيون شحنته +3، فيتكون Al³⁺.', '["Mg في المجموعة 2 فيفقد إلكترونين ويكوّن Mg²⁺.","","S لافلز في المجموعة 16 يكتسب إلكترونين ويكوّن أنيونًا S²⁻."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-11T13:13:22.255Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(727, 2, 'K: 2,8,8,1 يفقد إلكترونًا فيصبح K⁺: 2,8,8 (18 إلكترونًا) مثل توزيع الأرغون.', '["توزيع K⁺ هو 2,8,8 وليس 2,8؛ النيون أقرب غاز نبيل لـ Na⁺ لا لـ K⁺.","الكريبتون يلي البوتاسيوم في الدورة، وK يفقد إلكترونًا ولا يكتسب.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-11T13:13:22.255Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(728, null, null, null, 'الكاتيون: ذرة أو مجموعة ذرات تحمل شحنة موجبة. توزيع Mg: 2,8,2؛ تفقد ذرة المغنيسيوم إلكتروني التكافؤ فتصبح Mg²⁺ بتوزيع 2,8 (يشبه النيون). عدد البروتونات 12 (لا يتغير)، وعدد الإلكترونات 12 − 2 = 10، فالشحنة +2.', '["تعريف الكاتيون","توزيع Mg: 2,8,2","فقد إلكترونين وتكوين Mg²⁺","التوزيع الناتج 2,8","12 بروتونًا و10 إلكترونات"]'::jsonb, '["Mg: 2,8,2","Mg → Mg²⁺ + 2e⁻","عدد الإلكترونات = 12 − 2 = 10","عدد البروتونات = 12"]'::jsonb, '[{"element":"التعريف","marks":1},{"element":"التوزيع وفقد الإلكترونين","marks":2},{"element":"الشحنة وعدد البروتونات والإلكترونات","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"تعريف صحيح وتوضيح كامل بالأعداد الصحيحة"},{"level":"3–4 درجات","description":"تعريف صحيح مع خطأ في عدد الإلكترونات أو التوزيع"},{"level":"1–2 درجة","description":"تعريف فقط أو كتابة الشحنة +2 دون تفسير"},{"level":"صفر","description":"لا إجابة أو إجابة خاطئة"}]'::jsonb, '["كتابة عدد البروتونات 10 ظنًا أنه يتغير","القول إن Mg يكتسب 6 إلكترونات","كتابة الشحنة +1"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-11T13:13:22.255Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(729, null, null, null, 'ذرة Na: 11 بروتونًا، 11 إلكترونًا، متعادلة، التوزيع 2,8,1. أيون Na⁺: 11 بروتونًا، 10 إلكترونات، شحنته +1، التوزيع 2,8. لا يتحول الصوديوم إلى نيون لأن عدد البروتونات (العدد الذري) هو الذي يحدد نوع العنصر، وعدد بروتونات Na⁺ يبقى 11 بينما للنيون 10.', '["البروتونات 11 في الحالتين","الإلكترونات 11 و10","الشحنة صفر و+1","التوزيع 2,8,1 و2,8","التعليل بأن عدد البروتونات يحدد نوع العنصر"]'::jsonb, '[]'::jsonb, '[{"element":"المقارنة (4 نقاط)","marks":4},{"element":"التعليل","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"مقارنة كاملة وتعليل صحيح"},{"level":"4–5 درجات","description":"مقارنة كاملة مع تعليل ناقص، أو خطأ في نقطة واحدة"},{"level":"2–3 درجات","description":"نقطتان أو ثلاث صحيحة في المقارنة دون تعليل"},{"level":"1 درجة","description":"نقطة واحدة صحيحة"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["القول إن عدد بروتونات Na⁺ 10","القول إن Na⁺ أصبح نيونًا لأن توزيعه 2,8","خلط شحنة الأيون بإشارة سالبة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-11T13:13:22.256Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(730, null, null, null, 'K (2,8,8,1) يفقد إلكترونًا → K⁺ وفيه 19 − 1 = 18 إلكترونًا. Ca (2,8,8,2) يفقد إلكترونين → Ca²⁺ وفيه 20 − 2 = 18 إلكترونًا. Li (2,1) يفقد إلكترونًا → Li⁺ وفيه 3 − 1 = 2 إلكترونان. القاعدة: عناصر المجموعة 1 تكوّن كاتيونات +1، والمجموعة 2 كاتيونات +2، والمجموعة 13 كاتيونات +3، أي أن الشحنة تساوي عدد إلكترونات التكافؤ المفقودة.', '["K⁺ و18 إلكترونًا","Ca²⁺ و18 إلكترونًا","Li⁺ وإلكترونان","القاعدة: الشحنة = عدد إلكترونات التكافؤ (+1، +2، +3)"]'::jsonb, '["K: 2,8,8,1 → K⁺: 19 − 1 = 18 e⁻","Ca: 2,8,8,2 → Ca²⁺: 20 − 2 = 18 e⁻","Li: 2,1 → Li⁺: 3 − 1 = 2 e⁻"]'::jsonb, '[{"element":"K⁺","marks":1},{"element":"Ca²⁺","marks":1},{"element":"Li⁺","marks":1},{"element":"القاعدة المستنتجة","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"الأيونات الثلاثة صحيحة بالشحنة وعدد الإلكترونات مع القاعدة"},{"level":"3–4 درجات","description":"أيونان صحيحان مع القاعدة، أو الثلاثة دون قاعدة"},{"level":"1–2 درجة","description":"أيون واحد صحيح"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["جمع الشحنة إلى العدد الذري بدل طرحها","إعطاء Li شحنة +2","عدم ربط الشحنة بإلكترونات التكافؤ"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-11T13:13:22.256Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(731, 1, 'الأنيون ذرة أو مجموعة ذرات تحمل شحنة سالبة، مثل Cl⁻ وS²⁻ وPO₄³⁻.', '["هذا تعريف الكاتيون (الأيون الموجب).","","فقد الإلكترونات يعطي أيونًا موجبًا لا سالبًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-11T13:13:22.260Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(732, 0, 'اللافلز يكتسب إلكترونًا أو أكثر ليصل إلى تركيب الغاز النبيل، فيصبح عدد إلكتروناته أكبر من بروتوناته ويتكون أنيون.', '["","الفلزات تفقد الإلكترونات فتكوّن كاتيونات.","الغازات النبيلة مستقرة ولا تميل إلى اكتساب الإلكترونات أو فقدها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-11T13:13:22.260Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(733, 2, 'الأيونات Cl⁻ وS²⁻ وPO₄³⁻ كلها سالبة الشحنة، فهي أنيونات (الأول والثاني أحاديا الذرة والثالث عديد الذرات).', '["Na⁺ موجب الشحنة فهو كاتيون.","جميع هذه الأيونات موجبة الشحنة (كاتيونات).",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-11T13:13:22.260Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(734, 1, 'تكتسب ذرة S إلكترونين فتصبح S²⁻، ويسمى الأنيون أحادي الذرة بإضافة المقطع «يد»: كبريت → كبريتيد.', '["اكتساب الإلكترونات يعطي شحنة سالبة لا موجبة.","","الكبريتات أيون عديد الذرات يحتوي على أكسجين، ولا ينتج من ذرة كبريت منفردة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-10-11T13:13:22.261Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(735, 0, 'ذرة N فيها 7 إلكترونات، وتكتسب 3 إلكترونات لتكوين N³⁻: 7 + 3 = 10 إلكترونات.', '["","طُرحت الشحنة من العدد الذري (7 − 3)، والصحيح أن الذرة اكتسبت 3 إلكترونات.","هذا عدد إلكترونات ذرة النيتروجين المتعادلة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-11T13:13:22.261Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(736, 2, 'الفوسفور (2,8,5) له 5 إلكترونات تكافؤ، فيكتسب 3 إلكترونات ليصل إلى 8، ويكوّن P³⁻.', '["الكلور له 7 إلكترونات تكافؤ فيكتسب إلكترونًا واحدًا ويكوّن Cl⁻.","الكبريت له 6 إلكترونات تكافؤ فيكتسب إلكترونين ويكوّن S²⁻.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-10-11T13:13:22.261Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(737, 1, 'تكتسب ذرة Cl إلكترونًا واحدًا فيبقى عدد بروتوناتها 17 ويصبح عدد إلكتروناتها 18، وتوزيعه 2,8,8 مثل الأرغون.', '["عدد البروتونات لا يتغير؛ الذي يزداد هو عدد الإلكترونات.","","هذه أعداد أيون موجب فقد إلكترونًا، لا أنيون اكتسب إلكترونًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-11T13:13:22.261Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(738, null, null, null, 'الأنيون: ذرة أو مجموعة ذرات تحمل شحنة سالبة. توزيع F: 2,7؛ تكتسب ذرة الفلور إلكترونًا واحدًا لتكمل ثمانيتها فتصبح F⁻ بتوزيع 2,8. اسمه أيون الفلوريد، ويشبه توزيعه توزيع النيون Ne.', '["تعريف الأنيون","توزيع F: 2,7","اكتساب إلكترون واحد وتكوين F⁻","الاسم: فلوريد","يشبه توزيع النيون"]'::jsonb, '["F: 2,7","F + e⁻ → F⁻","F⁻: 2,8 (10 إلكترونات)"]'::jsonb, '[{"element":"التعريف","marks":1},{"element":"التوزيع واكتساب الإلكترون","marks":2},{"element":"الرمز والاسم","marks":1},{"element":"الغاز النبيل المشابه","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة صحيحة"},{"level":"3–4 درجات","description":"تعريف وتكوين صحيحان مع خطأ في الاسم أو الغاز النبيل"},{"level":"1–2 درجة","description":"تعريف فقط أو رمز F⁻ فقط"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["تسمية الأيون «فلور» بدل «فلوريد»","القول إن الفلور يفقد 7 إلكترونات","اختيار الأرغون غازًا نبيلًا مشابهًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-11T13:13:22.261Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(739, null, null, null, 'N (المجموعة 15، 5 إلكترونات تكافؤ) يكتسب 3 → N³⁻ نيتريد، إلكتروناته 7 + 3 = 10. O (المجموعة 16) يكتسب 2 → O²⁻ أكسيد، إلكتروناته 8 + 2 = 10. Br (المجموعة 17) يكتسب 1 → Br⁻ بروميد، إلكتروناته 35 + 1 = 36. تُحدد الشحنة بعدد الإلكترونات اللازمة لإكمال ثمانية إلكترونات في المستوى الخارجي (8 − عدد إلكترونات التكافؤ) مسبوقة بإشارة سالبة.', '["N³⁻ نيتريد 10 إلكترونات","O²⁻ أكسيد 10 إلكترونات","Br⁻ بروميد 36 إلكترونًا","طريقة تحديد الشحنة: 8 − إلكترونات التكافؤ"]'::jsonb, '["N: 8 − 5 = 3 ← N³⁻ ، 7 + 3 = 10","O: 8 − 6 = 2 ← O²⁻ ، 8 + 2 = 10","Br: 8 − 7 = 1 ← Br⁻ ، 35 + 1 = 36"]'::jsonb, '[{"element":"N³⁻ رمزًا واسمًا وعددًا","marks":1},{"element":"O²⁻ رمزًا واسمًا وعددًا","marks":1},{"element":"Br⁻ رمزًا واسمًا وعددًا","marks":1},{"element":"توضيح طريقة تحديد الشحنة","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"جميع العناصر صحيحة مع التوضيح"},{"level":"3–4 درجات","description":"عنصران صحيحان مع التوضيح أو الثلاثة دونه"},{"level":"1–2 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["طرح الشحنة من العدد الذري بدل جمعها","تسمية O²⁻ «أكسجين»","إعطاء N شحنة +5"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-11T13:13:22.262Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(740, null, null, null, 'الكاتيون: يتكون بفقد إلكترون أو أكثر، تكوّنه الفلزات غالبًا، عدد البروتونات فيه أكبر من الإلكترونات، يُسمى باسم العنصر نفسه (Na⁺ أيون الصوديوم). الأنيون: يتكون باكتساب إلكترون أو أكثر، تكوّنه اللافلزات غالبًا، عدد الإلكترونات فيه أكبر من البروتونات، يُسمى بإضافة المقطع «يد» إلى اسم العنصر (Cl⁻ أيون الكلوريد).', '["الفقد مقابل الاكتساب","فلزات مقابل لافلزات","البروتونات > الإلكترونات مقابل الإلكترونات > البروتونات","التسمية باسم العنصر مقابل المقطع «يد»","مثال صحيح لكل منهما"]'::jsonb, '[]'::jsonb, '[{"element":"طريقة التكوين","marks":1},{"element":"نوع العنصر","marks":1},{"element":"البروتونات والإلكترونات","marks":1},{"element":"التسمية مع مثالين","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"مقارنة كاملة بالأمثلة"},{"level":"3–4 درجات","description":"ثلاثة أوجه صحيحة"},{"level":"1–2 درجة","description":"وجه أو وجهان صحيحان"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["عكس الفقد والاكتساب","القول إن الأنيون فيه بروتونات أقل لأنه فقد بروتونات","تسمية الكاتيون بالمقطع «يد»"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-10-11T13:13:22.262Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(741, 0, 'لدى اللافلزات 5 إلى 7 إلكترونات تكافؤ، فاكتساب عدد قليل من الإلكترونات (1–3) يكمل ثمانيتها ويوصلها إلى تركيب الغاز النبيل المستقر.', '["","اللافلزات لها عدد كبير من إلكترونات التكافؤ (5–7)، والذرات ذات الإلكترونات القليلة تميل إلى الفقد.","الاكتساب يغير عدد الإلكترونات فقط، أما البروتونات فثابتة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-10-11T13:13:22.265Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(742, 2, 'ذرة الكلور ينقصها إلكترون واحد فقط لتكمل ثمانيتها، فتكتسبه وتصبح Cl⁻ بتوزيع الأرغون.', '["Na لديه إلكترون تكافؤ واحد يفقده بسهولة، ولا يكتسب.","Mg يفقد إلكتروني تكافئه ليصل إلى توزيع النيون.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-10-11T13:13:22.265Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(743, 1, 'تصل الذرة إلى الاستقرار بأسهل طريق: الكلور يحتاج إلى إلكترون واحد فقط ليصل إلى ثمانية، وفقد سبعة إلكترونات يتطلب طاقة كبيرة جدًا.', '["فقد الإلكترونات أو اكتسابها لا يغير نوع العنصر؛ عدد البروتونات هو الذي يحدده.","","للكلور 7 إلكترونات تكافؤ يمكن نظريًا فقدها، لكن ذلك يحتاج إلى طاقة كبيرة جدًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-11T13:13:22.265Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(744, 1, 'لدى X ستة إلكترونات تكافؤ، فتكتسب إلكترونين لتصل إلى 2,8 (توزيع النيون)، ويصبح عدد إلكتروناتها أكبر من بروتوناتها بـ 2.', '["الذرة التي لها 6 إلكترونات تكافؤ لا تفقد إلكترونين؛ فذلك يبعدها عن الثمانية.","","فقد ستة إلكترونات يحتاج طاقة كبيرة جدًا، والأسهل اكتساب إلكترونين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-11T13:13:22.266Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(745, 0, 'الكهروسالبية هي قدرة الذرة على جذب الإلكترونات، وهي مرتفعة لدى اللافلزات، ولهذا تميل إلى اكتساب الإلكترونات.', '["","اللافلزات عدد إلكترونات تكافئها كبير لا قليل.","النيوترونات لا تؤثر في السلوك الكيميائي للذرة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-11T13:13:22.266Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(746, 2, '5 + 3 = 8، 6 + 2 = 8، 7 + 1 = 8؛ فاللافلز يكتسب عددًا من الإلكترونات يكمل به ثمانية إلكترونات في مستواه الخارجي (التركيب الثماني).', '["العددان غير متساويين في أي صف (5 و3، 6 و2، 7 و1).","الفرق بين العددين 2 و4 و6، وليس 8.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-11T13:13:22.266Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(747, 1, 'الأسهل للصوديوم فقد إلكترون واحد، أما الكلور فيكفيه اكتساب إلكترون واحد ليصل إلى الثمانية؛ فالذرة تسلك الطريق الأقل طاقة.', '["مستوى الصوديوم الخارجي فيه إلكترون واحد فقط، فهو ليس ممتلئًا بل نشط جدًا.","","الكلور لافلز يكتسب الإلكترونات، ولا يفقدها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-11T13:13:22.266Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(748, null, null, null, 'لأن ذرات هذه المجموعات لا فلزية ولها 5 أو 6 أو 7 إلكترونات تكافؤ، فمستواها الخارجي قريب من الامتلاء، واكتساب 3 أو 2 أو 1 إلكترون أسهل (أقل طاقة) من فقد 5 أو 6 أو 7 إلكترونات، فتصل بالاكتساب إلى التركيب الثماني لأقرب غاز نبيل. مثال: O توزيعه 2,6 يكتسب إلكترونين فيصبح O²⁻ بتوزيع 2,8 مثل النيون.', '["عدد إلكترونات التكافؤ 5–7","الاكتساب أسهل من الفقد","الوصول إلى التركيب الثماني/الغاز النبيل","مثال O → O²⁻ بالتوزيع"]'::jsonb, '[]'::jsonb, '[{"element":"التعليل بإلكترونات التكافؤ وسهولة الاكتساب","marks":2},{"element":"ذكر التركيب الثماني","marks":1},{"element":"المثال بالتوزيع","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تعليل كامل ومثال صحيح"},{"level":"3 درجات","description":"تعليل صحيح مع نقص في المثال"},{"level":"2 درجتان","description":"تعليل ناقص أو مثال فقط"},{"level":"1 درجة","description":"ذكر أنها لافلزات فقط"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["القول إن الأكسجين يكتسب 6 إلكترونات","تعليل الاكتساب بقلة إلكترونات التكافؤ","القول إن الاكتساب يغير عدد البروتونات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-10-11T13:13:22.267Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(749, null, null, null, '(أ) X؛ لأن لديه 6 إلكترونات تكافؤ فيكتسب إلكترونين. (ب) X²⁻ وتوزيعه 2,8,8 (مثل الأرغون). (ج) Y لديه إلكترونا تكافؤ فقط؛ ليصل إلى الثمانية بالاكتساب يحتاج إلى 6 إلكترونات وهذا صعب ويحتاج طاقة كبيرة، فالأسهل أن يفقد إلكترونيه فيصبح Y²⁺.', '["تحديد X","يكتسب إلكترونين","X²⁻ وتوزيعه 2,8,8","Y يحتاج 6 إلكترونات فالأسهل فقد إلكترونين"]'::jsonb, '["X: 8 − 6 = 2 إلكترون مكتسب","X²⁻: 2,8,8","Y: الفقد (2) أسهل من الاكتساب (6)"]'::jsonb, '[{"element":"(أ) تحديد العنصر وعدد الإلكترونات","marks":2},{"element":"(ب) الرمز والتوزيع","marks":2},{"element":"(ج) التعليل","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"الأجزاء الثلاثة صحيحة"},{"level":"4–5 درجات","description":"جزآن صحيحان كاملان"},{"level":"2–3 درجات","description":"جزء واحد صحيح"},{"level":"1 درجة","description":"تحديد X فقط"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["كتابة X²⁺ بدل X²⁻","كتابة التوزيع 2,8 بدل 2,8,8","القول إن Y يكتسب 6 إلكترونات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-11T13:13:22.267Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(750, null, null, null, '(أ) توزيع N هو 2,5؛ يكفيه اكتساب 3 إلكترونات ليكمل ثمانيته (2,8 مثل النيون)، وهذا أسهل وأقل طاقة من فقد 5 إلكترونات، فيكوّن N³⁻. (ب) لأن عدد البروتونات في النواة لا يتغير بينما يزداد عدد الإلكترونات، فيصبح عدد الشحنات السالبة أكبر من عدد الشحنات الموجبة.', '["توزيع N: 2,5","اكتساب 3 أسهل من فقد 5","الوصول إلى التركيب الثماني","البروتونات ثابتة والإلكترونات تزداد","الإلكترونات أكثر من البروتونات → شحنة سالبة"]'::jsonb, '[]'::jsonb, '[{"element":"(أ) تعليل اكتساب النيتروجين","marks":2},{"element":"(ب) تعليل الشحنة السالبة","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"تعليلان صحيحان كاملان"},{"level":"3 درجات","description":"تعليل كامل وآخر ناقص"},{"level":"2 درجتان","description":"تعليل واحد صحيح"},{"level":"1 درجة","description":"إشارة عامة إلى الاستقرار"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["القول إن الشحنة سالبة لأن الذرة فقدت بروتونات","القول إن النيتروجين يكتسب 5 إلكترونات","إهمال المقارنة بين الفقد والاكتساب"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-11T13:13:22.267Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.')
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check, reviewer_notes) values
(751, 1, 'نشاط الفلز يعني سهولة دخوله في التفاعلات الكيميائية، وذلك لسهولة فقده إلكترونات تكافئه وتكوين أيونات موجبة.', '["اكتساب الإلكترونات سلوك اللافلزات لا الفلزات.","","هذا وصف الغازات النبيلة الخاملة لا الفلزات النشطة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-11T13:13:22.270Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(752, 0, 'فلزات المجموعتين 1 و2 لها إلكترون أو إلكترونان فقط في المستوى الخارجي، فتفقدها بسهولة، ولذلك هي أنشط الفلزات.', '["","المجموعتان 16 و17 لافلزات تكتسب الإلكترونات.","المجموعة 18 غازات نبيلة خاملة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-11T13:13:22.271Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(753, 2, 'توزيع Na هو 2,8,1؛ يكفيه فقد إلكترون واحد ليصل إلى توزيع النيون، فهو يفقده بسهولة كبيرة.', '["الألومنيوم يحتاج إلى فقد 3 إلكترونات، وهذا أصعب من فقد إلكترون واحد.","الكبريت لافلز يميل إلى اكتساب إلكترونين لا إلى فقد إلكترونات.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-11T13:13:22.271Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(754, 0, 'تفقد ذرة الفلز إلكترونات تكافئها لتصل إلى تركيب الغاز النبيل، فتصبح كاتيونًا (أيونًا موجبًا).', '["","الأيونات السالبة تكوّنها اللافلزات التي تكتسب الإلكترونات.","الأيون يشبه الغاز النبيل في التوزيع فقط، ولا يتغير عدد البروتونات في نواته."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-11T13:13:22.271Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(755, 2, 'لكل من Li وNa وK إلكترون تكافؤ واحد؛ بفقده تصل الذرة إلى تركيب الغاز النبيل، ولذلك تتفاعل بسهولة.', '["مستواها الخارجي فيه إلكترون واحد فقط، فهو غير ممتلئ.","عدد إلكترونات تكافئها 1 لا 7، والسبعة صفة الهالوجينات.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-11T13:13:22.271Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(756, 1, 'تفقد ذرة Mg إلكتروني تكافئها بسهولة فتصبح Mg²⁺ بتوزيع 2,8 مثل النيون.', '["اكتساب ستة إلكترونات يتطلب طاقة كبيرة، والفلز يميل إلى الفقد.","","فقد الإلكترونات يعطي شحنة موجبة لا سالبة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-11T13:13:22.272Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(757, 0, 'قلة إلكترونات التكافؤ تجعل فقدها أسهل من اكتساب عدد كبير من الإلكترونات، فتصل الذرة بالفقد إلى تركيب الغاز النبيل.', '["","هذا وصف اللافلزات التي تميل إلى الاكتساب.","امتلاء المستوى الخارجي صفة الغازات النبيلة غير النشطة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-11T13:13:22.272Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(758, null, null, null, 'لأن ذرات المجموعة 1 لها إلكترون تكافؤ واحد وذرات المجموعة 2 لها إلكترونا تكافؤ، فتفقدها بسهولة لتصل إلى التوزيع الإلكتروني لأقرب غاز نبيل (حالة الاستقرار). مثال: Na (2,8,1) يفقد إلكترونًا → Na⁺ (2,8)، وMg (2,8,2) يفقد إلكترونين → Mg²⁺ (2,8).', '["قلة إلكترونات التكافؤ (1 أو 2)","سهولة فقدها","الوصول إلى تركيب الغاز النبيل","مثال من المجموعة 1","مثال من المجموعة 2"]'::jsonb, '[]'::jsonb, '[{"element":"التعليل","marks":2},{"element":"مثال المجموعة 1","marks":1},{"element":"مثال المجموعة 2","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تعليل كامل ومثالان صحيحان"},{"level":"3 درجات","description":"تعليل كامل ومثال واحد"},{"level":"2 درجتان","description":"تعليل صحيح دون أمثلة"},{"level":"1 درجة","description":"مثال صحيح دون تعليل"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["القول إنها نشطة لأنها تكتسب الإلكترونات","كتابة Mg⁺ بدل Mg²⁺","عدم ربط النشاط بسهولة فقد الإلكترونات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-11T13:13:22.272Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(759, null, null, null, 'K: التوزيع 2,8,8,1، إلكترون تكافؤ واحد، نشط جدًا. Ar: التوزيع 2,8,8، ثمانية إلكترونات تكافؤ، خامل (غير نشط). التعليل: البوتاسيوم يفقد إلكترونه الوحيد بسهولة ليصل إلى توزيع الأرغون المستقر فيتفاعل بسهولة، أما الأرغون فمستواه الخارجي ممتلئ وهو مستقر أصلًا فلا يميل إلى التفاعل.', '["التوزيعان الصحيحان","إلكترون واحد مقابل ثمانية","K نشط وAr خامل","التعليل بسهولة الفقد مقابل امتلاء المستوى"]'::jsonb, '[]'::jsonb, '[{"element":"التوزيع وإلكترونات التكافؤ","marks":2},{"element":"النشاط","marks":1},{"element":"التعليل","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"مقارنة كاملة وتعليل صحيح"},{"level":"3–4 درجات","description":"مقارنة صحيحة مع تعليل ناقص"},{"level":"1–2 درجة","description":"نقطة أو نقطتان صحيحتان"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["كتابة توزيع K بالصورة 2,8,9","القول إن K يتحول إلى أرغون بعد فقد الإلكترون","القول إن الأرغون نشط لأن عدد إلكتروناته كبير"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-11T13:13:22.272Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(760, null, null, null, 'Na: 2,8,1 يفقد إلكترونًا واحدًا؛ Mg: 2,8,2 يفقد إلكترونين؛ Al: 2,8,3 يفقد ثلاثة إلكترونات. كلما قل عدد الإلكترونات التي يلزم فقدها للوصول إلى توزيع الغاز النبيل (النيون 2,8) كان الفقد أسهل والطاقة اللازمة أقل، فيكون الفلز أنشط؛ لذلك Na > Mg > Al.', '["التوزيعات الثلاثة","عدد الإلكترونات المفقودة 1 و2 و3","كلما قل عدد الإلكترونات المفقودة كان الفقد أسهل","الربط بالنشاط والوصول إلى توزيع النيون"]'::jsonb, '["Na: 2,8,1 → Na⁺ (يفقد 1)","Mg: 2,8,2 → Mg²⁺ (يفقد 2)","Al: 2,8,3 → Al³⁺ (يفقد 3)"]'::jsonb, '[{"element":"التوزيعات الثلاثة","marks":2},{"element":"عدد الإلكترونات المفقودة","marks":1},{"element":"التفسير","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"توزيعات صحيحة وتفسير كامل"},{"level":"3–4 درجات","description":"توزيعات صحيحة مع تفسير ناقص"},{"level":"1–2 درجة","description":"توزيعات فقط أو تفسير عام"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["تفسير النشاط بعدد البروتونات فقط","القول إن Al أنشط لأنه يفقد إلكترونات أكثر","أخطاء في التوزيع الإلكتروني"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-11T13:13:22.273Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(761, 2, 'الرابطة الأيونية قوة جذب كهروستاتيكي بين أيون موجب (كاتيون) وأيون سالب (أنيون).', '["المشاركة بالإلكترونات تصف رابطة أخرى (التساهمية) لا الرابطة الأيونية.","هذا وصف الرابطة الفلزية.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-11T13:13:22.276Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(762, 0, 'الفلز يفقد إلكترونات فيصبح أيونًا موجبًا، واللافلز يكتسبها فيصبح أيونًا سالبًا، فيتجاذبان برابطة أيونية.', '["","اللافلزان يميل كلاهما إلى اكتساب الإلكترونات فلا يتكون بينهما أيونان مختلفان في الشحنة.","الفلزان يميل كلاهما إلى فقد الإلكترونات، فلا يتكون أيون سالب."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-11T13:13:22.276Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(763, 1, 'المغنيسيوم فلز يفقد إلكترونين، والأكسجين لافلز يكتسبهما، فيتكون Mg²⁺ وO²⁻ وبينهما رابطة أيونية (MgO).', '["النيتروجين والأكسجين لافلزان، فلا يكوّنان رابطة أيونية.","","النحاس والخارصين فلزان؛ يكوّنان سبيكة لا مركبًا أيونيًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-10-11T13:13:22.277Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(764, 1, 'المركب الأيوني مركب يحتوي على أيونات موجبة وأيونات سالبة تربط بينها روابط أيونية (تجاذب كهروستاتيكي).', '["المشاركة بين لافلزين لا تكوّن أيونات.","","هذا وصف السبيكة لا المركب الأيوني."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-11T13:13:22.277Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(765, 2, 'Y توزيعه 2,8,1 فهو فلز يفقد إلكترونًا ويصبح Y⁺، وX توزيعه 2,6 لافلز يكتسب إلكترونين ويصبح X²⁻؛ فالرابطة بينهما أيونية (والصيغة Y₂X).', '["الرابطة الفلزية تكون بين ذرات فلزية، وX لافلز.","Y (2,8,1) نشط يفقد إلكترونًا وX (2,6) يكتسب، فتتكون رابطة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-10-11T13:13:22.277Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(766, 0, 'الشحنات المختلفة تتجاذب؛ فالأيون الموجب والأيون السالب يتجاذبان بقوة كهروستاتيكية هي الرابطة الأيونية.', '["","التنافر بين الشحنات المتشابهة يُبعد الأيونات ولا يربطها.","القوى النووية تعمل داخل النواة فقط ولا تكوّن روابط كيميائية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-11T13:13:22.277Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(767, 0, 'A: 11 بروتونًا و10 إلكترونات → Na⁺ (موجب)، وB: 17 بروتونًا و18 إلكترونًا → Cl⁻ (سالب)؛ فيتجاذبان برابطة أيونية.', '["","الجسيمان غير متعادلين؛ عدد البروتونات لا يساوي عدد الإلكترونات في أي منهما.","A فيه بروتونات أكثر من الإلكترونات فهو موجب لا سالب."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-10-11T13:13:22.277Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(768, null, null, null, 'الرابطة الأيونية: قوة جذب كهروستاتيكي بين أيونين أحدهما موجب والآخر سالب. المركب الأيوني: مركب يتكون من أيونات موجبة وأيونات سالبة بينها تجاذب كهروستاتيكي. في KBr: الكاتيون K⁺ (أيون البوتاسيوم)، والأنيون Br⁻ (أيون البروميد).', '["تعريف الرابطة الأيونية","تعريف المركب الأيوني","الكاتيون K⁺","الأنيون Br⁻"]'::jsonb, '[]'::jsonb, '[{"element":"تعريف الرابطة الأيونية","marks":1},{"element":"تعريف المركب الأيوني","marks":1},{"element":"تحديد الكاتيون والأنيون","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"التعريفان والتحديد صحيحة"},{"level":"3 درجات","description":"تعريفان صحيحان مع خطأ في أحد الأيونين"},{"level":"2 درجتان","description":"تعريف واحد مع تحديد صحيح"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["القول إن الرابطة الأيونية مشاركة إلكترونات","عكس الكاتيون والأنيون","كتابة K²⁺ أو Br²⁻"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-10-11T13:13:22.278Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(769, null, null, null, '(أ) أيونية: Ca فلز يفقد إلكترونين وF لافلز يكتسب إلكترونًا. (ب) ليست أيونية: S وO لافلزان يميل كلاهما إلى الاكتساب. (ج) ليست أيونية: Na وK فلزان يميل كلاهما إلى الفقد فلا يتكون أنيون. (د) أيونية: Li فلز يفقد إلكترونًا وCl لافلز يكتسبه.', '["(أ) أيونية مع التعليل","(ب) ليست أيونية مع التعليل","(ج) ليست أيونية مع التعليل","(د) أيونية مع التعليل"]'::jsonb, '[]'::jsonb, '[{"element":"(أ)","marks":1},{"element":"(ب)","marks":1},{"element":"(ج)","marks":1},{"element":"(د)","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"التصنيفات الأربعة صحيحة مع التعليل"},{"level":"3 درجات","description":"ثلاثة صحيحة"},{"level":"2 درجتان","description":"اثنان صحيحان"},{"level":"1 درجة","description":"واحد صحيح أو تصنيف دون تعليل"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["اعتبار أي عنصرين مختلفين يكوّنان رابطة أيونية","اعتبار الفلزين يكوّنان مركبًا أيونيًا","التصنيف دون تعليل"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-10-11T13:13:22.278Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(770, null, null, null, 'الفلز يميل إلى فقد إلكترونات تكافئه فيصبح أيونًا موجبًا، واللافلز يميل إلى اكتساب الإلكترونات فيصبح أيونًا سالبًا، فتنتقل الإلكترونات من الفلز إلى اللافلز ويتكون أيونان مختلفان في الشحنة يتجاذبان كهروستاتيكيًا. أما الفلزان فيميل كلاهما إلى الفقد، فلا يتكون أيون سالب. والمركب الأيوني متعادل لأن مجموع الشحنات الموجبة فيه يساوي مجموع الشحنات السالبة (عدد الإلكترونات التي يفقدها الفلز يساوي عدد الإلكترونات التي يكتسبها اللافلز).', '["الفلز يفقد فيصبح موجبًا","اللافلز يكتسب فيصبح سالبًا","انتقال الإلكترونات والتجاذب","الفلزان كلاهما يفقد فلا أنيون","تساوي الشحنات الموجبة والسالبة"]'::jsonb, '[]'::jsonb, '[{"element":"تفسير التكوين بين فلز ولافلز","marks":2},{"element":"تفسير عدم التكوين بين فلزين","marks":1},{"element":"تعليل التعادل الكهربائي","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"تفسير كامل وتعليل صحيح"},{"level":"3–4 درجات","description":"تفسير صحيح مع نقص في أحد الأجزاء"},{"level":"1–2 درجة","description":"جزء واحد صحيح"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["القول إن الأيونات تتعادل لأنها تفقد شحناتها بعد الارتباط","القول إن الفلزين يكوّنان رابطة أيونية","إغفال انتقال الإلكترونات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-11T13:13:22.280Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(771, 1, 'Na (2,8,1) يفقد إلكترون تكافئه، فينتقل إلى Cl (2,8,7) الذي يكتسبه، فيتكون Na⁺ وCl⁻ ويتجاذبان.', '["الكلور لافلز يكتسب الإلكترونات ولا يفقدها.","","المشاركة في الإلكترونات لا تكوّن أيونات؛ الرابطة الأيونية تنتج عن انتقال الإلكترونات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-11T13:13:22.286Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(772, 0, 'Mg (2,8,2) تفقد إلكترونين، وO (2,6) تكتسب إلكترونين، فينتقل إلكترونان ويتكون Mg²⁺ وO²⁻.', '["","Mg تفقد إلكتروني تكافئها كليهما لا إلكترونًا واحدًا.","الأكسجين يحتاج إلى إلكترونين فقط ليكمل ثمانيته (2,6 → 2,8)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-11T13:13:22.286Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(773, 2, 'تفقد Mg إلكترونين، وكل ذرة Cl لا تستطيع إلا اكتساب إلكترون واحد، فيلزم ذرتا كلور: Mg²⁺ + 2Cl⁻.', '["عكس الصحيح؛ Cl تكتسب إلكترونًا واحدًا وMg تفقد إلكترونين.","النسبة بين الأيونات تحددها الشحنات (الإلكترونات المنتقلة) لا الأحجام.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-11T13:13:22.286Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(774, 0, 'كتابة الطاقة مع النواتج تعني انطلاقها؛ فالمركب الأيوني الناتج أقل طاقة وأكثر استقرارًا من الذرات المنفردة.', '["","الطاقة مكتوبة في جهة النواتج، فهي منطلقة لا ممتصة.","وجود الطاقة في المعادلة يدل على تغير في الطاقة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-10-11T13:13:22.287Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(775, 1, 'ذرة Cl لها 7 إلكترونات تكافؤ، وبعد اكتساب إلكترون Na تصبح 8 إلكترونات تُرسم نقاطًا حول الرمز داخل أقواس مع الشحنة [Cl]⁻.', '["7 نقاط تمثل ذرة الكلور قبل اكتساب الإلكترون.","","النقطة الواحدة تمثل إلكترون تكافؤ ذرة الصوديوم قبل فقده."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-11T13:13:22.287Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(776, 2, 'Al (2,8,3) تفقد 3 إلكترونات، وكل ذرة F (2,7) تكتسب إلكترونًا واحدًا، فيلزم 3 ذرات فلور ويتكون AlF₃.', '["ذرة F واحدة تكتسب إلكترونًا واحدًا فقط، وAl تفقد ثلاثة.","7 هو عدد إلكترونات تكافؤ الفلور، وليس عدد الذرات اللازمة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-11T13:13:22.288Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(777, 0, 'Ca (2,8,8,2) يفقد إلكترونين فيصبح 2,8,8 مثل الأرغون، وO (2,6) يكتسب إلكترونين فيصبح 2,8 مثل النيون.', '["","Ca²⁺ فيه 18 إلكترونًا (2,8,8) لا 10.","O²⁻ فيه 10 إلكترونات (2,8) لا 18."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-11T13:13:22.288Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(778, null, null, null, 'Na: 2,8,1 (إلكترون تكافؤ واحد)، Cl: 2,8,7 (7 إلكترونات تكافؤ). يفقد Na إلكترونًا فيصبح Na⁺ (2,8)، ويكتسبه Cl فيصبح Cl⁻ (2,8,8). يتجاذب الأيونان المختلفان في الشحنة بقوة كهروستاتيكية هي الرابطة الأيونية. لويس: Na· + ·Cl (7 نقاط) ← [Na]⁺ [Cl (8 نقاط)]⁻.', '["التوزيعان الإلكترونيان","إلكترونات التكافؤ 1 و7","Na يفقد وCl يكتسب","الأيونان Na⁺ وCl⁻","التجاذب الكهروستاتيكي (رابطة أيونية)","تمثيل لويس صحيح"]'::jsonb, '["Na: 2,8,1 ، Cl: 2,8,7","Na → Na⁺ + e⁻","Cl + e⁻ → Cl⁻","Na⁺ + Cl⁻ → NaCl (تجاذب كهروستاتيكي)"]'::jsonb, '[{"element":"التوزيعات وإلكترونات التكافؤ","marks":1},{"element":"الفقد والاكتساب والأيونات","marks":2},{"element":"نوع الرابطة","marks":1},{"element":"تمثيل لويس","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"خطوات كاملة وتمثيل لويس صحيح"},{"level":"4–5 درجات","description":"خطوات كاملة مع خطأ في تمثيل لويس"},{"level":"2–3 درجات","description":"الفقد والاكتساب صحيحان دون تفاصيل"},{"level":"1 درجة","description":"ذكر أن الرابطة أيونية فقط"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["رسم 7 نقاط حول Cl⁻","عدم وضع الأقواس والشحنة في تمثيل لويس","القول إن الذرتين تتشاركان إلكترونًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-11T13:13:22.289Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(779, null, null, null, 'Ca: 2,8,8,2 يفقد إلكترونين فيصبح Ca²⁺ (2,8,8). كل ذرة Cl (2,8,7) تكتسب إلكترونًا واحدًا فتصبح Cl⁻ (2,8,8). لذلك يلزم ذرتا كلور لاستقبال الإلكترونين، فيتكون المركب CaCl₂، وتربط بين Ca²⁺ وCl⁻ روابط أيونية (تجاذب كهروستاتيكي).', '["Ca يفقد إلكترونين → Ca²⁺","كل Cl تكتسب إلكترونًا → Cl⁻","يلزم ذرتا كلور","الصيغة CaCl₂","التجاذب الكهروستاتيكي"]'::jsonb, '["Ca → Ca²⁺ + 2e⁻","2Cl + 2e⁻ → 2Cl⁻","Ca²⁺ + 2Cl⁻ → CaCl₂"]'::jsonb, '[{"element":"فقد Ca لإلكترونين","marks":1},{"element":"اكتساب Cl وعدد الذرات","marks":2},{"element":"الصيغة ونوع الرابطة","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"توضيح كامل وصيغة صحيحة"},{"level":"3–4 درجات","description":"توضيح صحيح مع خطأ في الصيغة أو عدد الذرات"},{"level":"1–2 درجة","description":"ذكر الفقد والاكتساب فقط"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["كتابة الصيغة CaCl","القول إن ذرة Cl واحدة تكتسب إلكترونين","كتابة Cl²⁻"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-11T13:13:22.289Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(780, null, null, null, '(أ) Al (2,8,3) تفقد 3 إلكترونات → Al³⁺، وO (2,6) تكتسب إلكترونين → O²⁻. (ب) المضاعف المشترك الأصغر لـ 3 و2 هو 6: ذرتا Al تفقدان 2 × 3 = 6 إلكترونات، و3 ذرات O تكتسب 3 × 2 = 6 إلكترونات. (ج) الصيغة Al₂O₃؛ الشحنات الموجبة 2 × (+3) = +6، والسالبة 3 × (−2) = −6، والمجموع صفر.', '["Al تفقد 3 وO تكتسب 2","المضاعف المشترك 6","ذرتا Al و3 ذرات O","الصيغة Al₂O₃","+6 و−6 والمجموع صفر"]'::jsonb, '["Al: 2,8,3 → Al³⁺ ، O: 2,6 → O²⁻","م.م.أ (3، 2) = 6 إلكترونات","2Al → 2Al³⁺ + 6e⁻ ، 3O + 6e⁻ → 3O²⁻","Al₂O₃: 2(+3) + 3(−2) = 0"]'::jsonb, '[{"element":"(أ)","marks":2},{"element":"(ب)","marks":2},{"element":"(ج)","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"الأجزاء الثلاثة صحيحة"},{"level":"4–5 درجات","description":"جزآن صحيحان كاملان"},{"level":"2–3 درجات","description":"جزء واحد صحيح"},{"level":"1 درجة","description":"تحديد شحنة أحد الأيونين فقط"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["كتابة الصيغة AlO أو Al₃O₂","القول إن O تكتسب 6 إلكترونات","عدم التحقق من تعادل الشحنات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-10-11T13:13:22.289Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(781, 1, 'من خواص المركبات الأيونية ارتفاع درجات انصهارها وغليانها، لقوة الرابطة بين أيوناتها.', '["المركب الأيوني الصلب لا يوصل الكهرباء؛ يوصلها مصهورًا أو محلولًا.","","القابلية للطرق والسحب من خواص الفلزات؛ المركبات الأيونية هشة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (44%)"}],"at":"2026-10-11T13:13:22.293Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(782, 0, 'معظم المركبات الأيونية مواد صلبة بلورية عند درجة حرارة الغرفة، لأن أيوناتها مترابطة بقوة في شبكة بلورية.', '["","المركبات الأيونية درجات غليانها مرتفعة جدًا فلا توجد غازات في الظروف العادية.","درجات انصهارها مرتفعة فلا تكون سوائل في درجة حرارة الغرفة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-11T13:13:22.293Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(783, 2, 'محاليل المركبات الأيونية ومصاهيرها توصل الكهرباء، أما الصلب فلا يوصلها.', '["الأيونات في الحالة الصلبة مقيدة في الشبكة فلا يوصل الصلب.","الصلب لا يوصل، بينما يوصل المصهور والمحلول، فالتوصيل يختلف باختلاف الحالة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-11T13:13:22.293Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(784, 1, 'تترتب الأيونات في وحدات منتظمة متكررة تكوّن البلورات، والبلورة ترتيب هندسي ثلاثي الأبعاد للجسيمات.', '["المركب الأيوني لا يتكون من جزيئات منفصلة بل من شبكة متصلة من الأيونات.","","ترتيب الأيونات منتظم ومتكرر لا عشوائي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-10-11T13:13:22.293Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(785, 0, 'المركبات الأيونية صلبة وقوية، لكنها هشة تتفتت بلوراتها عند تعرضها لضربة قوية.', '["","المركبات الأيونية ليست لينة، وتتفتت عند الطرق.","المرونة وقابلية السحب من صفات الفلزات لا المركبات الأيونية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-10-11T13:13:22.293Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(786, 2, 'A درجة انصهارها مرتفعة، ولا توصل الكهرباء صلبة لكنها توصلها منصهرة، وهذه خواص المركبات الأيونية.', '["B توصل الكهرباء وهي صلبة، وهذه صفة الفلزات.","C درجة انصهارها منخفضة ولا توصل في أي حالة، فليست مركبًا أيونيًا.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-10-11T13:13:22.294Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(787, 1, 'بلورة NaCl مكعبة الشكل، ونسبة أيونات Na⁺ إلى Cl⁻ فيها 1:1.', '["شحنتا Na⁺ وCl⁻ متساويتان في المقدار فالنسبة 1:1 لا 1:2.","","بلورة NaCl مكعبة لا سداسية، والنسبة 1:1."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-10-11T13:13:22.294Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(788, null, null, null, '1) معظمها مواد صلبة بلورية عند درجة حرارة الغرفة. 2) درجات انصهارها وغليانها مرتفعة. 3) صلبة وقوية لكنها هشة. 4) لا توصل الكهرباء وهي صلبة، لكن مصاهيرها ومحاليلها المائية توصل الكهرباء.', '["صلبة بلورية","درجات انصهار وغليان مرتفعة","صلبة وقوية وهشة","محاليلها ومصاهيرها توصل الكهرباء (والصلب لا يوصل)"]'::jsonb, '[]'::jsonb, '[{"element":"الخاصية الأولى","marks":1},{"element":"الخاصية الثانية","marks":1},{"element":"الخاصية الثالثة","marks":1},{"element":"الخاصية الرابعة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"أربع خواص صحيحة"},{"level":"3 درجات","description":"ثلاث خواص صحيحة"},{"level":"2 درجتان","description":"خاصيتان صحيحتان"},{"level":"1 درجة","description":"خاصية واحدة صحيحة"},{"level":"صفر","description":"لا إجابة أو خواص خاطئة"}]'::jsonb, '["ذكر أن المركبات الأيونية الصلبة توصل الكهرباء","ذكر قابلية الطرق والسحب","ذكر خواص كيميائية بدل الفيزيائية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (44%)"}],"at":"2026-10-11T13:13:22.294Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(789, null, null, null, 'X مركب أيوني؛ لأن درجة انصهارها مرتفعة، ولا توصل الكهرباء صلبة لكن محلولها يوصل، وهي هشة تتفتت عند الطرق. استُبعدت Y لأن درجة انصهارها منخفضة ولا توصل منصهرة. واستُبعدت Z لأنها توصل وهي صلبة وقابلة للطرق، وهذه خواص الفلزات.', '["تحديد X","درجة انصهار مرتفعة","لا توصل صلبة ويوصل محلولها","هشة","استبعاد Y","استبعاد Z (خواص فلز)"]'::jsonb, '[]'::jsonb, '[{"element":"تحديد X","marks":1},{"element":"التبرير بثلاث خواص","marks":3},{"element":"استبعاد Y وZ","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"تحديد صحيح وتبرير بثلاث خواص واستبعاد مبرر"},{"level":"4–5 درجات","description":"تحديد صحيح مع تبرير بخاصيتين أو استبعاد ناقص"},{"level":"2–3 درجات","description":"تحديد صحيح مع خاصية واحدة"},{"level":"1 درجة","description":"تحديد X دون تبرير"},{"level":"صفر","description":"إجابة خاطئة"}]'::jsonb, '["اختيار Z لأن درجة انصهارها الأعلى مع إهمال التوصيل في الحالة الصلبة","اعتبار عدم توصيل الصلب دليلًا كافيًا وحده","عدم تبرير الاستبعاد"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-10-11T13:13:22.294Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(790, null, null, null, 'البلورة: ترتيب هندسي ثلاثي الأبعاد للجسيمات (الأيونات) في وحدات منتظمة متكررة. بلورة NaCl مكعبة الشكل، ونسبة أيونات Na⁺ إلى Cl⁻ فيها 1:1. ويختلف شكل البلورة باختلاف حجم الأيونات وعددها (نسبتها).', '["تعريف البلورة","بلورة NaCl مكعبة","النسبة 1:1","حجم الأيونات","عدد الأيونات"]'::jsonb, '[]'::jsonb, '[{"element":"تعريف البلورة","marks":1},{"element":"وصف بلورة NaCl","marks":2},{"element":"العاملان","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"تعريف ووصف وعاملان صحيحة"},{"level":"3–4 درجات","description":"نقص في عنصر واحد"},{"level":"1–2 درجة","description":"تعريف فقط أو وصف فقط"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["وصف بلورة NaCl بأنها مكونة من جزيئات NaCl منفصلة","ذكر نسبة 1:2","ذكر لون الأيونات عاملًا لشكل البلورة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-10-11T13:13:22.295Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(791, 2, 'طاقة الشبكة البلورية (طاقة البلورة) هي الطاقة اللازمة لفصل أيونات 1 mol من المركب الأيوني بعضها عن بعض.', '["هذا وصف لطاقة التأين لا لطاقة الشبكة البلورية.","طاقة الشبكة تخص أيونات مول كامل من المركب لا زوجًا واحدًا من الأيونات.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (60%)"}],"at":"2026-10-11T13:13:22.298Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(792, 0, 'يُعرَّف المفهوم لمول واحد من المركب الأيوني، ولذلك تقاس بوحدة kJ/mol.', '["","طاقة الشبكة تُنسب إلى عدد الأيونات (المول) لا إلى الكتلة.","المركب الأيوني صلب، ولا تُنسب طاقة شبكته إلى الحجم."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-11T13:13:22.298Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(793, 1, 'البلورة ترتيب هندسي ثلاثي الأبعاد للجسيمات (الأيونات) في وحدات منتظمة متكررة، وطاقة الشبكة هي الطاقة اللازمة لتفكيكها.', '["هذا وصف قريب من السبيكة لا البلورة.","","هذا وصف الأيون عديد الذرات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (60%)"}],"at":"2026-10-11T13:13:22.298Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(794, 2, 'طاقة الشبكة البلورية هي الطاقة اللازمة لفصل أيونات 1 mol من المركب، فيلزم نحو 790 kJ لفصل أيونات 1 mol من NaCl.', '["طاقة الشبكة تخص فصل أيونات مول كامل لا صهر جرام.","القيمة تخص مولًا كاملًا من الأيونات لا زوجًا واحدًا.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-10-11T13:13:22.298Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(795, 0, 'الأيونات في البلورة مترابطة بقوى تجاذب كهروستاتيكي، ولفصلها يجب امتصاص طاقة تساوي طاقة الشبكة البلورية.', '["","انطلاق الطاقة يحدث عند تكوين البلورة من الأيونات لا عند فصلها.","الأيونات مترابطة بقوى تجاذب، والتغلب عليها يحتاج إلى طاقة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-10-11T13:13:22.299Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(796, 1, 'طاقة الشبكة لـ KCl نحو 720 kJ لكل 1 mol، فلـ 2 mol: 2 × 720 = 1440 kJ.', '["هذه الطاقة اللازمة لمول واحد فقط.","","قُسمت القيمة على 2 بدل ضربها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-11T13:13:22.299Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(797, 0, 'كلما زادت الطاقة اللازمة لفصل الأيونات كانت قوى التجاذب بينها (الرابطة الأيونية) أقوى.', '["","طاقة الشبكة تتعلق بقوة التجاذب بين الأيونات لا بعدد إلكترونات أحدها.","طاقة الشبكة لا تعبّر عن سرعة الذوبان."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-11T13:13:22.299Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(798, null, null, null, 'طاقة الشبكة البلورية: الطاقة اللازمة لفصل أيونات 1 mol من المركب الأيوني. تُنسب إلى مول واحد لتكون القيم قابلة للمقارنة بين المركبات (عدد ثابت من وحدات الصيغة)، ولذلك وحدتها kJ/mol. والقيمة المرتفعة تدل على قوة التجاذب بين الأيونات، أي رابطة أيونية قوية.', '["التعريف مع ذكر 1 mol","سبب النسبة إلى المول (المقارنة/عدد ثابت من الوحدات)","الوحدة kJ/mol","القيمة المرتفعة = رابطة أيونية أقوى"]'::jsonb, '[]'::jsonb, '[{"element":"التعريف","marks":2},{"element":"سبب النسبة إلى المول","marks":1},{"element":"دلالة القيمة المرتفعة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تعريف دقيق وتوضيح كامل"},{"level":"3 درجات","description":"تعريف دقيق مع نقص في أحد الجزأين"},{"level":"2 درجتان","description":"تعريف دون ذكر المول أو دون التوضيحات"},{"level":"1 درجة","description":"إشارة عامة إلى الطاقة"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["حذف «1 mol» من التعريف","القول إن الطاقة تنطلق عند الفصل","ربط القيمة المرتفعة برابطة أضعف"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-11T13:13:22.299Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(799, null, null, null, 'الكتلة المولية لـ NaCl = 23.0 + 35.5 = 58.5 g/mol. عدد المولات = 117 ÷ 58.5 = 2.00 mol. الطاقة اللازمة = 2.00 mol × 787 kJ/mol = 1574 kJ ≈ 1.57×10³ kJ.', '["حساب الكتلة المولية 58.5 g/mol","حساب عدد المولات 2.00 mol","ضرب عدد المولات في طاقة الشبكة","الناتج 1.57×10³ kJ بالوحدة"]'::jsonb, '["M(NaCl) = 23.0 + 35.5 = 58.5 g/mol","n = 117 ÷ 58.5 = 2.00 mol","E = 2.00 × 787 = 1574 kJ ≈ 1.57×10³ kJ"]'::jsonb, '[{"element":"الكتلة المولية","marks":1},{"element":"عدد المولات","marks":1},{"element":"التعويض","marks":1},{"element":"الناتج والوحدة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"خطوات صحيحة وناتج 1.57×10³ kJ"},{"level":"3 درجات","description":"خطوات صحيحة مع خطأ في الوحدة أو التقريب"},{"level":"2 درجتان","description":"حساب عدد المولات صحيح فقط"},{"level":"1 درجة","description":"حساب الكتلة المولية فقط"},{"level":"صفر","description":"لا إجابة أو طريقة خاطئة"}]'::jsonb, '["ضرب الكتلة مباشرة في طاقة الشبكة (9.21×10⁴ kJ)","قسمة طاقة الشبكة على عدد المولات (394 kJ)","كتابة الوحدة kJ/mol للناتج"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-10-11T13:13:22.299Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(800, null, null, null, 'الخطأ الأول: «تنطلق» — والصحيح أن فصل الأيونات يحتاج إلى امتصاص طاقة (الطاقة لازمة). الخطأ الثاني: «أيون واحد عن أيون واحد» — والصحيح أنها لفصل أيونات 1 mol من المركب الأيوني. العلاقة: تكوين البلورة من أيوناتها عملية طاردة تنطلق فيها طاقة، لأن المركب الأيوني المستقر أقل طاقة من أيوناته المنفردة، أما فصل الأيونات فعملية معاكسة تحتاج إلى امتصاص طاقة.', '["تصحيح «تنطلق» إلى «تلزم/تُمتص»","تصحيح «أيون واحد» إلى «1 mol»","تكوين البلورة طارد للطاقة","الفصل عملية معاكسة ماصة للطاقة"]'::jsonb, '[]'::jsonb, '[{"element":"الخطأ الأول وتصحيحه","marks":1},{"element":"الخطأ الثاني وتصحيحه","marks":1},{"element":"العلاقة بين الفصل والتكوين","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"تحديد الخطأين وتصحيحهما وتوضيح العلاقة"},{"level":"3 درجات","description":"الخطآن مع توضيح ناقص"},{"level":"2 درجتان","description":"خطأ واحد مع تصحيحه وتوضيح جزئي"},{"level":"1 درجة","description":"تحديد خطأ واحد دون تصحيح"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["الاعتقاد بأن فصل الأيونات يطلق طاقة","عدم الانتباه إلى أن التعريف لمول كامل","الخلط بين طاقة الشبكة وطاقة التأين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-11T13:13:22.300Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(801, 1, 'الإلكتروليت هو محلول المركب الأيوني الذي يستطيع توصيل التيار الكهربائي.', '["المركب الأيوني الصلب لا يوصل الكهرباء أصلًا.","","الإلكتروليت يوصل الكهرباء بحكم تعريفه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-11T13:13:22.303Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(802, 0, 'الإلكتروليت محلول مركب أيوني؛ فعند الذوبان تنفصل الأيونات وتصبح قادرة على نقل الشحنات.', '["","الفلزات توصل بالإلكترونات الحرة ولا تكوّن محلولًا إلكتروليتيًا بالذوبان في الماء.","الغازات النبيلة لا تكوّن أيونات فلا تعطي محلولًا موصلًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-11T13:13:22.303Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(803, 2, 'عند ذوبان NaCl تنفصل أيونات Na⁺ وCl⁻ وتتحرك بحرية في المحلول فتنقل الشحنة الكهربائية.', '["التوصيل في المحلول الأيوني يتم بحركة الأيونات لا بالإلكترونات الحرة.","الماء النقي رديء التوصيل؛ التوصيل سببه الأيونات الذائبة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-11T13:13:22.303Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(804, 1, 'في الإلكتروليت تتحرك الأيونات الموجبة والسالبة الحرة فتنقل الشحنة الكهربائية.', '["الإلكترونات الحرة تنقل الشحنة في الفلزات لا في المحاليل الأيونية.","","الجزيئات المتعادلة لا تحمل شحنة فلا تنقل التيار."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-11T13:13:22.303Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(805, 0, 'محلول KCl أضاء المصباح، فهو محلول مركب أيوني يوصل الكهرباء، أي إلكتروليت.', '["","بلورات KCl لم يضئ معها المصباح؛ أيوناتها مقيدة، كما أن الإلكتروليت محلول لا مادة صلبة.","محلول السكر لم يوصل الكهرباء، فليس إلكتروليتًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-11T13:13:22.303Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(806, 2, 'يؤدي الذوبان إلى انفصال الأيونات عن الشبكة البلورية فتصبح حرة الحركة، وهذا ما يجعل المحلول موصلًا.', '["الأيونات تبقى مشحونة في المحلول، ولو تحولت إلى ذرات متعادلة لما وصل المحلول.","الذوبان لا يحوّل المركب الأيوني إلى فلز.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-10-11T13:13:22.304Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(807, 1, 'الماء المالح محلول مركب أيوني (NaCl) فهو إلكتروليت يوصل التيار الكهربائي، مما يعرّض الشخص للصعق.', '["الماء المالح ليس عازلًا؛ فيه أيونات حرة توصل الكهرباء.","","التوصيل في الماء المالح سببه الأيونات لا الإلكترونات الحرة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-10-11T13:13:22.304Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(808, null, null, null, 'الإلكتروليت: محلول المركب الأيوني القادر على توصيل الكهرباء. البلورات الصلبة لا توصل لأن الأيونات مقيدة في مواقع ثابتة في الشبكة البلورية فلا تستطيع الحركة لنقل الشحنات. أما في المحلول المائي فتنفصل الأيونات Na⁺ وCl⁻ وتصبح حرة الحركة فتنقل الشحنة الكهربائية.', '["تعريف الإلكتروليت","الأيونات في الصلب مقيدة في الشبكة","الأيونات في المحلول حرة الحركة","حركة الأيونات تنقل الشحنة"]'::jsonb, '[]'::jsonb, '[{"element":"التعريف","marks":1},{"element":"تعليل عدم توصيل الصلب","marks":1},{"element":"تعليل توصيل المحلول","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"تعريف وتعليلان صحيحان"},{"level":"3 درجات","description":"تعريف وتعليل واحد كامل"},{"level":"2 درجتان","description":"تعريف فقط أو تعليلان ناقصان"},{"level":"1 درجة","description":"إشارة عامة إلى الأيونات"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["القول إن الصلب لا يحتوي على أيونات","تفسير التوصيل بالإلكترونات الحرة","القول إن الماء النقي هو الموصل"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-11T13:13:22.304Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(809, null, null, null, '(أ) يضيء المصباح مع محلول NaBr فقط. (ب) محلول NaBr إلكتروليت لأنه محلول مركب أيوني تتحرك أيوناته Na⁺ وBr⁻ بحرية فتوصل الكهرباء؛ أما البلورات الصلبة فأيوناتها مقيدة، والسكر والماء المقطر لا يحتويان على أيونات حرة بكمية تكفي لإضاءة المصباح. (ج) الماء المقطر عينة ضابطة تثبت أن التوصيل في المحلول سببه الأيونات الذائبة لا الماء نفسه.', '["المصباح يضيء مع محلول NaBr فقط","محلول NaBr إلكتروليت","التبرير بحركة الأيونات","سبب عدم توصيل العينات الأخرى","الماء المقطر عينة ضابطة"]'::jsonb, '[]'::jsonb, '[{"element":"(أ) التوقع","marks":1},{"element":"(ب) التحديد والتبرير","marks":3},{"element":"(ج) دور الماء المقطر","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة صحيحة"},{"level":"3–4 درجات","description":"التوقع والتحديد صحيحان مع تبرير ناقص"},{"level":"1–2 درجة","description":"التوقع فقط صحيح"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["توقع إضاءة المصباح مع البلورات الصلبة","اعتبار محلول السكر إلكتروليتًا لأنه محلول","إغفال دور العينة الضابطة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-11T13:13:22.305Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(810, null, null, null, 'في الإلكتروليت: تنتقل الشحنة بحركة الأيونات الموجبة (K⁺) والسالبة (Cl⁻) الحرة، ويحدث التوصيل في المحلول (أو المصهور) لا في الحالة الصلبة. في سلك النحاس: تنتقل الشحنة بحركة الإلكترونات الحرة غير المتمركزة، ويحدث التوصيل والفلز في الحالة الصلبة.', '["الأيونات في الإلكتروليت","الإلكترونات الحرة في النحاس","الإلكتروليت يوصل في المحلول/المصهور","النحاس يوصل وهو صلب"]'::jsonb, '[]'::jsonb, '[{"element":"الجسيمات الناقلة في كل منهما","marks":2},{"element":"الحالة الفيزيائية في كل منهما","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"مقارنة كاملة صحيحة"},{"level":"3 درجات","description":"ثلاث نقاط صحيحة"},{"level":"2 درجتان","description":"نقطتان صحيحتان"},{"level":"1 درجة","description":"نقطة واحدة"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["القول إن الإلكتروليت يوصل بالإلكترونات","القول إن النحاس يوصل بحركة الأيونات","القول إن الفلز يجب أن ينصهر ليوصل"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-11T13:13:22.305Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(811, 0, 'طاقة الشبكة البلورية مقياس لقوة الرابطة الأيونية؛ فكلما زادت كانت قوى التجاذب بين الأيونات أقوى.', '["","زيادة الطاقة اللازمة لفصل الأيونات تعني تجاذبًا أقوى لا أضعف.","طاقة الشبكة مقياس مباشر لقوة الرابطة الأيونية فلا يمكن ألا تتأثر."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-11T13:13:22.308Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(812, 2, 'تتناسب طاقة الشبكة طرديًا مع شحنة الأيون؛ شحنة Mg²⁺ (+2) أكبر من شحنة Na⁺ (+1)، فطاقة شبكة MgCl₂ أكبر.', '["طاقة الشبكة تتناسب طرديًا مع الشحنة، فالشحنة الأصغر تعطي طاقة أقل.","الأنيون واحد لكن الكاتيونين مختلفان في الشحنة، فلا تتساوى الطاقتان.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-11T13:13:22.309Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(813, 1, 'تتناسب طاقة الشبكة عكسيًا مع حجم الأيون؛ Na⁺ أصغر من K⁺ فالمسافة بين مراكز الأيونات في NaI أقل والتجاذب أقوى.', '["الأيون الأكبر حجمًا يزيد المسافة بين الأيونات فيضعف التجاذب وتقل طاقة الشبكة.","","تساوي الشحنة لا يكفي؛ فحجم الأيون يؤثر أيضًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-10-11T13:13:22.310Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(814, 0, 'كلما زادت طاقة الشبكة زادت قوة التجاذب بين الأيونات، فترتفع درجتا الانصهار والغليان وتزداد الصلابة.', '["","Y طاقة شبكته أقل فقوى التجاذب فيه أضعف، فتكون درجة انصهاره أقل.","زيادة طاقة الشبكة ترفع درجة الانصهار وتزيد الصلابة معًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-10-11T13:13:22.310Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(815, 2, 'أثر الشحنة هو الغالب: CaCl₂ هو المركب الوحيد الذي شحنة كاتيونه +2، فطاقة شبكته الأعلى.', '["شحنة Na⁺ في NaCl تساوي +1 فقط، وهي أقل من شحنة Ca²⁺.","NaI شحنة كاتيونه +1 وأنيونه I⁻ أكبر حجمًا، فطاقة شبكته الأقل بين مركبات الصوديوم.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-11T13:13:22.310Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(816, 1, 'تزداد طاقة الشبكة بزيادة شحنة الأيونات، وتقل بزيادة حجمها (لأن المسافة بين مراكز الأيونات تزداد فيضعف التجاذب).', '["عكس الصحيح في العاملين كليهما.","","الحجم الأكبر يقلل طاقة الشبكة، فالعلاقة مع الحجم عكسية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-10-11T13:13:22.311Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(817, 1, 'أيونا MgO شحنتاهما +2 و−2 مقابل +1 و−1 في NaCl، فطاقة الشبكة أكبر بكثير، والتجاذب أقوى، فيلزم طاقة أكبر لصهره.', '["الكتلة المولية لـ MgO (نحو 40 g/mol) أصغر من NaCl (58.5 g/mol)، والكتلة ليست العامل المحدد.","","الحجم الأكبر يقلل طاقة الشبكة ولا يرفع درجة الانصهار."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-11T13:13:22.311Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(818, null, null, null, '(أ) علاقة طردية: كلما زادت طاقة الشبكة البلورية كانت الرابطة الأيونية أقوى، لأن طاقة الشبكة مقياس لقوة التجاذب بين الأيونات. (ب) كلما زادت طاقة الشبكة ارتفعت درجتا الانصهار والغليان وزادت الصلابة، لأن التغلب على تجاذب أقوى يحتاج إلى طاقة أكبر. العاملان: شحنة الأيونات (علاقة طردية)، وحجم الأيونات (علاقة عكسية).', '["علاقة طردية مع قوة الرابطة","علاقة طردية مع درجة الانصهار والصلابة","التعليل بقوة التجاذب","الشحنة: طردية","الحجم: عكسية"]'::jsonb, '[]'::jsonb, '[{"element":"(أ)","marks":1},{"element":"(ب) مع التعليل","marks":2},{"element":"العاملان ونوع العلاقة","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"العلاقات والعاملان صحيحة مع التعليل"},{"level":"3–4 درجات","description":"خطأ أو نقص في عنصر واحد"},{"level":"1–2 درجة","description":"علاقة واحدة صحيحة"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["جعل العلاقة مع الحجم طردية","ذكر «حجم الذرة» بدل «حجم الأيون»","القول إن طاقة الشبكة العالية تعني درجة انصهار منخفضة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-11T13:13:22.311Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(819, null, null, null, '(أ) CaF₂؛ لأن شحنة Ca²⁺ (+2) أكبر من شحنة K⁺ (+1)، وطاقة الشبكة تتناسب طرديًا مع الشحنة. (ب) MgCl₂؛ لأن الشحنتين متساويتين وMg²⁺ أصغر حجمًا من Ca²⁺، فالمسافة بين الأيونات أقل والتجاذب أقوى. (ج) NaCl؛ لأن Cl⁻ أصغر حجمًا من Br⁻، وطاقة الشبكة تتناسب عكسيًا مع حجم الأيون.', '["(أ) CaF₂ — الشحنة","(ب) MgCl₂ — حجم الكاتيون","(ج) NaCl — حجم الأنيون","التعليل بالتناسب الطردي/العكسي"]'::jsonb, '[]'::jsonb, '[{"element":"(أ)","marks":2},{"element":"(ب)","marks":2},{"element":"(ج)","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"الأزواج الثلاثة صحيحة مع العامل والتعليل"},{"level":"4–5 درجات","description":"زوجان صحيحان كاملان أو الثلاثة دون تعليل كامل"},{"level":"2–3 درجات","description":"زوج واحد صحيح كامل"},{"level":"1 درجة","description":"اختيار صحيح دون تعليل"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["اختيار CaCl₂ في (ب) بحجة أن Ca أثقل","تعليل (ج) بكتلة البروم","الخلط بين حجم الذرة وحجم الأيون"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-11T13:13:22.312Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(820, null, null, null, '(أ) تقل درجة الانصهار من NaF إلى NaI. (ب) الكاتيون واحد (Na⁺) والشحنات متساوية، لكن حجم الأنيون يزداد من F⁻ إلى I⁻، فتزداد المسافة بين مراكز الأيونات ويضعف التجاذب، فتقل طاقة الشبكة البلورية وتقل الطاقة اللازمة للصهر. (ج) NaI؛ لأن أنيونه الأكبر حجمًا فطاقة شبكته الأقل.', '["وصف النمط (تناقص)","ثبات الشحنة والكاتيون","زيادة حجم الأنيون","نقص طاقة الشبكة وضعف التجاذب","اختيار NaI"]'::jsonb, '[]'::jsonb, '[{"element":"(أ) وصف النمط","marks":1},{"element":"(ب) التفسير","marks":3},{"element":"(ج) الاختيار مع التبرير","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"وصف وتفسير واختيار صحيحة"},{"level":"3–4 درجات","description":"وصف واختيار صحيحان مع تفسير ناقص"},{"level":"1–2 درجة","description":"وصف النمط فقط"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["تفسير النمط بزيادة الكتلة","القول إن الأيون الأكبر يعطي تجاذبًا أقوى","اختيار NaF لأقل طاقة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-11T13:13:22.312Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(821, 1, 'الأيونات الموجبة والسالبة مترابطة بقوى تجاذب كهروستاتيكي قوية في الشبكة البلورية، فيلزم طاقة كبيرة للتغلب عليها.', '["لو كانت قوى التجاذب ضعيفة لانخفضت درجات الانصهار.","","المركبات الأيونية لا تحتوي على إلكترونات حرة؛ هذه صفة الفلزات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (40%)"}],"at":"2026-10-11T13:13:22.315Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(822, 2, 'عند إزاحة طبقة من الأيونات تتقابل أيونات متشابهة الشحنة (موجب مع موجب وسالب مع سالب) فتتنافر وتنكسر البلورة، ولذلك المركبات الأيونية هشة.', '["الطرق لا يغير شحنات الأيونات.","لا توجد إلكترونات حرة في البلورة الأيونية.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-11T13:13:22.316Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(823, 0, 'التوصيل يحتاج إلى جسيمات مشحونة حرة الحركة، والأيونات في الصلب ثابتة في مواقعها في الشبكة.', '["","المركب الأيوني يتكون من أيونات أصلًا، لكنها غير حرة الحركة في الصلب.","المركب الأيوني يحتوي على أيونات موجبة وأخرى سالبة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-11T13:13:22.316Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(824, 1, 'عند الصهر تتفكك الشبكة البلورية وتتحرر الأيونات K⁺ وBr⁻ فتتحرك وتنقل الشحنة الكهربائية.', '["التوصيل في المصهور الأيوني يتم بحركة الأيونات لا الإلكترونات.","","الذرات المتعادلة لا تنقل الشحنة الكهربائية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-11T13:13:22.316Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(825, 0, 'تعود الألوان الزاهية لبعض الأحجار الكريمة إلى وجود كميات قليلة من أيونات فلزات انتقالية في بلوراتها.', '["","البلورات الأيونية لا تحتوي على إلكترونات حرة.","طاقة الشبكة تتعلق بقوة الرابطة لا بلون البلورة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-10-11T13:13:22.316Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(826, 2, 'الأيونات المقيدة تفسر عدم توصيل الصلب، وتنافر الأيونات المتشابهة عند الإزاحة يفسر التفتت، وتحررها في المحلول يفسر التوصيل.', '["لو وُجدت إلكترونات حرة لوصلت البلورة الكهرباء وهي صلبة.","الجزيئات المتعادلة لا تعطي محلولًا موصلًا، وضعف الترابط لا يفسر صلابة البلورة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-10-11T13:13:22.316Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(827, 1, 'قوة التجاذب الكهروستاتيكي بين الأيونات المرتبة في الشبكة البلورية تجعل المركب صلبًا وقويًا.', '["التنافر يفسر الهشاشة (التفتت) لا الصلابة.","","الأيونات في البلورة الصلبة مقيدة لا حرة الحركة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-11T13:13:22.317Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(828, null, null, null, '(أ) لأن قوى التجاذب الكهروستاتيكي بين الأيونات الموجبة والسالبة في الشبكة البلورية قوية، فيلزم طاقة كبيرة للتغلب عليها. (ب) صلبة لقوة التجاذب بين الأيونات، وهشة لأن إزاحة طبقة من الأيونات تجعل الأيونات المتشابهة الشحنة متقابلة فتتنافر وتتفتت البلورة. (ج) لأن الأيونات في المحلول والمصهور تصبح حرة الحركة فتنقل الشحنات الكهربائية.', '["(أ) قوة التجاذب الكهروستاتيكي وطاقة كبيرة","(ب) الصلابة: قوة التجاذب","(ب) الهشاشة: تنافر الأيونات المتشابهة عند الإزاحة","(ج) الأيونات حرة الحركة"]'::jsonb, '[]'::jsonb, '[{"element":"(أ)","marks":2},{"element":"(ب)","marks":2},{"element":"(ج)","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"التفسيرات الثلاثة صحيحة كاملة"},{"level":"4–5 درجات","description":"تفسيران كاملان وثالث ناقص"},{"level":"2–3 درجات","description":"تفسير واحد كامل"},{"level":"1 درجة","description":"إشارة عامة صحيحة"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["تفسير الهشاشة بضعف الرابطة","تفسير التوصيل بالإلكترونات الحرة","تفسير ارتفاع درجة الانصهار بكبر الكتلة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (40%)"}],"at":"2026-10-11T13:13:22.317Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(829, null, null, null, 'في الوضع الأصلي يتقابل كل أيون Na⁺ في طبقة مع أيون Cl⁻ في الطبقة المجاورة (+ − + − فوق − + − +) فيتجاذبان. عند إزاحة إحدى الطبقتين بمقدار موضع أيون واحد يصبح Na⁺ مقابلًا لـ Na⁺ وCl⁻ مقابلًا لـ Cl⁻ (+ − + − فوق + − + −)، فتتنافر الأيونات المتشابهة الشحنة بقوة، فتنفصل الطبقتان وتتفتت البلورة.', '["الوضع الأصلي: أيونات مختلفة الشحنة متقابلة","بعد الإزاحة: أيونات متشابهة الشحنة متقابلة","التنافر الكهروستاتيكي","انفصال الطبقات وتفتت البلورة"]'::jsonb, '[]'::jsonb, '[{"element":"الرسم/الوصف للوضع الأصلي","marks":1},{"element":"الوضع بعد الإزاحة","marks":1},{"element":"تفسير التفتت بالتنافر","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"رسم أو وصف صحيح للوضعين وتفسير كامل"},{"level":"3 درجات","description":"الوضعان صحيحان مع تفسير ناقص"},{"level":"2 درجتان","description":"تفسير صحيح دون رسم/وصف"},{"level":"1 درجة","description":"وصف الوضع الأصلي فقط"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["رسم أيونات متشابهة متقابلة في الوضع الأصلي","القول إن البلورة تنثني كالفلز","إغفال دور التنافر"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-10-11T13:13:22.317Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(830, null, null, null, '(أ) لا يوصل؛ لأن أيونات K⁺ وCl⁻ مقيدة في مواقع ثابتة في الشبكة البلورية. (ب) يوصل؛ لأن الصهر يفكك الشبكة فتصبح الأيونات حرة الحركة. (ج) يوصل؛ لأن الأيونات تنفصل في الماء وتتحرك بحرية، فالمحلول إلكتروليت.', '["(أ) لا يوصل — أيونات مقيدة","(ب) يوصل — أيونات حرة بعد الصهر","(ج) يوصل — أيونات حرة في المحلول (إلكتروليت)"]'::jsonb, '[]'::jsonb, '[{"element":"(أ)","marks":1},{"element":"(ب)","marks":1},{"element":"(ج)","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"التوقعات الثلاثة صحيحة مع التفسير"},{"level":"2 درجتان","description":"توقعان صحيحان مع التفسير"},{"level":"1 درجة","description":"توقع واحد صحيح أو توقعات دون تفسير"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["توقع توصيل البلورة الصلبة","توقع عدم توصيل المصهور لعدم وجود ماء","تفسير التوصيل بالإلكترونات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-11T13:13:22.318Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(831, 2, 'عدد التأكسد هو عدد الإلكترونات التي تفقدها الذرة أو تكتسبها أو تشارك بها عند تكوين الرابطة، ويساوي شحنة الأيون أحادي الذرة.', '["عدد البروتونات هو العدد الذري لا عدد التأكسد.","هذا تعريف إلكترونات التكافؤ؛ عدد التأكسد يعبر عن الإلكترونات المفقودة أو المكتسبة أو المشارَك بها.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-11T13:13:22.321Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(832, 0, 'عدد تأكسد الأيون أحادي الذرة يساوي شحنته، فمثلًا عدد تأكسد Mg²⁺ هو +2 وعدد تأكسد Cl⁻ هو −1.', '["","العدد الذري يساوي عدد البروتونات ولا يعبّر عن الإلكترونات المفقودة أو المكتسبة.","النيوترونات لا علاقة لها بعدد التأكسد."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-11T13:13:22.321Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(833, 1, 'فقدت ذرة Mg إلكترونين فأصبحت شحنتها +2، وعدد تأكسد الأيون أحادي الذرة يساوي شحنته.', '["الإشارة السالبة تعني اكتساب إلكترونات، والمغنيسيوم فقد إلكترونين.","","12 هو العدد الذري للمغنيسيوم لا عدد تأكسده."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-11T13:13:22.322Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(834, 2, 'اكتسبت ذرة الكبريت إلكترونين لتكمل ثمانيتها فأصبحت شحنتها −2، وهي عدد تأكسدها.', '["الإشارة الموجبة تعني فقد إلكترونات، والكبريت اكتسب إلكترونين.","6 هو عدد إلكترونات تكافؤ الكبريت لا عدد الإلكترونات المكتسبة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-11T13:13:22.322Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(835, 1, 'مجموع أعداد التأكسد في المركب صفر: 2x + 3(−2) = 0 ← 2x = 6 ← x = +3.', '["+2 يجعل مجموع الشحنات 2(+2) + 3(−2) = −2 لا صفرًا.","","+6 هو مجموع الشحنات الموجبة لذرتي الحديد معًا لا عدد تأكسد ذرة واحدة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-11T13:13:22.322Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(836, 0, 'من الجدول: المجموعة 16 عدد تأكسدها −2، والمجموعة 1 عدد تأكسدها +1 (والصيغة Y₂X).', '["","عُكست الإشارتان؛ الفلز (Y) يفقد فيكون موجبًا واللافلز (X) يكتسب فيكون سالبًا.","عناصر المجموعة 1 عدد تأكسدها +1 لا +2."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-11T13:13:22.323Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(837, 2, 'الحديد من الفلزات متعددة التكافؤ؛ له عددا تأكسد +2 (Fe²⁺) و+3 (Fe³⁺).', '["الصوديوم عدد تأكسده +1 فقط.","المغنيسيوم عدد تأكسده +2 فقط.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-11T13:13:22.323Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(838, null, null, null, 'عدد التأكسد: عدد الإلكترونات التي تفقدها الذرة أو تكتسبها أو تشارك بها عند تكوين الرابطة (ويساوي شحنة الأيون أحادي الذرة). Na⁺: +1 ، O²⁻: −2 ، Al³⁺: +3 ، Cl⁻: −1. الإشارة الموجبة تعني أن الذرة فقدت إلكترونات، والإشارة السالبة تعني أنها اكتسبت إلكترونات.', '["التعريف","أعداد التأكسد الأربعة صحيحة","الموجبة = فقد","السالبة = اكتساب"]'::jsonb, '[]'::jsonb, '[{"element":"التعريف","marks":1},{"element":"أعداد التأكسد الأربعة","marks":2},{"element":"معنى الإشارتين","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة"},{"level":"3 درجات","description":"خطأ في عدد تأكسد واحد"},{"level":"2 درجتان","description":"تعريف مع عددين صحيحين أو أعداد صحيحة دون تعريف"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["كتابة عدد التأكسد دون إشارة","عكس معنى الإشارتين","الخلط بين عدد التأكسد والعدد الذري"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-11T13:13:22.323Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(839, null, null, null, 'مجموع أعداد التأكسد في المركب المتعادل يساوي صفرًا. (أ) x + 3(−1) = 0 ← x = +3. (ب) x + (−2) = 0 ← x = +2. (ج) x + 2(−2) = 0 ← x = +4.', '["قاعدة مجموع أعداد التأكسد = صفر","Fe = +3","Cu = +2","Pb = +4"]'::jsonb, '["FeCl₃: x + 3(−1) = 0 ← x = +3","CuO: x + (−2) = 0 ← x = +2","PbO₂: x + 2(−2) = 0 ← x = +4"]'::jsonb, '[{"element":"القاعدة","marks":1},{"element":"(أ)","marks":1},{"element":"(ب)","marks":1},{"element":"(ج)","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"القاعدة والنتائج الثلاث صحيحة"},{"level":"3 درجات","description":"نتيجتان صحيحتان مع القاعدة"},{"level":"2 درجتان","description":"نتيجة واحدة مع القاعدة أو نتائج دون خطوات"},{"level":"1 درجة","description":"كتابة القاعدة فقط"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["إهمال عدد الذرات (الأرقام السفلية) عند الجمع","كتابة Pb = +2 دون حساب","نسيان الإشارة الموجبة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-11T13:13:22.324Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(840, null, null, null, 'عناصر المجموعة 2 لها إلكترونا تكافؤ تفقدهما للوصول إلى تركيب الغاز النبيل فيصبح عدد تأكسدها +2. وعناصر المجموعة 17 لها 7 إلكترونات تكافؤ فتكتسب إلكترونًا واحدًا لتكمل ثمانيتها فيصبح عدد تأكسدها −1. التوقعات: Ca = +2 ، P = −3 ، I = −1.', '["المجموعة 2: فقد إلكترونين","المجموعة 17: اكتساب إلكترون","Ca = +2","P = −3","I = −1"]'::jsonb, '[]'::jsonb, '[{"element":"تفسير المجموعة 2","marks":1},{"element":"تفسير المجموعة 17","marks":1},{"element":"التوقعات الثلاثة","marks":3}]'::jsonb, '[{"level":"5 درجات","description":"تفسيران وتوقعات صحيحة"},{"level":"3–4 درجات","description":"خطأ في توقع واحد أو تفسير ناقص"},{"level":"1–2 درجة","description":"توقعات فقط دون تفسير"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["كتابة P = +5 بالاعتماد على عدد إلكترونات التكافؤ","كتابة I = +7","عدم الربط بإلكترونات التكافؤ"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-11T13:13:22.325Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(841, 1, 'Ca²⁺ وCl⁻: نبدّل أعداد التأكسد فنحصل على CaCl₂، ومجموع الشحنات (+2) + 2(−1) = 0.', '["لم تُراعَ شحنة Ca²⁺؛ الصيغة CaCl مجموع شحناتها +1.","","عُكس التبديل؛ Ca₂Cl مجموع شحناتها 2(+2) + (−1) = +3."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (50%)"}],"at":"2026-10-11T13:13:22.331Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(842, 2, 'Al³⁺ وO²⁻: بتبديل أعداد التأكسد نحصل على Al₂O₃، ومجموع الشحنات 2(+3) + 3(−2) = 0.', '["AlO مجموع شحناتها (+3) + (−2) = +1، فهي غير متعادلة.","عُكس التبديل: Al₃O₂ مجموع شحناتها 3(+3) + 2(−2) = +5.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-10-11T13:13:22.332Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(843, 2, 'من خطوات كتابة الصيغة: يُكتب رمز الأيون الموجب (الفلز) أولًا على اليسار ثم رمز الأيون السالب.', '["الأيون السالب يُكتب في الصيغة ثانيًا (يمينًا)، وإن كان يُذكر أولًا في الاسم العربي.","ترتيب الرموز في الصيغة لا يعتمد على الكتلة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-11T13:13:22.332Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(844, 1, 'Mg²⁺ وN³⁻: بتبديل أعداد التأكسد نحصل على Mg₃N₂، ومجموع الشحنات 3(+2) + 2(−3) = 0.', '["عُكس التبديل؛ Mg₂N₃ مجموع شحناتها 2(+2) + 3(−3) = −5.","","MgN مجموع شحناتها (+2) + (−3) = −1، فهي غير متعادلة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-10-11T13:13:22.332Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(845, 0, 'بعد التبديل تُختصر الأرقام إلى أبسط نسبة: Mg₂O₂ ← MgO، لأن وحدة الصيغة تمثل أبسط نسبة للأيونات.', '["","Mg₂O₂ لم تُختصر؛ الصيغة تعبر عن أبسط نسبة بين الأيونات.","MgO₂ مجموع شحناتها (+2) + 2(−2) = −2، فهي غير متعادلة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-11T13:13:22.332Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(846, 2, 'Fe³⁺ وS²⁻: بالتبديل نحصل على Fe₂S₃، ومجموع الشحنات 2(+3) + 3(−2) = 0.', '["FeS صيغة كبريتيد الحديد (II) حيث شحنة الحديد +2.","عُكس التبديل: Fe₃S₂ مجموع شحناتها 3(+3) + 2(−2) = +5.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-11T13:13:22.333Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(847, 1, 'الرقم الروماني (II) يعني أن شحنة الحديد +2: Fe²⁺ وCl⁻ ← FeCl₂.', '["FeCl₃ صيغة كلوريد الحديد (III).","","عُكس التبديل؛ Fe₂Cl مجموع شحناتها 2(+2) + (−1) = +3."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (50%)"}],"at":"2026-10-11T13:13:22.333Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(848, null, null, null, '1) رمز الأيون الموجب يسارًا وشحنته: Al³⁺، ورمز الأيون السالب يمينًا وشحنته: S²⁻. 2) تبديل أعداد التأكسد (بدون إشارات): يصبح عدد التأكسد لأحدهما رقمًا سفليًا للآخر: Al₂S₃. 3) الاختصار إن أمكن: 2 و3 لا يختصران. التحقق: 2(+3) + 3(−2) = +6 − 6 = 0.', '["كتابة Al³⁺ وS²⁻ بالترتيب الصحيح","تبديل أعداد التأكسد","التحقق من إمكانية الاختصار","الصيغة Al₂S₃","التحقق من التعادل"]'::jsonb, '["Al³⁺ ، S²⁻","التبديل: Al₂S₃","لا اختصار","2(+3) + 3(−2) = 0"]'::jsonb, '[{"element":"كتابة الأيونين وشحنتيهما","marks":1},{"element":"التبديل والاختصار","marks":2},{"element":"الصيغة الصحيحة","marks":1},{"element":"التحقق من التعادل","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"خطوات كاملة وصيغة صحيحة وتحقق"},{"level":"3–4 درجات","description":"صيغة صحيحة مع نقص في الخطوات أو التحقق"},{"level":"1–2 درجة","description":"شحنات صحيحة مع صيغة خاطئة"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["كتابة Al₃S₂","كتابة الإشارات أرقامًا سفلية","كتابة الأيون السالب أولًا في الصيغة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-11T13:13:22.333Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(849, null, null, null, '(أ) Na⁺ وN³⁻ ← Na₃N. (ب) Ba²⁺ وBr⁻ ← BaBr₂. (ج) Sn⁴⁺ وO²⁻ ← Sn₂O₄ ← بالاختصار SnO₂. (د) Cu⁺ وO²⁻ ← Cu₂O.', '["Na₃N","BaBr₂","SnO₂ (مع الاختصار)","Cu₂O"]'::jsonb, '["Na₃N: 3(+1) + (−3) = 0","BaBr₂: (+2) + 2(−1) = 0","SnO₂: (+4) + 2(−2) = 0","Cu₂O: 2(+1) + (−2) = 0"]'::jsonb, '[{"element":"(أ)","marks":1},{"element":"(ب)","marks":1},{"element":"(ج)","marks":1},{"element":"(د)","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"الصيغ الأربع صحيحة"},{"level":"3 درجات","description":"ثلاث صيغ صحيحة"},{"level":"2 درجتان","description":"صيغتان صحيحتان"},{"level":"1 درجة","description":"صيغة واحدة صحيحة"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["كتابة Sn₂O₄ دون اختصار","كتابة CuO لأكسيد النحاس (I)","كتابة NaN₃ بعكس التبديل"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-10-11T13:13:22.333Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(850, null, null, null, 'Ca₂O₂: لم تُختصر النسبة، والصحيح CaO لأن (+2) + (−2) = 0. KCl₂: شحنة K⁺ هي +1 فلا يلزم إلا أيون كلوريد واحد، والصحيح KCl لأن (+1) + (−1) = 0. Al₃N₃: Al³⁺ وN³⁻ شحنتاهما متساويتان في المقدار فالنسبة 1:1 بعد الاختصار، والصحيح AlN لأن (+3) + (−3) = 0.', '["خطأ Ca₂O₂ (عدم الاختصار) والتصحيح CaO","خطأ KCl₂ (شحنة K) والتصحيح KCl","خطأ Al₃N₃ (عدم الاختصار) والتصحيح AlN","التحقق من التعادل"]'::jsonb, '["CaO: +2 − 2 = 0","KCl: +1 − 1 = 0","AlN: +3 − 3 = 0"]'::jsonb, '[{"element":"Ca₂O₂","marks":2},{"element":"KCl₂","marks":2},{"element":"Al₃N₃","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"تحديد الأخطاء الثلاثة وتصحيحها مع التحقق"},{"level":"4–5 درجات","description":"تصحيح الثلاثة دون تحديد سبب الخطأ في إحداها"},{"level":"2–3 درجات","description":"تصحيح صيغة أو صيغتين"},{"level":"1 درجة","description":"تحديد خطأ واحد دون تصحيح"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["قبول Ca₂O₂ لأنها متعادلة دون الانتباه إلى أبسط نسبة","تصحيح KCl₂ إلى K₂Cl","عدم ذكر سبب الخطأ"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-11T13:13:22.334Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(851, 0, 'Ca²⁺ وNO₃⁻: يلزم أيونا نترات، ويوضع الشق بين قوسين لأنه يتكرر: Ca(NO₃)₂.', '["","حُذفت الأقواس فأصبح الرقم 2 كأنه يخص الأكسجين وحده (O₃₂)، وهذا خطأ.","عُكس التبديل؛ Ca₂NO₃ مجموع شحناتها 2(+2) + (−1) = +3."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (60%)"}],"at":"2026-10-11T13:13:22.337Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(852, 2, 'NH₄⁺ وSO₄²⁻: يلزم أيونا أمونيوم لكل أيون كبريتات، فيوضع الأمونيوم بين قوسين: (NH₄)₂SO₄.', '["NH₄SO₄ مجموع شحناتها (+1) + (−2) = −1، فهي غير متعادلة.","عُكس التبديل؛ هذه الصيغة مجموع شحناتها (+1) + 2(−2) = −3.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-10-11T13:13:22.337Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(853, 1, 'يوضع الأيون عديد الذرات بين قوسين ويكتب الرقم السفلي خارجهما عندما يتكرر في الصيغة، مثل Al(OH)₃.', '["إذا كان الأيون عديد الذرات واحدًا فلا حاجة إلى الأقواس (مثل NaNO₃).","","الأقواس خاصة بالأيونات عديدة الذرات المتكررة لا بالأيونات أحادية الذرة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-11T13:13:22.337Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(854, 0, 'Ca²⁺ وPO₄³⁻: بالتبديل نحصل على Ca₃(PO₄)₂، ومجموع الشحنات 3(+2) + 2(−3) = 0.', '["","عُكس التبديل؛ Ca₂(PO₄)₃ مجموع شحناتها 2(+2) + 3(−3) = −5.","CaPO₄ مجموع شحناتها (+2) + (−3) = −1، فهي غير متعادلة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (60%)"}],"at":"2026-10-11T13:13:22.337Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(855, 2, 'الرقم خارج القوس يضرب في كل ما بداخله: 4 × 3 = 12 ذرة أكسجين.', '["أُهمل الرقم 3 خارج القوس الذي يضاعف كل ما بداخله.","جُمع الرقمان (4 + 3) بدل ضربهما.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-11T13:13:22.338Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(856, 2, 'NH₄⁺ وCO₃²⁻: يلزم أيونا أمونيوم لكل أيون كربونات: (NH₄)₂CO₃، ومجموع الشحنات 2(+1) + (−2) = 0.', '["NH₄CO₃ مجموع شحناتها (+1) + (−2) = −1.","عُكس التبديل؛ هذه الصيغة مجموع شحناتها (+1) + 2(−2) = −3.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-11T13:13:22.338Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(857, 0, 'Na⁺ وHCO₃⁻ شحنتاهما متساويتان في المقدار، فالنسبة 1:1 والصيغة NaHCO₃ دون أقواس.', '["","Na₂HCO₃ مجموع شحناتها 2(+1) + (−1) = +1؛ شحنة HCO₃⁻ هي −1 لا −2.","Na(HCO₃)₂ مجموع شحناتها (+1) + 2(−1) = −1."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-11T13:13:22.338Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(858, null, null, null, 'Al³⁺ وOH⁻: نكتب الأيون الموجب يسارًا ثم الأيون السالب، ونبدل أعداد التأكسد فنحصل على Al(OH)₃. تُستخدم الأقواس لأن الشق OH⁻ أيون عديد الذرات يتكرر ثلاث مرات، والرقم 3 خارج القوس يضاعف الأكسجين والهيدروجين معًا. العدد الكلي للذرات: Al = 1، O = 3، H = 3، المجموع 7 ذرات.', '["Al³⁺ وOH⁻","التبديل ← Al(OH)₃","تفسير الأقواس","حساب الذرات = 7"]'::jsonb, '["Al³⁺ ، OH⁻","التبديل: Al(OH)₃","التحقق: (+3) + 3(−1) = 0","الذرات: 1 + 3 + 3 = 7"]'::jsonb, '[{"element":"الأيونان وشحنتاهما","marks":1},{"element":"الصيغة الصحيحة","marks":1},{"element":"تفسير الأقواس","marks":1},{"element":"حساب عدد الذرات","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة"},{"level":"3 درجات","description":"صيغة صحيحة مع خطأ في عدد الذرات أو تفسير ناقص"},{"level":"2 درجتان","description":"صيغة صحيحة فقط"},{"level":"1 درجة","description":"شحنات صحيحة مع صيغة خاطئة"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["كتابة AlOH₃ دون أقواس","حساب الذرات 5 بإهمال تضاعف الهيدروجين","كتابة Al₃OH"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-11T13:13:22.339Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(859, null, null, null, '(أ) Mg²⁺ وPO₄³⁻ ← Mg₃(PO₄)₂. (ب) NH₄⁺ وNO₃⁻ ← NH₄NO₃. (ج) Fe³⁺ وSO₄²⁻ ← Fe₂(SO₄)₃. (د) K⁺ وMnO₄⁻ ← KMnO₄.', '["Mg₃(PO₄)₂","NH₄NO₃","Fe₂(SO₄)₃","KMnO₄"]'::jsonb, '["Mg₃(PO₄)₂: 3(+2) + 2(−3) = 0","NH₄NO₃: (+1) + (−1) = 0","Fe₂(SO₄)₃: 2(+3) + 3(−2) = 0","KMnO₄: (+1) + (−1) = 0"]'::jsonb, '[{"element":"(أ)","marks":1},{"element":"(ب)","marks":1},{"element":"(ج)","marks":1},{"element":"(د)","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"الصيغ الأربع صحيحة"},{"level":"3 درجات","description":"ثلاث صيغ صحيحة"},{"level":"2 درجتان","description":"صيغتان صحيحتان"},{"level":"1 درجة","description":"صيغة واحدة صحيحة"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["كتابة Mg₃PO₄₂ دون أقواس","كتابة FeSO₄ لكبريتات الحديد (III)","كتابة N₂H₄O₃ لنترات الأمونيوم بدمج الذرات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-11T13:13:22.342Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(860, null, null, null, 'NH₄₂S: يجب وضع الأمونيوم بين قوسين لأنه يتكرر مرتين، والصحيح (NH₄)₂S (وإلا فُهم أن عدد ذرات H هو 42). CaOH₂: يجب وضع الهيدروكسيد بين قوسين لأنه يتكرر، والصحيح Ca(OH)₂ (وإلا فُهم أن H وحده مضاعف). Na₂(SO₄): لا حاجة إلى الأقواس لأن أيون الكبريتات واحد فقط، والصحيح Na₂SO₄. القاعدة: يوضع الأيون عديد الذرات بين قوسين فقط عندما يتكرر أكثر من مرة في الصيغة.', '["تصحيح (NH₄)₂S مع السبب","تصحيح Ca(OH)₂ مع السبب","تصحيح Na₂SO₄ (حذف الأقواس)","صياغة قاعدة الأقواس"]'::jsonb, '[]'::jsonb, '[{"element":"(NH₄)₂S","marks":1},{"element":"Ca(OH)₂","marks":1},{"element":"Na₂SO₄","marks":1},{"element":"القاعدة","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"تصحيحات وأسباب وقاعدة صحيحة"},{"level":"3–4 درجات","description":"تصحيحات صحيحة مع قاعدة ناقصة"},{"level":"1–2 درجة","description":"تصحيح أو اثنان فقط"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["اعتبار Na₂(SO₄) صحيحة تمامًا","تصحيح CaOH₂ إلى Ca₂OH","عدم ذكر القاعدة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-11T13:13:22.342Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(861, 0, 'الأيون أحادي الذرة ذرة عنصر واحدة مشحونة، مثل Mg²⁺ وCl⁻.', '["","هذا تعريف الأيون عديد الذرات.","الجزيء ثنائي الذرة (مثل Cl₂) متعادل وليس أيونًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-10-11T13:13:22.346Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(862, 2, 'Mg²⁺ ذرة مغنيسيوم واحدة فقدت إلكترونين، فهو أيون أحادي الذرة.', '["NH₄⁺ يتكون من خمس ذرات (N وأربع H) فهو عديد الذرات.","SO₄²⁻ يتكون من خمس ذرات (S وأربع O) فهو عديد الذرات.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-10-11T13:13:22.347Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(863, 0, 'الأيون عديد الذرات مجموعة من الذرات المترابطة تسلك سلوك وحدة واحدة وتحمل شحنة، مثل NH₄⁺ وSO₄²⁻.', '["","الذرة الواحدة التي فقدت عدة إلكترونات تبقى أيونًا أحادي الذرة (مثل Al³⁺).","الأيون عديد الذرات وحدة واحدة مترابطة، لا أيونات منفصلة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-10-11T13:13:22.347Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(864, 1, 'NO₃⁻ (4 ذرات) وOH⁻ (ذرتان) وCO₃²⁻ (4 ذرات) كلها مجموعات ذرات مشحونة، فهي أيونات عديدة الذرات.', '["Cl⁻ وS²⁻ أيونان أحاديا الذرة.","","جميعها أيونات أحادية الذرة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-11T13:13:22.347Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(865, 2, 'O²⁻ (أكسيد) ذرة واحدة مشحونة، أما OH⁻ (هيدروكسيد) فذرتان مترابطتان تحملان شحنة واحدة.', '["OH⁻ يتكون من ذرتين (O وH)، فليس أحادي الذرة.","O²⁻ ذرة أكسجين واحدة مشحونة، فليس عديد الذرات.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-11T13:13:22.347Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(866, 0, 'الأيونات عديدة الذرات: CN⁻ (ذرتان) وNH₄⁺ (5 ذرات) وPO₄³⁻ (5 ذرات)، أما Br⁻ وCa²⁺ فأحاديا الذرة.', '["","ربما لم يُعدّ CN⁻ عديد الذرات لأنه من ذرتين فقط؛ وهو عديد الذرات.","Br⁻ وCa²⁺ أحاديا الذرة فلا يُعدّان."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-10-11T13:13:22.347Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(867, 2, 'Cl₂ جزيء ثنائي الذرة متعادل لا يحمل شحنة، فهو ليس أيونًا أصلًا.', '["CN⁻ ذرتان مترابطتان تحملان شحنة، فهو أيون عديد الذرات.","NH₄⁺ مجموعة ذرات مشحونة، فهو أيون عديد الذرات.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-10-11T13:13:22.348Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(868, null, null, null, 'الأيون أحادي الذرة: ذرة عنصر واحدة تحمل شحنة، مثل Na⁺ (موجب) وCl⁻ (سالب). الأيون عديد الذرات: مجموعة ذرات مترابطة تحمل شحنة كهربائية، مثل NH₄⁺ (موجب) وSO₄²⁻ (سالب).', '["تعريف الأيون أحادي الذرة","تعريف الأيون عديد الذرات","مثالان صحيحان لأحادي الذرة (موجب وسالب)","مثالان صحيحان لعديد الذرات (موجب وسالب)"]'::jsonb, '[]'::jsonb, '[{"element":"التعريفان","marks":2},{"element":"أمثلة أحادي الذرة","marks":1},{"element":"أمثلة عديد الذرات","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تعريفان وأربعة أمثلة صحيحة"},{"level":"3 درجات","description":"تعريفان مع نقص في الأمثلة"},{"level":"2 درجتان","description":"تعريف واحد مع أمثلته أو أمثلة فقط"},{"level":"1 درجة","description":"مثال واحد صحيح"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["اعتبار Al³⁺ عديد الذرات لأن شحنته كبيرة","اعتبار الجزيئات مثل O₂ أيونات عديدة الذرات","ذكر مثال سالب فقط لعديد الذرات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-11T13:13:22.348Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(869, null, null, null, 'أحادية الذرة: Na⁺ ، Br⁻ ، Al³⁺ ، N³⁻. عديدة الذرات: SO₄²⁻ (5 ذرات)، NH₄⁺ (5 ذرات)، CN⁻ (ذرتان)، CO₃²⁻ (4 ذرات).', '["الأيونات الأربعة أحادية الذرة","الأيونات الأربعة عديدة الذرات","عدد ذرات كل أيون عديد الذرات"]'::jsonb, '["SO₄²⁻: 1 + 4 = 5","NH₄⁺: 1 + 4 = 5","CN⁻: 1 + 1 = 2","CO₃²⁻: 1 + 3 = 4"]'::jsonb, '[{"element":"تصنيف أحادية الذرة","marks":2},{"element":"تصنيف عديدة الذرات","marks":2},{"element":"عدد الذرات","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"تصنيف كامل وأعداد ذرات صحيحة"},{"level":"4–5 درجات","description":"خطأ واحد أو اثنان"},{"level":"2–3 درجات","description":"تصنيف نصف الأيونات صحيحًا"},{"level":"1 درجة","description":"تصنيف أيون أو اثنين"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["تصنيف CN⁻ أحادي الذرة لقلة ذراته","تصنيف Al³⁺ عديد الذرات لأن شحنته +3","عدّ ذرات CO₃²⁻ ثلاثًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-11T13:13:22.348Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(870, null, null, null, 'S²⁻: أحادي الذرة، ذرة واحدة، اسمه الكبريتيد، شحنته −2. SO₄²⁻: عديد الذرات، 5 ذرات (S وأربع O)، اسمه الكبريتات، شحنته −2. الشحنة −2 في SO₄²⁻ تعود إلى المجموعة كلها بوصفها وحدة واحدة، لا إلى ذرة بعينها.', '["S²⁻ أحادي وSO₄²⁻ عديد","ذرة واحدة مقابل 5 ذرات","كبريتيد مقابل كبريتات","الشحنة −2 في كليهما","الشحنة تخص المجموعة كلها"]'::jsonb, '[]'::jsonb, '[{"element":"نوع الأيون وعدد الذرات","marks":2},{"element":"الاسم والشحنة","marks":2},{"element":"توضيح الشحنة في SO₄²⁻","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"مقارنة كاملة وتوضيح صحيح"},{"level":"3–4 درجات","description":"مقارنة صحيحة مع توضيح ناقص"},{"level":"1–2 درجة","description":"وجه أو وجهان صحيحان"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["تسمية SO₄²⁻ كبريتيد","القول إن الشحنة على ذرة الكبريت وحدها","عدّ ذرات SO₄²⁻ أربعًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-11T13:13:22.348Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(871, 1, 'قاعدة التسمية: اسم الأيون السالب أولًا بإضافة المقطع «يد» (بروم ← بروميد) ثم اسم الفلز: بروميد الكالسيوم.', '["في العربية يُذكر الأيون السالب أولًا ثم الموجب، ويُضاف المقطع «يد» إلى اسم اللافلز.","","لم يُضف المقطع «يد» إلى اسم الأيون السالب أحادي الذرة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (60%)"}],"at":"2026-10-11T13:13:22.351Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(872, 2, 'عدد تأكسد الحديد: 2x + 3(−2) = 0 ← x = +3، فالاسم أكسيد الحديد (III).', '["«الحديدوز» اسم قديم لأيون الحديد (II)، أما الحديد (III) فاسمه القديم «الحديديك».","الرقم الروماني يمثل عدد تأكسد ذرة حديد واحدة (+3) لا مجموع شحنتي الذرتين (+6).",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (60%)"}],"at":"2026-10-11T13:13:22.352Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(873, 0, 'NO₃⁻ هو أيون النترات، وهو من الأيونات عديدة الذرات في جدول المذكرة.', '["","النيتريد اسم الأيون أحادي الذرة N³⁻.","النيتروجين اسم العنصر لا اسم الأيون."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-10-11T13:13:22.352Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(874, 1, 'شحنة NO₃⁻ هي −1 وفي الصيغة أيونان منه، فعدد تأكسد النحاس +2، والاسم نترات النحاس (II).', '["يلزم أيونا نترات لكل أيون نحاس، فشحنة النحاس +2 لا +1.","","النيتريد هو N³⁻، أما NO₃⁻ فاسمه النترات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (50%)"}],"at":"2026-10-11T13:13:22.352Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(875, 2, 'يُكتب عدد تأكسد الفلز بالرقم الروماني بين قوسين إذا كان الفلز متعدد التكافؤ (مثل Fe وCu وPb وSn) لتمييز المركبات.', '["وجود أيون عديد الذرات لا يستلزم رقمًا رومانيًا (مثل نترات الصوديوم).","عدد ذرات اللافلز لا يُكتب بالرقم الروماني (مثل كلوريد المغنيسيوم MgCl₂).",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (3%)"}],"at":"2026-10-11T13:13:22.352Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(876, 0, 'Cu₃PO₄: شحنة PO₄³⁻ هي −3 وفي الصيغة 3 ذرات نحاس، فعدد تأكسد النحاس +1، والاسم الصحيح فوسفات النحاس (I).', '["","FeSO₄: شحنة SO₄²⁻ هي −2 فعدد تأكسد الحديد +2، والاسم كبريتات الحديد (II) صحيح.","(NH₄)₂S: أيونا أمونيوم وأيون كبريتيد S²⁻، والاسم كبريتيد الأمونيوم صحيح."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-10-11T13:13:22.352Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.')
