(877, 2, 'SO₄²⁻ أيون عديد الذرات اسمه الكبريتات، فالمركب كبريتات الصوديوم.', '["كبريتيد الصوديوم اسم Na₂S الذي يحتوي على الأيون أحادي الذرة S²⁻.","«كبريت» اسم العنصر، ولا يسمى به الأيون عديد الذرات.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (60%)"}],"at":"2026-10-11T13:13:22.353Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(878, null, null, null, '(أ) كلوريد الخارصين (الخارصين له عدد تأكسد واحد +2 فلا يلزم رقم روماني). (ب) كبريتات الفضة. (ج) كربونات الحديد (III)؛ لأن 2x + 3(−2) = 0 ← x = +3. (د) هيدروكسيد الكالسيوم.', '["كلوريد الخارصين","كبريتات الفضة","كربونات الحديد (III) مع تحديد عدد التأكسد","هيدروكسيد الكالسيوم"]'::jsonb, '["Fe₂(CO₃)₃: 2x + 3(−2) = 0 ← x = +3"]'::jsonb, '[{"element":"(أ)","marks":1},{"element":"(ب)","marks":1},{"element":"(ج)","marks":1},{"element":"(د)","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"الأسماء الأربعة صحيحة"},{"level":"3 درجات","description":"ثلاثة أسماء صحيحة"},{"level":"2 درجتان","description":"اسمان صحيحان"},{"level":"1 درجة","description":"اسم واحد صحيح"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["كتابة كربونات الحديد (II) أو (VI)","إضافة رقم روماني للخارصين أو الفضة","تسمية OH⁻ «أكسيد»"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-10-11T13:13:22.353Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(879, null, null, null, 'NH₄⁺ أمونيوم (+1)، OH⁻ هيدروكسيد (−1)، HCO₃⁻ كربونات هيدروجينية/بيكربونات (−1)، MnO₄⁻ برمنجنات (−1)، CO₃²⁻ كربونات (−2)، PO₄³⁻ فوسفات (−3). NH₄Cl: كلوريد الأمونيوم. K₃PO₄: فوسفات البوتاسيوم.', '["أسماء الأيونات الستة","شحناتها الصحيحة","كلوريد الأمونيوم","فوسفات البوتاسيوم"]'::jsonb, '[]'::jsonb, '[{"element":"أسماء الأيونات وشحناتها","marks":3},{"element":"كلوريد الأمونيوم","marks":1},{"element":"فوسفات البوتاسيوم","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة صحيحة"},{"level":"3–4 درجات","description":"خطأ في اسم أو اثنين"},{"level":"1–2 درجة","description":"نصف الأسماء صحيحة"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["الخلط بين كربونات وبيكربونات","تسمية NH₄⁺ «أمونيا»","تسمية K₃PO₄ «فوسفات البوتاسيوم (III)»"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-10-11T13:13:22.353Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(880, null, null, null, '(أ) CuO: x + (−2) = 0 ← x = +2، والاسم أكسيد النحاس (II). Cu₂O: 2x + (−2) = 0 ← x = +1، والاسم أكسيد النحاس (I). (ب) الجزء الأول صحيح؛ عدد تأكسد الحديد في Fe₂O₃ هو +3 فالاسم أكسيد الحديد (III). أما «الحديدوز» فخطأ لأنه الاسم القديم للحديد (II)، والاسم القديم الصحيح للحديد (III) هو «الحديديك»، فيُسمى أكسيد الحديديك.', '["CuO: +2 ← أكسيد النحاس (II)","Cu₂O: +1 ← أكسيد النحاس (I)","Fe₂O₃: الحديد +3","الحديدوز للحديد (II) والحديديك للحديد (III)"]'::jsonb, '["CuO: x − 2 = 0 ← x = +2","Cu₂O: 2x − 2 = 0 ← x = +1","Fe₂O₃: 2x − 6 = 0 ← x = +3"]'::jsonb, '[{"element":"تسمية CuO مع الحساب","marks":1},{"element":"تسمية Cu₂O مع الحساب","marks":1},{"element":"تقويم العبارة","marks":1},{"element":"التصحيح","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تسميتان صحيحتان وتقويم وتصحيح كاملان"},{"level":"3 درجات","description":"خطأ في عنصر واحد"},{"level":"2 درجتان","description":"تسميتان صحيحتان فقط أو التقويم فقط"},{"level":"1 درجة","description":"تسمية واحدة صحيحة"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["تسمية Cu₂O أكسيد النحاس (II) لوجود ذرتين","قبول «الحديدوز» للحديد (III)","عدم إظهار الحساب"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (4%)"}],"at":"2026-10-11T13:13:22.353Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(881, 1, 'الرابطة الفلزية قوة التجاذب بين الأيونات الفلزية الموجبة وبحر الإلكترونات الحرة (غير المتمركزة) المحيطة بها.', '["هذا وصف الرابطة الأيونية.","","المشاركة بين لافلزين لا تمثل الرابطة الفلزية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-11T13:13:22.356Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(882, 0, 'تتداخل مستويات الطاقة الخارجية لذرات الفلز، فتتحرر إلكترونات التكافؤ وتتحرك بحرية بين الأيونات الموجبة على شكل «بحر».', '["","في الفلز لا ترتبط إلكترونات التكافؤ بذرة معينة.","لا توجد ذرات لافلز في الفلز النقي تستقبل الإلكترونات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-11T13:13:22.357Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(883, 2, 'تتكون الرابطة الفلزية بين ذرات العنصر الفلزي في الشبكة البلورية للفلز (كما توجد في السبائك).', '["التجاذب بين أيونات فلز وأيونات لافلز يمثل الرابطة الأيونية.","اللافلزات لا تكوّن بحرًا من الإلكترونات الحرة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-10-11T13:13:22.357Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(884, 1, 'تتكون الشبكة من أيونات فلزية موجبة في مواقع منتظمة يحيط بها بحر من الإلكترونات الحرة.', '["لا توجد أيونات سالبة في الفلز النقي.","","الذرات تفقد إلكترونات تكافئها لتصبح أيونات موجبة، ولا توجد أيونات سالبة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-10-11T13:13:22.357Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(885, 2, 'في الرابطة الفلزية تجاذب بين أيونات موجبة وبحر من الإلكترونات الحرة، وفي الأيونية تجاذب بين أيونات موجبة وأيونات سالبة.', '["عُكس الوصف بين النوعين.","الرابطة الفلزية لا تحتوي على أيونات سالبة، بل إلكترونات حرة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-10-11T13:13:22.357Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(886, 0, 'النموذج 1 يصف أيونات موجبة منتظمة يحيط بها بحر من الإلكترونات المتحركة، وهذا نموذج بحر الإلكترونات للرابطة الفلزية.', '["","النموذج 2 يمثل بلورة أيونية (أيونات موجبة وسالبة متبادلة).","النموذج 3 يصف مشاركة الإلكترونات بين ذرتين، لا الرابطة الفلزية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-11T13:13:22.358Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(887, 2, 'الإلكترونات الحرة تحيط بالأيونات في كل موضع، فعند الطرق تنزلق الأيونات بعضها فوق بعض ويبقى بحر الإلكترونات رابطًا لها.', '["هذا تفسير هشاشة المركبات الأيونية لا قابلية الفلزات للطرق.","الإلكترونات في الفلز حرة الحركة لا ثابتة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-10-11T13:13:22.358Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(888, null, null, null, 'الرابطة الفلزية: قوة التجاذب بين الأيونات الفلزية الموجبة والإلكترونات الحرة المحيطة بها. نموذج بحر الإلكترونات: تترتب ذرات الفلز في شبكة بلورية، وتتداخل مستويات طاقتها الخارجية فتتحرر إلكترونات التكافؤ من ذراتها وتصبح غير متمركزة، تتحرك بحرية بين الأيونات الموجبة على شكل بحر لا يرتبط بذرة معينة.', '["تعريف الرابطة الفلزية","مصدر الإلكترونات: إلكترونات التكافؤ","تداخل المستويات الخارجية","الإلكترونات غير متمركزة وحرة الحركة","الأيونات الموجبة في شبكة"]'::jsonb, '[]'::jsonb, '[{"element":"التعريف","marks":2},{"element":"مصدر الإلكترونات الحرة","marks":1},{"element":"طبيعة حركتها","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تعريف ووصف كاملان"},{"level":"3 درجات","description":"تعريف صحيح ووصف ناقص"},{"level":"2 درجتان","description":"تعريف فقط أو وصف فقط"},{"level":"1 درجة","description":"ذكر الإلكترونات الحرة فقط"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["تعريف الرابطة الفلزية بأنها تجاذب بين أيونات موجبة وسالبة","القول إن الإلكترونات تأتي من مستويات داخلية","القول إن الإلكترونات مرتبطة بذرات محددة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-11T13:13:22.358Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(889, null, null, null, 'الرابطة الفلزية: الجسيمات أيونات موجبة وإلكترونات حرة؛ تتكون بين ذرات الفلزات؛ إلكترونات التكافؤ غير متمركزة تتحرك بحرية بين الأيونات. الرابطة الأيونية: الجسيمات أيونات موجبة وأيونات سالبة؛ تتكون بين فلز ولافلز؛ إلكترونات التكافؤ تنتقل من الفلز إلى اللافلز وتستقر فيه.', '["الجسيمات في الفلزية","الجسيمات في الأيونية","فلز-فلز مقابل فلز-لافلز","إلكترونات حرة مقابل إلكترونات منتقلة"]'::jsonb, '[]'::jsonb, '[{"element":"الجسيمات المتجاذبة","marks":2},{"element":"نوع العناصر","marks":2},{"element":"سلوك الإلكترونات","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"مقارنة كاملة دقيقة"},{"level":"4–5 درجات","description":"وجهان كاملان وثالث ناقص"},{"level":"2–3 درجات","description":"وجه واحد كامل"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["القول إن الرابطة الفلزية تحتوي على أيونات سالبة","القول إن الإلكترونات في الأيونية حرة","القول إن الرابطة الفلزية بين فلز ولافلز"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-10-11T13:13:22.358Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(890, null, null, null, 'تفقد كل ذرة مغنيسيوم إلكتروني تكافئها فتصبح أيونًا موجبًا Mg²⁺ مرتبًا في الشبكة البلورية، وتسهم كل ذرة بإلكترونين في بحر الإلكترونات. لا تُعد الإلكترونات ملكًا لذرة معينة لأن المستويات الخارجية للذرات متداخلة فتتحرك الإلكترونات بحرية بين جميع الأيونات (غير متمركزة).', '["الأيونات Mg²⁺","إلكترونان من كل ذرة","التجاذب بين Mg²⁺ وبحر الإلكترونات","الإلكترونات غير متمركزة لتداخل المستويات الخارجية"]'::jsonb, '[]'::jsonb, '[{"element":"الأيونات الموجبة","marks":1},{"element":"عدد الإلكترونات من كل ذرة","marks":1},{"element":"تفسير عدم تمركز الإلكترونات","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة"},{"level":"3 درجات","description":"خطأ بسيط في عنصر واحد"},{"level":"2 درجتان","description":"تحديد الأيونات والعدد دون تفسير"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["كتابة Mg⁺ وأن كل ذرة تسهم بإلكترون واحد","القول بوجود أيونات Mg²⁻","القول إن الإلكترونات تنتقل إلى ذرة مغنيسيوم أخرى وتستقر فيها"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-11T13:13:22.359Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(891, 0, 'من خواص الفلزات: قابليتها للطرق والسحب، وارتفاع درجات انصهارها وغليانها، وتوصيلها للحرارة والكهرباء، وصلابتها وقوتها.', '["","الهشاشة صفة المركبات الأيونية لا الفلزات.","الفلزات موصلة جيدة للحرارة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-11T13:13:22.361Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(892, 1, 'قابلية السحب: إمكانية سحب الفلز وتشكيله على هيئة أسلاك، مثل أسلاك النحاس.', '["تشكيل الصفائح بالطرق هو قابلية الطرق لا السحب.","","قابلية السحب خاصية ميكانيكية لا علاقة لها بالذوبان."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-10-11T13:13:22.362Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(893, 0, 'تشكيل الفلز صفائح رقيقة دون أن يتكسر يدل على قابليته للطرق.', '["","قابلية السحب تعني تشكيل أسلاك لا صفائح.","الألومنيوم درجة انصهاره مرتفعة نسبيًا، والرقائق لا علاقة لها بالانصهار."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-11T13:13:22.362Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(894, 2, 'معظم الفلزات صلبة وقوية، ودرجتا انصهارها وغليانها مرتفعتان.', '["معظم الفلزات صلبة؛ والزئبق استثناء.","لا توجد فلزات غازية في الظروف العادية.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-11T13:13:22.362Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(895, 1, 'يجمع النحاس بين جودة توصيل الكهرباء وقابلية السحب إلى أسلاك، وهما خاصيتان فلزيتان.', '["النحاس ليس هشًا؛ ولو كان هشًا لما أمكن سحبه أسلاكًا.","","النحاس من أفضل موصلات الكهرباء."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-11T13:13:22.362Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(896, 2, 'X درجة انصهارها مرتفعة، وتوصل الكهرباء وهي صلبة، وتتسطح عند الطرق دون أن تتكسر، وهذه خواص الفلزات.', '["Y لا توصل وهي صلبة وتتفتت عند الطرق، وهذه خواص المركبات الأيونية.","Z درجة انصهارها منخفضة ولا توصل، فليست فلزًا.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-11T13:13:22.362Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(897, 0, 'الفلزات موصلة جيدة للحرارة، فتنقل حرارة اللهب إلى الطعام بسرعة، كما أن درجات انصهارها مرتفعة.', '["","لو كانت عازلة للحرارة لما وصلت الحرارة إلى الطعام.","درجات انصهار الفلزات مرتفعة، ولو كانت منخفضة لانصهرت الأواني على النار."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-11T13:13:22.362Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(898, null, null, null, '1) موصلة جيدة للكهرباء: أسلاك الكهرباء. 2) موصلة جيدة للحرارة: أواني الطهي. 3) قابلة للطرق والسحب: رقائق الألومنيوم والأسلاك. 4) درجتا انصهار وغليان مرتفعتان وصلبة قوية: الأدوات والهياكل المعدنية.', '["توصيل الكهرباء مع استخدام","توصيل الحرارة مع استخدام","الطرق والسحب مع استخدام","درجات انصهار مرتفعة/صلابة مع استخدام"]'::jsonb, '[]'::jsonb, '[{"element":"الخاصية الأولى واستخدامها","marks":1},{"element":"الخاصية الثانية واستخدامها","marks":1},{"element":"الخاصية الثالثة واستخدامها","marks":1},{"element":"الخاصية الرابعة واستخدامها","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"أربع خواص مع استخدامات مناسبة"},{"level":"3 درجات","description":"ثلاث خواص صحيحة"},{"level":"2 درجتان","description":"خاصيتان صحيحتان أو أربع خواص دون استخدامات"},{"level":"1 درجة","description":"خاصية واحدة"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["ذكر الهشاشة خاصية للفلزات","استخدام لا يتفق مع الخاصية","ذكر خواص كيميائية بدل الفيزيائية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-11T13:13:22.363Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(899, null, null, null, '(أ) الفلزات توصل الكهرباء وهي صلبة، أما المركبات الأيونية الصلبة فلا توصلها (توصلها مصهورة أو محلولة). (ب) الفلزات قابلة للطرق والسحب، أما المركبات الأيونية فهشة تتفتت. (ج) كلاهما في الغالب ذو درجة انصهار مرتفعة.', '["الفلز يوصل صلبًا والأيوني لا","الفلز قابل للطرق والأيوني هش","كلاهما مرتفع درجة الانصهار غالبًا"]'::jsonb, '[]'::jsonb, '[{"element":"(أ)","marks":2},{"element":"(ب)","marks":2},{"element":"(ج)","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"مقارنة كاملة صحيحة"},{"level":"3–4 درجات","description":"وجهان صحيحان كاملان"},{"level":"1–2 درجة","description":"وجه واحد صحيح"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["القول إن المركبات الأيونية الصلبة توصل","القول إن الفلزات هشة","القول إن درجات انصهار الفلزات منخفضة دائمًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-11T13:13:22.363Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(900, null, null, null, '(أ) الأيونات الموجبة محاطة ببحر من الإلكترونات الحرة، فعند الطرق أو السحب تنزلق الأيونات بعضها فوق بعض ويبقى بحر الإلكترونات يربطها، فلا تنكسر الرابطة ويتغير شكل الفلز دون أن يتكسر. (ب) لأن التجاذب بين الأيونات الموجبة وبحر الإلكترونات (الرابطة الفلزية) قوي، فيحتاج التغلب عليه إلى طاقة كبيرة.', '["انزلاق الأيونات","بقاء بحر الإلكترونات رابطًا لها","عدم انكسار الرابطة","قوة التجاذب بين الأيونات وبحر الإلكترونات","الحاجة إلى طاقة كبيرة"]'::jsonb, '[]'::jsonb, '[{"element":"(أ) تفسير الطرق والسحب","marks":2},{"element":"(ب) تفسير ارتفاع درجة الانصهار","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"تفسيران صحيحان كاملان"},{"level":"3 درجات","description":"تفسير كامل وآخر ناقص"},{"level":"2 درجتان","description":"تفسير واحد صحيح"},{"level":"1 درجة","description":"إشارة عامة إلى الإلكترونات الحرة"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["تفسير قابلية الطرق بضعف الرابطة الفلزية","القول إن الأيونات تتنافر عند الطرق كما في البلورة الأيونية","تفسير درجة الانصهار بكتلة الفلز"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-11T13:13:22.363Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(901, 1, 'يحتوي الفلز على بحر من الإلكترونات الحرة غير المتمركزة، فعند وصله بمصدر كهربائي تتحرك هذه الإلكترونات خلال الشبكة فتنقل الشحنة.', '["الأيونات الموجبة في الفلز ثابتة نسبيًا في مواقعها، والتوصيل يتم بالإلكترونات.","","لو كانت الإلكترونات مرتبطة بذرات محددة لما انتقلت الشحنة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (50%)"}],"at":"2026-10-11T13:13:22.366Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(902, 0, 'الإلكترونات الحرة سهلة الحركة، فتنقل الطاقة الحرارية بسرعة من الجزء الساخن إلى بقية أجزاء الفلز.', '["","الفلزات تنقل الحرارة بسرعة، ولا تحتفظ بها في موضع واحد.","الأيونات لا تنتقل من مواقعها في الشبكة؛ الإلكترونات الحرة هي التي تنقل الطاقة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-11T13:13:22.366Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(903, 2, 'في الفلز الصلب إلكترونات حرة تنقل الشحنة، أما في المركب الأيوني الصلب فالأيونات مقيدة في الشبكة ولا توجد إلكترونات حرة.', '["عُكست الحالتان؛ أيونات المركب الأيوني الصلب هي المقيدة.","المركب الأيوني لا يحتوي على إلكترونات حرة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-11T13:13:22.367Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(904, 2, 'التيار الكهربائي في الفلزات يحمله تدفق الإلكترونات الحرة غير المتمركزة.', '["أيونات النحاس تبقى في مواقعها في الشبكة البلورية.","لا توجد أيونات سالبة في الفلز النقي.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-10-11T13:13:22.367Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(905, 1, 'بحر الإلكترونات الحرة موجود في النحاس صلبًا ومنصهرًا، فيوصل في الحالتين، بخلاف NaCl الذي يحتاج إلى تحرر أيوناته بالصهر.', '["التوصيل بالأيونات الحرة يفسر نتيجة مصهور NaCl لا النحاس.","","الإلكتروليت محلول مركب أيوني، والنحاس الصلب يوصل أصلًا دون صهر."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-10-11T13:13:22.367Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(906, 0, 'الإلكترونات الحرة في الفلز تتحرك بسهولة فتنقل الطاقة الحرارية من الطرف الساخن إلى الطرف البارد بسرعة.', '["","الأيونات لا تغادر مواقعها في الشبكة البلورية.","الفلز الصلب لا يسمح بتسرب السائل خلاله."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-10-11T13:13:22.367Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(907, 1, 'الفلزات توصل الكهرباء وهي صلبة وكذلك منصهرة، لأن إلكترونات التكافؤ الحرة تتحرك خلال الشبكة.', '["هذا تعميم خاطئ لسلوك المركبات الأيونية على الفلزات.","","التوصيل في الفلزات يتم بالإلكترونات لا بالأيونات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-11T13:13:22.367Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(908, null, null, null, 'لأن الفلزات تحتوي على بحر من إلكترونات التكافؤ الحرة غير المتمركزة. فعند وصل الفلز بمصدر كهربائي تتحرك هذه الإلكترونات بسهولة خلال الشبكة البلورية فتنقل الشحنة الكهربائية. وعند تسخين جزء من الفلز تنقل الإلكترونات الحرة سهلة الحركة الطاقة الحرارية بسرعة إلى بقية أجزائه.', '["وجود إلكترونات حرة غير متمركزة","حركتها تنقل الشحنة الكهربائية","حركتها تنقل الطاقة الحرارية"]'::jsonb, '[]'::jsonb, '[{"element":"ذكر الإلكترونات الحرة (بحر الإلكترونات)","marks":1},{"element":"تعليل التوصيل الكهربائي","marks":1},{"element":"تعليل التوصيل الحراري","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"تعليل كامل للتوصيلين"},{"level":"2 درجتان","description":"تعليل أحد التوصيلين بالإلكترونات الحرة"},{"level":"1 درجة","description":"ذكر الإلكترونات الحرة دون ربط"},{"level":"صفر","description":"لا إجابة أو تعليل بالأيونات"}]'::jsonb, '["التعليل بحركة الأيونات الموجبة","التعليل بارتفاع درجة الانصهار","إغفال التوصيل الحراري"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (50%)"}],"at":"2026-10-11T13:13:22.367Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(909, null, null, null, 'النحاس: الجسيمات الناقلة هي الإلكترونات الحرة؛ حرة لأن إلكترونات التكافؤ غير متمركزة في بحر الإلكترونات؛ يوصل وهو صلب. مصهور NaCl: الجسيمات الناقلة هي الأيونات Na⁺ وCl⁻؛ حرة لأن الصهر فكك الشبكة البلورية؛ لا يوصل وهو صلب لأن أيوناته تكون مقيدة.', '["الإلكترونات في النحاس","الأيونات في مصهور NaCl","سبب الحرية في كل منهما","النحاس يوصل صلبًا وNaCl الصلب لا يوصل"]'::jsonb, '[]'::jsonb, '[{"element":"الجسيمات الناقلة","marks":2},{"element":"سبب الحرية","marks":2},{"element":"التوصيل في الحالة الصلبة","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"مقارنة كاملة دقيقة"},{"level":"4–5 درجات","description":"وجهان كاملان"},{"level":"2–3 درجات","description":"وجه واحد كامل"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["القول إن مصهور NaCl يوصل بالإلكترونات","القول إن النحاس يحتاج إلى صهر ليوصل","إغفال سبب حرية الجسيمات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-10-11T13:13:22.368Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(910, null, null, null, '(أ) الفلز يحتوي على بحر من الإلكترونات الحرة التي تتحرك بسهولة فتنقل التيار الكهربائي. (ب) لأن البلاستيك لا يحتوي على إلكترونات حرة (أو جسيمات مشحونة حرة) تنقل الشحنة، فهو عازل يحمي من الصعق. (ج) قابلية السحب: إمكانية تشكيل الفلز على هيئة أسلاك.', '["الإلكترونات الحرة في الفلز","البلاستيك لا يحتوي على جسيمات مشحونة حرة","قابلية السحب"]'::jsonb, '[]'::jsonb, '[{"element":"(أ)","marks":2},{"element":"(ب)","marks":1},{"element":"(ج)","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"الأجزاء الثلاثة صحيحة"},{"level":"3 درجات","description":"خطأ أو نقص في جزء واحد"},{"level":"2 درجتان","description":"جزء واحد صحيح كامل"},{"level":"1 درجة","description":"إشارة عامة صحيحة"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["القول إن البلاستيك لا يوصل لأنه لين","ذكر قابلية الطرق بدل السحب للأسلاك","تفسير التوصيل بالأيونات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-11T13:13:22.370Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(911, 2, 'السبيكة خليط من عنصرين أو أكثر (أحدها على الأقل فلز) له خواص الفلزات، مثل البرونز والفولاذ.', '["السبيكة خليط لا مركب، ولا تتكون من أيونات موجبة وسالبة.","العنصر النقي لا يُعد سبيكة مهما كانت صلابته.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-11T13:13:22.373Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(912, 0, 'السبيكة خليط من عناصر (فلزات وقد يدخلها لافلز)، تحتفظ مكوناتها بطبيعتها الفلزية ويمكن أن تختلف نسبها.', '["","مكونات السبيكة لا ترتبط بنسب ثابتة بروابط أيونية.","السبيكة تتكون من أكثر من عنصر."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-11T13:13:22.373Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(913, 1, 'الفولاذ سبيكة من الحديد والكربون، وهذا يبين أن السبيكة قد تحتوي على لافلز.', '["الكلور لافلز لكنه ليس من مكونات الفولاذ.","","الكبريت ليس من المكونات الأساسية للفولاذ."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-11T13:13:22.374Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(914, 2, 'البرونز سبيكة من النحاس والقصدير، أما الذهب الخالص والنحاس النقي فعنصران نقيان.', '["الذهب الخالص عنصر نقي وليس سبيكة؛ السبيكة هي الذهب المخلوط بفلزات أخرى.","النحاس النقي عنصر واحد، فلا يُعد سبيكة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-11T13:13:22.374Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(915, 0, 'تُصنع السبائك لأن خواصها (كالصلابة ومقاومة التآكل) تختلف عن خواص مكوناتها وقد تفوقها، مع احتفاظها بالخواص الفلزية.', '["","لو تطابقت خواصها مع الفلز الأساسي لما كان لصنعها فائدة.","السبيكة تحتفظ بالخواص الفلزية كالتوصيل واللمعان."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-11T13:13:22.374Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(916, 1, 'B خليط من الذهب مع النحاس والفضة، فهي سبيكة ذهب (كالمستخدمة في المجوهرات).', '["A ذهب خالص (عنصر واحد)، فليست سبيكة.","","C مركب أيوني من فلز ولافلز، وليس خليطًا له خواص الفلزات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-11T13:13:22.374Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(917, 0, 'الذهب الخالص لين نسبيًا، فيُخلط بفلزات مثل النحاس والفضة لتكوين سبيكة أكثر صلابة تصلح للمجوهرات.', '["","الذهب عنصر فلزي لا مركب أيوني.","الذهب الخالص عنصر واحد لا خليط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-11T13:13:22.374Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(918, null, null, null, 'السبيكة: خليط من عنصرين أو أكثر له خواص الفلزات (أحدها على الأقل فلز). تُعد خليطًا لأن مكوناتها لا ترتبط بنسب ثابتة وتحتفظ بخواصها الفلزية، ويمكن تغيير نسب مكوناتها. مثالان: البرونز (نحاس + قصدير)، والفولاذ (حديد + كربون).', '["تعريف السبيكة","سبب كونها خليطًا","مثال أول بمكوناته","مثال ثانٍ بمكوناته"]'::jsonb, '[]'::jsonb, '[{"element":"التعريف","marks":1},{"element":"تعليل كونها خليطًا","marks":1},{"element":"المثالان","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"تعريف وتعليل ومثالان صحيحة"},{"level":"3 درجات","description":"نقص في عنصر واحد"},{"level":"2 درجتان","description":"تعريف ومثال واحد"},{"level":"1 درجة","description":"تعريف فقط أو مثال فقط"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["تعريف السبيكة بأنها مركب","ذكر الذهب الخالص مثالًا","خطأ في مكونات الفولاذ أو البرونز"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-10-11T13:13:22.375Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(919, null, null, null, 'العبارة الأولى غير دقيقة؛ لأن السبيكة قد تحتوي على لافلز، مثل الكربون في الفولاذ. الصياغة الدقيقة: السبيكة خليط من عنصرين أو أكثر له خواص الفلزات، أحدها على الأقل فلز. والعبارة الثانية غير دقيقة؛ لأن الذهب الخالص عنصر نقي وليس سبيكة. الصياغة الدقيقة: من أمثلة السبائك سبائك الذهب (ذهب مخلوط بالنحاس أو الفضة) المستخدمة في المجوهرات.', '["نقد العبارة الأولى بمثال الكربون في الفولاذ","إعادة صياغة التعريف","نقد العبارة الثانية (الذهب الخالص عنصر)","إعادة الصياغة: سبائك الذهب"]'::jsonb, '[]'::jsonb, '[{"element":"تقويم العبارة الأولى وتصحيحها","marks":2},{"element":"تقويم العبارة الثانية وتصحيحها","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"تقويم وتصحيح صحيحان للعبارتين"},{"level":"3 درجات","description":"تصحيح العبارتين مع تعليل ناقص"},{"level":"2 درجتان","description":"تقويم عبارة واحدة وتصحيحها"},{"level":"1 درجة","description":"إشارة إلى خطأ دون تصحيح"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["قبول العبارتين دون نقد","القول إن الذهب الخالص سبيكة لأنه يستخدم في المجوهرات","عدم ذكر مثال يدعم النقد"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-11T13:13:22.375Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(920, null, null, null, '(أ) الفولاذ؛ يحتوي على الكربون وهو لافلز. (ب) لأن كلًّا منها خليط من عنصرين أو أكثر أحدها على الأقل فلز، وله خواص الفلزات. (ج) الرابطة الفلزية (تجاذب الأيونات الموجبة مع بحر الإلكترونات الحرة).', '["الفولاذ والكربون","تطبيق تعريف السبيكة","الرابطة الفلزية"]'::jsonb, '[]'::jsonb, '[{"element":"(أ)","marks":1},{"element":"(ب)","marks":2},{"element":"(ج)","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"الأجزاء الثلاثة صحيحة"},{"level":"3 درجات","description":"خطأ في جزء واحد"},{"level":"2 درجتان","description":"جزء أو جزآن صحيحان دون تعليل"},{"level":"1 درجة","description":"جزء واحد صحيح"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["اعتبار الألومنيوم لافلزًا","القول إن الرابطة في السبائك أيونية","تعريف السبيكة بأنها من فلزات فقط"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-11T13:13:22.375Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
