(928, null, null, null, '1) سبائك الذهب: المجوهرات. 2) البرونز: الميداليات والأجراس. 3) الفولاذ: المغاسل والأدوات. 4) النيكو: المغانط.', '["سبائك الذهب – المجوهرات","البرونز – الميداليات/الأجراس","الفولاذ – المغاسل/الأدوات","النيكو – المغانط"]'::jsonb, '[]'::jsonb, '[{"element":"السبيكة الأولى واستخدامها","marks":1},{"element":"السبيكة الثانية واستخدامها","marks":1},{"element":"السبيكة الثالثة واستخدامها","marks":1},{"element":"السبيكة الرابعة واستخدامها","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"أربع سبائك باستخدامات صحيحة"},{"level":"3 درجات","description":"ثلاث صحيحة"},{"level":"2 درجتان","description":"اثنتان صحيحتان"},{"level":"1 درجة","description":"واحدة صحيحة"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["ربط النيكو بالمجوهرات","ذكر الذهب الخالص بدل سبائك الذهب","ربط البرونز بالمغانط"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-10-11T13:13:22.381Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(929, null, null, null, '(أ) البرونز: يُستخدم تقليديًا في الأجراس لمتانته. (ب) الفولاذ (المقاوم للصدأ): قوي ويقاوم الصدأ. (ج) النيكو: سبيكة تُصنع منها المغانط. (د) سبائك الذهب: أكثر صلابة من الذهب الخالص ومناسبة للمجوهرات.', '["(أ) البرونز","(ب) الفولاذ","(ج) النيكو","(د) سبائك الذهب","مبرر مناسب لكل اختيار"]'::jsonb, '[]'::jsonb, '[{"element":"(أ)","marks":1},{"element":"(ب)","marks":1},{"element":"(ج)","marks":1},{"element":"(د)","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"الاختيارات الأربعة صحيحة بمبررات"},{"level":"3 درجات","description":"ثلاثة صحيحة"},{"level":"2 درجتان","description":"اثنان صحيحان أو الأربعة دون مبررات"},{"level":"1 درجة","description":"اختيار واحد صحيح"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["اختيار الفولاذ للمغناطيس وترك النيكو","اختيار البرونز للمغسلة","عدم ذكر مبررات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-10-11T13:13:22.382Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(930, null, null, null, 'لأن خواص السبيكة تختلف عن خواص مكوناتها النقية وتكون أنسب للاستخدام، كزيادة الصلابة والمتانة ومقاومة التآكل. مثال 1: الذهب الخالص لين، فيُخلط بفلزات كالنحاس والفضة لتصبح السبيكة أصلب ولا تتشوه المجوهرات بسهولة. مثال 2: الفولاذ (حديد + كربون) أقوى وأصلب من الحديد النقي، فيناسب صناعة الأدوات.', '["خواص السبيكة تختلف عن مكوناتها وأنسب للاستخدام","سبائك الذهب أصلب من الذهب الخالص","الفولاذ أقوى من الحديد النقي"]'::jsonb, '[]'::jsonb, '[{"element":"التعليل العام","marks":1},{"element":"مثال سبائك الذهب","marks":1},{"element":"مثال الفولاذ","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"تعليل عام ومثالان صحيحان"},{"level":"2 درجتان","description":"تعليل مع مثال واحد أو مثالان دون تعليل"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["القول إن السبائك أرخص فقط دون ذكر الخواص","القول إن الذهب الخالص أصلب من سبائكه","اعتبار الفولاذ فلزًا نقيًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-11T13:13:22.382Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(931, 0, 'الرابطة التساهمية تنشأ من المشاركة في أزواج من إلكترونات التكافؤ بين ذرتين، فتصل كل منهما إلى الاستقرار.', '["","هذا وصف الرابطة الأيونية التي تقوم على انتقال الإلكترونات وتكوين أيونات.","هذا وصف الرابطة الفلزية بين ذرات الفلزات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-11T13:13:22.385Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(932, 2, 'تتكون الرابطة التساهمية غالبًا بين ذرات اللافلزات المتقاربة في ميلها لجذب الإلكترونات، فتتشارك بدل أن تفقد أو تكتسب.', '["الغازات النبيلة مستقرة ولا تميل إلى تكوين روابط في الظروف العادية.","ذرات الفلزات ترتبط برابطة فلزية لا تساهمية.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-10-11T13:13:22.385Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(933, 0, 'الهيدروجين والأكسجين لافلزان، فيرتبطان بالمشاركة في الإلكترونات (رابطة تساهمية).', '["","الصوديوم فلز والكلور لافلز، فتنتقل الإلكترونات وتتكون رابطة أيونية.","الكالسيوم فلز والأكسجين لافلز، فالرابطة أيونية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-11T13:13:22.386Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(934, 1, 'الهيدروجين له مستوى طاقة أول فقط يتسع لإلكترونين، فيستقر بمشاركة زوج واحد (توزيع يشبه الهيليوم).', '["الأكسجين يكمل ثمانيته بتكوين رابطتين (6 + 2 = 8).","","الفلور يكمل ثمانيته بتكوين رابطة واحدة (7 + 1 = 8)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-10-11T13:13:22.386Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(935, 0, 'في الرابطة التساهمية يبقى زوج الإلكترونات مشتركًا بين الذرتين، أما في الأيونية فتنتقل الإلكترونات وتتكون أيونات.', '["","تكوين الأيونات المتجاذبة هو أساس الرابطة الأيونية لا التساهمية.","الانتقال الكلي للإلكترونات من سمات الرابطة الأيونية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-11T13:13:22.386Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(936, 1, 'النيتروجين والهيدروجين لافلزان، فيكونان روابط تساهمية (كما في NH₃).', '["المغنيسيوم فلز يفقد إلكترونين للأكسجين فتتكون رابطة أيونية.","","البوتاسيوم فلز قلوي يفقد إلكترونه للفلور فتتكون رابطة أيونية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-11T13:13:22.386Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(937, 2, 'الفقد والاكتساب يميزان الرابطة الأيونية، أما التساهمية فتقوم على المشاركة في أزواج إلكترونات التكافؤ.', '["ليست كل الروابط فقدًا واكتسابًا؛ فالتساهمية مشاركة والفلزية بحر إلكترونات.","لا يوجد منح دائم للإلكترونات في الرابطة التساهمية؛ هذا تصور خاطئ.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-11T13:13:22.387Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(938, null, null, null, 'الرابطة التساهمية: رابطة كيميائية تنتج عن مشاركة ذرتين بزوج أو أكثر من إلكترونات التكافؤ. تتكون غالبًا بين ذرات اللافلزات. مثال: جزيء F₂ أو H₂O أو HF.', '["التعريف: مشاركة ذرتين بزوج أو أكثر من الإلكترونات","ذكر إلكترونات التكافؤ","تتكون بين اللافلزات","مثال صحيح"]'::jsonb, '[]'::jsonb, '[{"element":"التعريف (المشاركة)","marks":2},{"element":"نوع العناصر (لافلزات)","marks":1},{"element":"المثال الصحيح","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة دقيقة بجميع العناصر"},{"level":"3 درجات","description":"إجابة صحيحة ينقصها عنصر واحد"},{"level":"2 درجتان","description":"إجابة صحيحة جزئيًا بعنصرين"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تعريفها بانتقال الإلكترونات","التمثيل بمركب أيوني مثل NaCl"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-10-11T13:13:22.387Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(939, null, null, null, 'التساهمية: تتكون بالمشاركة في أزواج إلكترونات التكافؤ، وتكون غالبًا بين لافلز ولافلز، مثل H₂O. الأيونية: تتكون بانتقال الإلكترونات من ذرة إلى أخرى وتجاذب الأيونات الناتجة، وتكون غالبًا بين فلز ولافلز، مثل NaCl.', '["التساهمية: مشاركة","الأيونية: انتقال وتجاذب أيونات","التساهمية بين لافلزات والأيونية بين فلز ولافلز","مثالان صحيحان"]'::jsonb, '[]'::jsonb, '[{"element":"طريقة التكون لكل منهما","marks":2},{"element":"نوع العناصر","marks":2},{"element":"مثال لكل رابطة","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"مقارنة كاملة صحيحة في الجوانب الثلاثة"},{"level":"4 درجات","description":"جانبان صحيحان"},{"level":"2 درجتان","description":"جانب واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الخلط بين المشاركة والانتقال","التمثيل للتساهمية بمركب فلز ولافلز"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-11T13:13:22.387Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(940, null, null, null, 'لأن ذرات اللافلزات جميعها تميل إلى اكتساب الإلكترونات ولا تميل إلى فقدها، فلا تستطيع إحداهما أن تمنح الأخرى إلكترونات، لذلك تتشارك في أزواج من إلكترونات التكافؤ حتى تصل كل منها إلى التوزيع الثماني المستقر (القاعدة الثمانية).', '["اللافلزات تميل جميعها إلى اكتساب الإلكترونات","لا تفقد إحداها إلكترونات بسهولة للأخرى","تلجأ إلى المشاركة","تصل إلى التوزيع الثماني المستقر"]'::jsonb, '[]'::jsonb, '[{"element":"ميل اللافلزات للاكتساب وعدم الفقد","marks":1},{"element":"المشاركة بديلًا","marks":1},{"element":"الوصول إلى الثمانية/الاستقرار","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"إجابة كاملة دقيقة"},{"level":"2 درجتان","description":"إجابة ينقصها عنصر واحد"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الاكتفاء بقول «لأنها لافلزات» دون تفسير","ذكر أن اللافلزات تفقد الإلكترونات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-11T13:13:22.387Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(941, 1, 'تنجذب نواة كل ذرة إلى إلكترونات الأخرى، وفي الوقت نفسه تتنافر النواتان وتتنافر الإلكترونات؛ وتتكون الرابطة عند التوازن بين هذه القوى.', '["النواتان موجبتان فتتنافران ولا تتجاذبان.","","لو وُجد تنافر فقط لما تكونت أي رابطة، والواقع أن التجاذب موجود أيضًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-11T13:13:22.392Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(942, 1, 'يتكون الجزيء المستقر عند المسافة التي يبلغ فيها التجاذب أقصاه مقارنة بالتنافر، فتكون طاقة النظام في أدنى قيمة.', '["عند الابتعاد التام لا يوجد تجاذب ولا تتكون رابطة.","","تلامس النواتين يزيد التنافر بشدة ويرفع الطاقة فلا يستقر الجزيء."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-10-11T13:13:22.392Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(943, 0, 'للنيتروجين 5 إلكترونات تكافؤ منها 3 إلكترونات مفردة، وعدد الروابط = عدد الإلكترونات المفردة، فيكوّن 3 روابط (5 + 3 = 8).', '["","5 هو عدد إلكترونات التكافؤ وليس عدد الإلكترونات المفردة.","رابطتان لعناصر المجموعة 16 مثل الأكسجين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-11T13:13:22.392Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(944, 2, 'للكربون 4 إلكترونات تكافؤ مفردة، فيكون 4 روابط ليصل إلى 8 إلكترونات (4 + 4 = 8).', '["رابطتان لعناصر المجموعة 16 التي لها 6 إلكترونات تكافؤ.","8 هو عدد الإلكترونات الذي تصل إليه الذرة وليس عدد الروابط.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-11T13:13:22.393Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(945, 1, 'لكل فلور 7 إلكترونات تكافؤ، وتشارك كل ذرة بإلكترونها المفرد فيتكون زوج مشترك يُحسب للذرتين، فيصبح حول كل ذرة 6 + 2 = 8 إلكترونات.', '["14 هو مجموع إلكترونات التكافؤ في الجزيء كله وليس حول كل ذرة.","","7 هو عدد إلكترونات التكافؤ قبل تكوين الرابطة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-10-11T13:13:22.393Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(946, 2, 'عدد الروابط يساوي عدد الإلكترونات المفردة: للأكسجين 6 إلكترونات تكافؤ منها 2 مفردان، وللفلور 7 منها 1 مفرد.', '["عدد إلكترونات تكافؤ الأكسجين (6) أقل من الفلور (7) لا أكبر.","الحالة الفيزيائية لا تحدد عدد الروابط، وكلاهما غاز أصلًا.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-10-11T13:13:22.393Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(947, 0, 'تكوين الرابطة يصاحبه انطلاق طاقة، فتكون طاقة الجزيء أقل من مجموع طاقتي الذرتين المنفردتين، أي أكثر استقرارًا.', '["","تكوين الرابطة يغير طاقة النظام؛ فالطاقة تنخفض إلى أدنى قيمة.","امتصاص الطاقة يصاحب تكسير الروابط لا تكوينها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-10-11T13:13:22.393Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(948, null, null, null, 'لكل ذرة فلور 7 إلكترونات تكافؤ (منها إلكترون واحد مفرد). عند تقارب الذرتين تشارك كل ذرة بإلكترونها المفرد فيتكون زوج إلكترونات مشترك بين الذرتين، فيصبح حول كل ذرة 6 إلكترونات غير رابطة + 2 مشتركة = 8 إلكترونات، فتتحقق القاعدة الثمانية. الرابطة الناتجة تساهمية أحادية: F–F.', '["7 إلكترونات تكافؤ لكل فلور (إلكترون مفرد واحد)","مشاركة كل ذرة بإلكترون واحد","تكوين زوج مشترك واكتمال 8 إلكترونات حول كل ذرة","الرابطة تساهمية أحادية"]'::jsonb, '[]'::jsonb, '[{"element":"عدد إلكترونات التكافؤ والإلكترون المفرد","marks":1},{"element":"المشاركة وتكوين الزوج المشترك","marks":1},{"element":"اكتمال الثمانية لكل ذرة","marks":1},{"element":"نوع الرابطة (أحادية)","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة دقيقة بجميع العناصر"},{"level":"3 درجات","description":"إجابة صحيحة ينقصها عنصر واحد"},{"level":"2 درجتان","description":"إجابة صحيحة جزئيًا بعنصرين"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["حساب 14 إلكترونًا حول كل ذرة","القول إن ذرة تعطي الأخرى إلكترونًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-10-11T13:13:22.394Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(949, null, null, null, 'عندما تقترب ذرتان تنجذب نواة كل منهما إلى إلكترونات الأخرى، وفي الوقت نفسه تتنافر النواتان الموجبتان وتتنافر الإلكترونات السالبة. عند مسافة معينة يصل التجاذب إلى أقصاه مقابل التنافر وتكون طاقة النظام في أدنى قيمة، فتشترك الذرتان في زوج من الإلكترونات ويتكون جزيء مستقر، ويصاحب ذلك انطلاق طاقة.', '["تجاذب نواة كل ذرة مع إلكترونات الأخرى","تنافر النواتين وتنافر الإلكترونات","التوازن عند مسافة معينة والطاقة أقل ما يمكن","تكون جزيء مستقر مع انطلاق طاقة"]'::jsonb, '[]'::jsonb, '[{"element":"قوى التجاذب","marks":1},{"element":"قوى التنافر","marks":1},{"element":"التوازن وأدنى طاقة","marks":1},{"element":"الاستقرار وانطلاق الطاقة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة دقيقة بجميع العناصر"},{"level":"3 درجات","description":"إجابة صحيحة ينقصها عنصر واحد"},{"level":"2 درجتان","description":"إجابة صحيحة جزئيًا بعنصرين"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["إغفال قوى التنافر","القول إن تكوين الرابطة يمتص طاقة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-11T13:13:22.394Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(950, null, null, null, 'C: 4 إلكترونات مفردة ← 4 روابط. N: 3 مفردة ← 3 روابط. O: 2 مفردان ← رابطتان. Cl: 1 مفرد ← رابطة واحدة. القاعدة: عدد الروابط التساهمية التي تكونها الذرة = عدد الإلكترونات المفردة في مستواها الخارجي = 8 − عدد إلكترونات التكافؤ (لعناصر المجموعات 14–17).', '["C: 4 روابط","N: 3 روابط","O: رابطتان","Cl: رابطة واحدة","القاعدة: عدد الروابط = عدد الإلكترونات المفردة"]'::jsonb, '["C: 8 − 4 = 4","N: 8 − 5 = 3","O: 8 − 6 = 2","Cl: 8 − 7 = 1"]'::jsonb, '[{"element":"عدد الروابط لـ C وN","marks":1},{"element":"عدد الروابط لـ O وCl","marks":1},{"element":"الإلكترونات المفردة للعناصر الأربعة","marks":1},{"element":"استنتاج القاعدة","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"جدول كامل صحيح واستنتاج القاعدة"},{"level":"4 درجات","description":"جدول صحيح مع استنتاج ناقص"},{"level":"3 درجات","description":"جدول صحيح دون استنتاج"},{"level":"1–2 درجة","description":"بعض القيم صحيحة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["جعل عدد الروابط مساويًا لعدد إلكترونات التكافؤ","عكس القيم بين N وCl"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-11T13:13:22.395Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(951, 1, 'الرابطة الأحادية تتكون عندما تتشارك ذرتان في زوج واحد (إلكترونين) من إلكترونات التكافؤ.', '["المشاركة بزوجين تعطي رابطة ثنائية.","","الرابطة تتكون من زوج (إلكترونين) لا من إلكترون واحد."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-11T13:13:22.398Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(952, 2, 'الرابطة الأحادية زوج واحد من الإلكترونات، أي إلكترونان يساهم كل من الذرتين غالبًا بواحد منهما.', '["الإلكترون الواحد لا يكوّن زوجًا رابطًا.","أربعة إلكترونات (زوجان) تكوّن رابطة ثنائية.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-11T13:13:22.398Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(953, 0, 'كل خط يمثل زوجًا مشتركًا، فالرابطة الأحادية تُمثل بخط واحد.', '["","الخطوط الثلاثة تمثل رابطة ثلاثية (ثلاثة أزواج).","الخطان يمثلان رابطة ثنائية (زوجين)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (43%)"}],"at":"2026-10-11T13:13:22.398Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(954, 0, 'الرابطة الأحادية زوج مشترك واحد، وهذا ينطبق على الرابطة Y.', '["","الرابطة X فيها 3 أزواج مشتركة فهي ثلاثية.","الرابطة Z فيها زوجان مشتركان فهي ثنائية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-11T13:13:22.399Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(955, 1, 'الرابطة الأحادية تتكون من تداخل رأسي مباشر بين المستويات، فهي دائمًا رابطة سيجما.', '["الرابطة الأحادية تساهمية تقوم على المشاركة لا على الأيونات.","","رابطة باي لا توجد إلا ضمن الروابط الثنائية والثلاثية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-11T13:13:22.399Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(956, 0, 'ترتبط ذرة الأكسجين بكل ذرة هيدروجين بزوج مشترك واحد، فتوجد رابطتان أحاديتان O–H.', '["","يوجد في الجزيء ذرتا هيدروجين، كل منهما مرتبطة برابطة مستقلة.","أربعة هو عدد أزواج الإلكترونات حول الأكسجين (رابطتان + زوجان حران) وليس عدد الروابط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-11T13:13:22.399Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(957, 2, 'مساهمة كل ذرة بإلكترون واحد تكوّن زوجًا مشتركًا واحدًا، وهذا تعريف الرابطة الأحادية.', '["الثنائية تتطلب زوجين مشتركين (مساهمة كل ذرة بإلكترونين).","الثلاثية تتطلب ثلاثة أزواج مشتركة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-11T13:13:22.400Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(958, null, null, null, 'الرابطة التساهمية الأحادية: رابطة تتكون عندما تشترك ذرتان بزوج واحد من الإلكترونات. عدد الإلكترونات المشتركة: إلكترونان. تمثل في الصيغة البنائية بخط واحد بين الذرتين، مثل H–Cl.', '["التعريف: زوج واحد مشترك","عدد الإلكترونات: 2","التمثيل بخط واحد"]'::jsonb, '[]'::jsonb, '[{"element":"التعريف","marks":1},{"element":"عدد الإلكترونات","marks":1},{"element":"طريقة التمثيل","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"إجابة كاملة دقيقة"},{"level":"2 درجتان","description":"إجابة ينقصها عنصر واحد"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إنها إلكترون واحد مشترك","تمثيلها بنقطة واحدة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (43%)"}],"at":"2026-10-11T13:13:22.400Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(959, null, null, null, 'الأحادية: زوج واحد = إلكترونان، مثل F₂ أو H₂. الثنائية: زوجان = 4 إلكترونات، مثل O₂. الثلاثية: ثلاثة أزواج = 6 إلكترونات، مثل N₂.', '["الأحادية: 1 زوج = 2 إلكترون","الثنائية: 2 زوج = 4 إلكترونات","الثلاثية: 3 أزواج = 6 إلكترونات","مثال صحيح لكل منها"]'::jsonb, '[]'::jsonb, '[{"element":"الأحادية مع مثال","marks":2},{"element":"الثنائية مع مثال","marks":2},{"element":"الثلاثية مع مثال","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"مقارنة كاملة مع الأمثلة"},{"level":"4 درجات","description":"نوعان صحيحان"},{"level":"2 درجتان","description":"نوع واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الخلط بين عدد الأزواج وعدد الإلكترونات","التمثيل للثنائية بـ N₂"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-11T13:13:22.401Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(960, null, null, null, 'H–H في H₂: أحادية لأن الذرتين تشتركان بزوج واحد. O=O في O₂: غير أحادية (ثنائية) لأن الذرتين تشتركان بزوجين. H–F في HF: أحادية لأن الذرتين تشتركان بزوج واحد.', '["H₂ أحادية بزوج واحد","O₂ ثنائية بزوجين","HF أحادية بزوج واحد"]'::jsonb, '[]'::jsonb, '[{"element":"تصنيف H₂ مع السبب","marks":1},{"element":"تصنيف O₂ مع السبب","marks":1},{"element":"تصنيف HF مع السبب","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"إجابة كاملة دقيقة"},{"level":"2 درجتان","description":"إجابة ينقصها عنصر واحد"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عد O₂ أحادية","التصنيف دون ذكر السبب"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-11T13:13:22.403Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(961, 0, 'في F₂ تشترك ذرتا الفلور بزوج واحد (F–F)، فالرابطة أحادية.', '["","في O₂ رابطة ثنائية (زوجان مشتركان).","في N₂ رابطة ثلاثية (ثلاثة أزواج مشتركة)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (36%)"}],"at":"2026-10-11T13:13:22.406Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
