(964, 2, 'لكل هالوجين 7 إلكترونات تكافؤ منها إلكترون مفرد واحد، فيحتاج إلى زوج مشترك واحد ليكمل 8 إلكترونات، فتتكون رابطة أحادية كما في HF وHCl.', '["الهيدروجين يستقر بإلكترونين فقط لا بثمانية.","من إلكترونات التكافؤ السبعة ستة في ثلاثة أزواج وإلكترون واحد مفرد فقط.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-11T13:13:22.407Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(965, 1, 'H₂ (H–H) وHF (H–F) وH₂O (رابطتان O–H) كلها روابط أحادية.', '["N₂ يحتوي على رابطة ثلاثية.","","O₂ يحتوي على رابطة ثنائية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (36%)"}],"at":"2026-10-11T13:13:22.407Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(966, 2, 'يرتبط النيتروجين بكل ذرة من ذرات الهيدروجين الثلاث بزوج واحد، فتوجد 3 روابط أحادية N–H.', '["يوجد في الجزيء ثلاث ذرات هيدروجين لكل منها رابطة مستقلة.","4 هو عدد أزواج الإلكترونات حول النيتروجين (3 رابطة + زوج حر) وليس عدد الروابط.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-11T13:13:22.407Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(967, 2, 'H₂ جزيء عنصر من ذرتين متماثلتين تشتركان بزوج واحد (H–H).', '["O₂ جزيء عنصر لكن رابطته ثنائية.","N₂ جزيء عنصر لكن رابطته ثلاثية.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-10-11T13:13:22.407Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(968, null, null, null, 'أمثلة: H₂: H–H ، F₂: F–F ، HF: H–F (ويقبل H₂O: H–O–H ، HCl: H–Cl ، CH₄ ، NH₃).', '["مثال أول صحيح مع صيغته البنائية","مثال ثانٍ صحيح مع صيغته البنائية","مثال ثالث صحيح مع صيغته البنائية"]'::jsonb, '[]'::jsonb, '[{"element":"المثال الأول وصيغته","marks":1},{"element":"المثال الثاني وصيغته","marks":1},{"element":"المثال الثالث وصيغته","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"إجابة كاملة دقيقة"},{"level":"2 درجتان","description":"إجابة ينقصها عنصر واحد"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ذكر O₂ أو N₂ أمثلة على الأحادية","ذكر مركب أيوني مثل NaCl"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-11T13:13:22.407Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(969, null, null, null, 'الجزيئات ذات الروابط الأحادية فقط: H₂ (H–H)، HF (H–F)، H₂O (O–H مرتين). تُستبعد: O₂ لأنه يحتوي على رابطة ثنائية (زوجان مشتركان)، وN₂ لأنه يحتوي على رابطة ثلاثية (ثلاثة أزواج)، وCO₂ لأنه يحتوي على رابطتين ثنائيتين O=C=O.', '["تحديد H₂ وHF وH₂O","استبعاد O₂ مع السبب","استبعاد N₂ مع السبب","استبعاد CO₂ مع السبب"]'::jsonb, '[]'::jsonb, '[{"element":"تحديد الجزيئات الثلاثة الصحيحة","marks":2},{"element":"تعليل استبعاد O₂","marks":1},{"element":"تعليل استبعاد N₂","marks":1},{"element":"تعليل استبعاد CO₂","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"تحديد وتعليل كاملان"},{"level":"3–4 درجات","description":"تحديد صحيح مع تعليل ناقص"},{"level":"1–2 درجة","description":"تحديد جزئي"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عد CO₂ ذا روابط أحادية","استبعاد H₂O لأن فيه ثلاث ذرات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-10-11T13:13:22.408Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(970, null, null, null, 'للهيدروجين إلكترون تكافؤ واحد ويحتاج إلى إلكترون واحد ليستقر بإلكترونين. وللكلور 7 إلكترونات تكافؤ منها إلكترون مفرد واحد، ويحتاج إلى إلكترون واحد ليكمل ثمانيته. فتشارك كل ذرة بإلكترون واحد ويتكون زوج مشترك واحد، أي رابطة أحادية H–Cl.', '["H: إلكترون واحد ويستقر بإلكترونين","Cl: 7 إلكترونات ويحتاج إلكترونًا واحدًا","زوج مشترك واحد = رابطة أحادية"]'::jsonb, '[]'::jsonb, '[{"element":"حالة الهيدروجين","marks":1},{"element":"حالة الكلور","marks":1},{"element":"الاستنتاج: زوج واحد","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"إجابة كاملة دقيقة"},{"level":"2 درجتان","description":"إجابة ينقصها عنصر واحد"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الهيدروجين يحتاج 8 إلكترونات","القول إن الكلور يشارك بسبعة إلكترونات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-11T13:13:22.408Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(971, 1, 'مجموع إلكترونات التكافؤ = 5 + (3 × 7) = 26 إلكترونًا، أي 13 زوجًا.', '["ناتج 3 × 7 فقط مع نسيان إلكترونات النيتروجين.","","ناتج 5 + 7 دون ضرب إلكترونات الفلور في عدد ذراته (3)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (40%)"}],"at":"2026-10-11T13:13:22.412Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(972, 1, 'الذرة المركزية هي الأقل ميلًا لجذب الإلكترونات (الأقل كهروسالبية)، والنيتروجين أقل من الفلور، فيكون مركزيًا وتحيط به ذرات الفلور الثلاث.', '["كثرة عدد الذرات لا تجعلها مركزية؛ بل الذرة المتكررة تكون عادة جانبية.","","الذرة الأكثر ميلًا لجذب الإلكترونات تكون جانبية لا مركزية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (40%)"}],"at":"2026-10-11T13:13:22.413Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(973, 0, 'الهيدروجين يستقر بإلكترونين، فيكوّن رابطة واحدة فقط ولا يمكن أن يرتبط بذرتين، لذلك يكون جانبيًا دائمًا.', '["","للهيدروجين إلكترون تكافؤ واحد فقط.","الهيدروجين أصغر الذرات حجمًا لا أكبرها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-11T13:13:22.413Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(974, 0, 'مجموع الإلكترونات = 4 + 2×6 = 16 = 8 أزواج؛ منها 4 أزواج رابطة (رابطتان ثنائيتان)، فيبقى 8 − 4 = 4 أزواج حرة (زوجان على كل أكسجين).', '["","هذا عدد الأزواج الحرة لو رُسمت روابط أحادية فقط (8 − 2 = 6)، ويبقى الكربون حينها دون ثمانية.","هذا عدد الأزواج الحرة على ذرة أكسجين واحدة فقط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-10-11T13:13:22.413Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(975, 2, 'عدد الأزواج الكلي 4، استُخدم منها زوجان للرابطتين O–H، فيبقى 4 − 2 = 2 زوجان حران على الأكسجين ليكمل ثمانيته.', '["ثلاثة أزواج حرة تتطلب 5 أزواج كليًا، بينما مجموع الأزواج 4 فقط.","زوج حر واحد يجعل حول الأكسجين 6 إلكترونات فقط.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-10-11T13:13:22.414Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(976, 1, '5 + 4×1 = 9، ولأن الأيون موجب الشحنة نطرح إلكترونًا واحدًا: 9 − 1 = 8 إلكترونات (4 أزواج رابطة).', '["نسيان طرح الشحنة الموجبة.","","إضافة الشحنة بدل طرحها؛ الإضافة تكون للأيون السالب."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-10-11T13:13:22.414Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(977, 2, 'إذا لم تكتمل ثمانية الذرة المركزية يُحوَّل زوج غير رابط من ذرة مجاورة إلى زوج رابط، فتتكون رابطة ثنائية بين ذرتي الكربون ويصبح لكل منهما 8 إلكترونات.', '["الهيدروجين لا يكون مركزيًا لأنه يكوّن رابطة واحدة فقط.","لا يجوز إضافة إلكترونات تزيد على مجموع إلكترونات التكافؤ المحسوب (12).",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-11T13:13:22.414Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(978, null, null, null, 'مجموع إلكترونات التكافؤ = 4 + 4×1 = 8 إلكترونات = 4 أزواج. الذرة المركزية: الكربون (الهيدروجين جانبي دائمًا). يوضع زوج رابط بين الكربون وكل ذرة هيدروجين، فتُستخدم الأزواج الأربعة في أربع روابط أحادية C–H ولا تبقى أزواج حرة. يحيط بالكربون 8 إلكترونات وبكل هيدروجين إلكترونان. الشكل: ذرة C في الوسط ترتبط بأربع ذرات H بأربعة خطوط.', '["مجموع الإلكترونات 8","عدد الأزواج 4","الكربون ذرة مركزية","أربع روابط أحادية ولا أزواج حرة","رسم صحيح"]'::jsonb, '["4 + 4×1 = 8 إلكترونات","8 ÷ 2 = 4 أزواج","C مركزية وH جانبية","4 أزواج رابطة C–H، والأزواج الحرة = 4 − 4 = 0"]'::jsonb, '[{"element":"مجموع الإلكترونات وعدد الأزواج","marks":1},{"element":"تحديد الذرة المركزية","marks":1},{"element":"توزيع الأزواج الرابطة","marks":1},{"element":"الرسم النهائي الصحيح","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة دقيقة بجميع العناصر"},{"level":"3 درجات","description":"إجابة صحيحة ينقصها عنصر واحد"},{"level":"2 درجتان","description":"إجابة صحيحة جزئيًا بعنصرين"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["وضع أزواج حرة على الكربون","جعل الهيدروجين مركزيًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-10-11T13:13:22.414Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(979, null, null, null, 'مجموع الإلكترونات = 4 + 2×6 = 16 = 8 أزواج. الكربون مركزي. نضع زوجًا رابطًا بين C وكل O (زوجان)، ونوزع الأزواج الستة المتبقية على ذرتي الأكسجين (3 لكل منهما)، فيبقى الكربون محاطًا بـ 4 إلكترونات فقط. نحول زوجًا حرًا من كل أكسجين إلى زوج رابط فتتكون رابطتان ثنائيتان: O=C=O، وعلى كل أكسجين زوجان حران. يصبح حول كل ذرة 8 إلكترونات.', '["مجموع الإلكترونات 16 (8 أزواج)","C مركزية","الروابط الأحادية لا تكمل ثمانية C","تحويل زوج حر من كل O إلى رابطة ثنائية","زوجان حران على كل O"]'::jsonb, '["4 + 2×6 = 16 إلكترونًا = 8 أزواج","زوجان رابطان أحاديان، ويبقى 6 أزواج توزع على O","الكربون حوله 4 إلكترونات فقط","تحويل زوجين حرين إلى رابطتين ثنائيتين: O=C=O"]'::jsonb, '[{"element":"الحساب وعدد الأزواج","marks":1},{"element":"الذرة المركزية والروابط الأولية","marks":1},{"element":"تحويل الأزواج إلى روابط ثنائية","marks":2},{"element":"الأزواج الحرة والرسم النهائي","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"خطوات ورسم نهائي صحيح"},{"level":"3–4 درجات","description":"رسم صحيح مع نقص في توضيح الخطوات"},{"level":"1–2 درجة","description":"حساب صحيح للإلكترونات فقط أو رسم بروابط أحادية"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["رسم روابط أحادية وترك الكربون بأربعة إلكترونات","وضع أزواج حرة على الكربون"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-11T13:13:22.415Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(980, null, null, null, 'مجموع الإلكترونات = 5 + 4×6 + 3 = 32 إلكترونًا (نضيف 3 لأن الشحنة سالبة) = 16 زوجًا. الفوسفور ذرة مركزية ترتبط بأربع ذرات أكسجين بأربع روابط أحادية (4 أزواج)، ويبقى 12 زوجًا توزع على ذرات الأكسجين (3 أزواج حرة لكل أكسجين)، فيحيط بكل ذرة 8 إلكترونات، ويوضع التركيب بين قوسين مع الشحنة 3−.', '["إضافة الشحنة السالبة (+3)","المجموع 32 إلكترونًا = 16 زوجًا","P مركزية مع 4 روابط أحادية","3 أزواج حرة على كل O","القوسان والشحنة"]'::jsonb, '["5 + 4×6 = 29","29 + 3 = 32 إلكترونًا","32 ÷ 2 = 16 زوجًا","4 أزواج رابطة، و16 − 4 = 12 زوجًا حرًا (3 لكل O)"]'::jsonb, '[{"element":"حساب المجموع مع الشحنة","marks":2},{"element":"عدد الأزواج","marks":1},{"element":"وصف التركيب (روابط وأزواج حرة)","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"حساب ووصف كاملان صحيحان"},{"level":"3–4 درجات","description":"حساب صحيح مع وصف ناقص"},{"level":"1–2 درجة","description":"حساب دون الشحنة أو وصف جزئي"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["طرح الشحنة بدل إضافتها (26 إلكترونًا)","نسيان كتابة الشحنة على التركيب"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-10-11T13:13:22.415Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(981, 2, 'رابطة سيجما تنتج عن التداخل المباشر (رأسًا لرأس) بين مستويين للذرتين المرتبطتين.', '["هذا وصف رابطة باي (π).","انتقال الإلكترونات لا يكوّن رابطة تساهمية.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-11T13:13:22.418Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(982, 0, 'في رابطة سيجما يتركز زوج الإلكترونات بين النواتين على محور الرابطة نتيجة التداخل المباشر.', '["","توزع الكثافة فوق المحور وتحته من صفات رابطة باي.","الزوج مشترك بين الذرتين ولا يتركز حول نواة واحدة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-10-11T13:13:22.418Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(983, 1, 'لكل ذرة هيدروجين إلكترون واحد في المستوى 1s، فتتكون الرابطة من تداخل s مع s رأسًا لرأس.', '["ذرة الهيدروجين لا تمتلك إلكترونات في مستويات p.","","تداخل s مع p يحدث في HF مثلًا، والهيدروجين ليس له إلكترونات p."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-11T13:13:22.419Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(984, 1, 'التداخل الرأسي المباشر يكوّن رابطة سيجما حتى لو كان بين مستويي p؛ فليس كل تداخل p-p رابطة باي.', '["رابطة باي تتكون من تداخل p-p الجانبي (المتوازي) لا الرأسي.","","الفلور لافلز والرابطة بين ذرتيه تساهمية بالمشاركة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-10-11T13:13:22.419Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(985, 1, 'في HF يتداخل مستوى 1s للهيدروجين مع مستوى 2p للفلور رأسًا لرأس، فتتكون سيجما من نوع s-p.', '["رابطة F₂ من تداخل p-p رأسي.","","رابطة H₂ من تداخل s-s."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-10-11T13:13:22.419Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(986, 2, 'في الميثان أربع روابط أحادية C–H، وكل رابطة أحادية هي رابطة سيجما، فعددها 4.', '["يحتوي الجزيء على أربع روابط مستقلة لا رابطة واحدة.","8 هو عدد الإلكترونات المشتركة (4 أزواج) لا عدد الروابط.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-11T13:13:22.419Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(987, 0, 'الرابطة الأحادية زوج واحد يتداخل رأسًا لرأس، فهي دائمًا سيجما.', '["","رابطة باي لا تكون وحدها، بل تأتي إضافة إلى سيجما في الروابط المتعددة.","نوع الذرتين لا يغير ذلك؛ الأحادية سيجما دائمًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-11T13:13:22.419Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(988, null, null, null, 'رابطة سيجما: رابطة تساهمية تنتج عن التداخل المباشر (رأسًا لرأس) بين مستويين للذرتين المرتبطتين. تتركز الكثافة الإلكترونية فيها في المنطقة الواقعة بين النواتين على المحور الواصل بينهما. مثال: الرابطة في H₂ أو HF أو F₂ (أو أي رابطة أحادية).', '["التعريف: تداخل مباشر رأسًا لرأس","الكثافة بين النواتين على المحور","مثال صحيح"]'::jsonb, '[]'::jsonb, '[{"element":"التعريف","marks":1},{"element":"موقع الكثافة الإلكترونية","marks":1},{"element":"المثال","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"إجابة كاملة دقيقة"},{"level":"2 درجتان","description":"إجابة ينقصها عنصر واحد"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تعريفها بالتداخل الجانبي","حصرها في مستويات s"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-10-11T13:13:22.420Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(989, null, null, null, 'H₂: تداخل 1s مع 1s. HF: تداخل 1s (للهيدروجين) مع 2p (للفلور). F₂: تداخل 2p مع 2p رأسًا لرأس. الاستنتاج: لا؛ فرابطة سيجما قد تتكون من تداخل s-s أو s-p أو p-p ما دام التداخل مباشرًا رأسًا لرأس.', '["H₂: s-s","HF: s-p","F₂: p-p رأسي","الاستنتاج: سيجما ليست مقتصرة على s"]'::jsonb, '[]'::jsonb, '[{"element":"H₂","marks":1},{"element":"HF","marks":1},{"element":"F₂","marks":1},{"element":"الاستنتاج","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة دقيقة بجميع العناصر"},{"level":"3 درجات","description":"إجابة صحيحة ينقصها عنصر واحد"},{"level":"2 درجتان","description":"إجابة صحيحة جزئيًا بعنصرين"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عد تداخل p-p في F₂ رابطة باي","القول إن الهيدروجين يستخدم مستوى p"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-11T13:13:22.420Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(990, null, null, null, 'لأن الرابطة الأحادية تتكون من زوج إلكترونات واحد ناتج عن تداخل مباشر (رأسًا لرأس) بين مستويي الذرتين على المحور الواصل بين النواتين، وهذا هو تعريف رابطة سيجما؛ أما رابطة باي فلا تتكون إلا إضافة إلى رابطة سيجما في الروابط الثنائية والثلاثية.', '["الأحادية زوج واحد","يتكون بتداخل رأسي مباشر","هذا تعريف سيجما","باي لا توجد إلا مع سيجما في الروابط المتعددة"]'::jsonb, '[]'::jsonb, '[{"element":"التداخل الرأسي للزوج الواحد","marks":1},{"element":"ربطه بتعريف سيجما","marks":1},{"element":"باي لا تكون منفردة","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"إجابة كاملة دقيقة"},{"level":"2 درجتان","description":"إجابة ينقصها عنصر واحد"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الاكتفاء بقول «لأنها أقوى»","القول إن الأحادية قد تكون باي"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-11T13:13:22.420Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(991, 1, 'رابطة باي تنتج عن التداخل الجانبي لمستويي p متوازيين، فتتوزع إلكتروناتها فوق محور الرابطة وتحته.', '["تداخل s-s يكوّن رابطة سيجما كما في H₂.","","التداخل الرأسي يكوّن رابطة سيجما."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-11T13:13:22.423Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(992, 2, 'الرابطة الثنائية = σ واحدة (التداخل الرأسي الأول) + π واحدة (تداخل جانبي إضافي).', '["لا تتكون رابطة باي دون وجود رابطة سيجما بين الذرتين.","لا يمكن تكوين أكثر من رابطة سيجما واحدة بين ذرتين؛ الرابطة الإضافية تكون باي.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-11T13:13:22.423Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(993, 1, 'الرابطة الثلاثية = 1σ + 2π.', '["الروابط الإضافية على سيجما الأولى تكون من نوع باي.","","بين ذرتين لا توجد إلا رابطة سيجما واحدة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-10-11T13:13:22.424Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(994, 0, 'في سيجما يكون التداخل رأسًا لرأس فتتركز الكثافة بين النواتين ويكون التداخل أكبر، أما في باي فالتداخل جانبي أقل.', '["","توزع الإلكترونات فوق المحور وتحته من صفات باي لا سيجما.","سيجما توجد في كل الروابط التساهمية بما فيها الأحادية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (55%)"}],"at":"2026-10-11T13:13:22.424Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(995, 0, 'أربع روابط C–H أحادية (4σ) + الرابطة الثنائية C=C (1σ + 1π) = 5σ و1π.', '["","عدّ الرابطة الثنائية رابطتي سيجما وإهمال باي.","عدّ الرابطة الثنائية رابطتي باي، والصحيح أنها سيجما وباي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-10-11T13:13:22.424Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(996, 2, 'C₂H₂: رابطتان C–H (2σ) + C≡C (1σ + 2π) = 3σ و2π. أما HCHO ففيه 3σ و1π، وCO₂ فيه 2σ و2π.', '["HCHO: رابطتان C–H ورابطة C=O، أي 3σ و1π.","CO₂: رابطتان ثنائيتان، أي 2σ و2π.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-11T13:13:22.424Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(997, 1, 'رابطة باي تأتي إضافة إلى سيجما في الروابط الثنائية والثلاثية، ولا توجد منفردة.', '["هذا مفهوم خاطئ؛ أول رابطة بين ذرتين تكون دائمًا سيجما.","","رابطة باي الواحدة أضعف من سيجما؛ وقوة الرابطة المتعددة ككل ناتجة عن مجموع روابطها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-11T13:13:22.425Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(998, null, null, null, 'طريقة التداخل: سيجما تداخل مباشر رأسًا لرأس، وباي تداخل جانبي لمستويي p متوازيين. موقع الكثافة: في سيجما بين النواتين على محور الرابطة، وفي باي فوق المحور وتحته. القوة: سيجما أقوى من باي لأن تداخلها أكبر. الوجود في الأحادية: الرابطة الأحادية سيجما دائمًا، ولا توجد باي إلا في الروابط الثنائية والثلاثية.', '["التداخل: رأسي/جانبي","الكثافة: على المحور/فوقه وتحته","القوة: سيجما أقوى","الأحادية سيجما وباي في المتعددة فقط"]'::jsonb, '[]'::jsonb, '[{"element":"طريقة التداخل","marks":1},{"element":"موقع الكثافة","marks":1},{"element":"القوة","marks":1},{"element":"الوجود في الروابط","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة دقيقة بجميع العناصر"},{"level":"3 درجات","description":"إجابة صحيحة ينقصها عنصر واحد"},{"level":"2 درجتان","description":"إجابة صحيحة جزئيًا بعنصرين"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عد باي أقوى من سيجما","القول إن الرابطة الثنائية رابطتا باي"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-11T13:13:22.425Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(999, null, null, null, 'C₂H₄ (H₂C=CH₂): 4 روابط C–H (4σ) + C=C (1σ + 1π) ← 5σ و1π. C₂H₂ (HC≡CH): رابطتان C–H (2σ) + C≡C (1σ + 2π) ← 3σ و2π. HCHO (H₂C=O): رابطتان C–H (2σ) + C=O (1σ + 1π) ← 3σ و1π.', '["C₂H₄: 5σ و1π","C₂H₂: 3σ و2π","HCHO: 3σ و1π","توضيح أن كل رابطة متعددة فيها سيجما واحدة فقط"]'::jsonb, '["كل رابطة أحادية = 1σ، والثنائية = 1σ + 1π، والثلاثية = 1σ + 2π","C₂H₄: 4 + 1 = 5σ ، 1π","C₂H₂: 2 + 1 = 3σ ، 2π","HCHO: 2 + 1 = 3σ ، 1π"]'::jsonb, '[{"element":"C₂H₄","marks":2},{"element":"C₂H₂","marks":2},{"element":"HCHO","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"الجزيئات الثلاثة صحيحة مع التوضيح"},{"level":"4 درجات","description":"جزيئان صحيحان"},{"level":"2 درجتان","description":"جزيء واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عد الرابطة الثنائية رابطتي سيجما","نسيان روابط C–H"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-11T13:13:22.425Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1000, null, null, null, 'لأن الرابطة الثنائية تتكون من رابطة سيجما ورابطة باي معًا، أي زوجين مشتركين بدل زوج واحد، فمجموع قوى الترابط فيها أكبر من رابطة سيجما وحدها، وتكون أقصر وتحتاج إلى طاقة أكبر لتفكيكها. كون باي أضعف من سيجما يعني فقط أن الرابطة الثنائية أقل من ضعف قوة الأحادية، لا أنها أضعف منها.', '["الثنائية = سيجما + باي","زوجان مشتركان يزيدان قوة الترابط الكلية","الثنائية أقصر وطاقة تفككها أكبر","لا تعارض: باي تضيف قوة وإن كانت أضعف من سيجما"]'::jsonb, '[]'::jsonb, '[{"element":"تركيب الرابطة الثنائية","marks":1},{"element":"زيادة القوة الكلية بالمشاركة الإضافية","marks":1},{"element":"إزالة التعارض الظاهري","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"إجابة كاملة دقيقة"},{"level":"2 درجتان","description":"إجابة ينقصها عنصر واحد"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن باي أقوى من سيجما","الاكتفاء بقول «لأنها ثنائية»"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (55%)"}],"at":"2026-10-11T13:13:22.425Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1001, 0, 'طول الرابطة هو المسافة بين نواتي ذرتين مرتبطتين عند أقصى تجاذب بينهما.', '["","مجموع أنصاف أقطار ذرات الجزيء كلها لا يمثل رابطة واحدة.","هذه ليست مسافة بين ذرتين مرتبطتين أصلًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-11T13:13:22.430Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1002, 1, 'كلما زاد عدد الأزواج المشتركة قصرت الرابطة؛ فالأحادية أطول ثم الثنائية ثم الثلاثية.', '["الأحادية أطول من الثنائية لا أقصر.","","هذا الترتيب معكوس؛ الثلاثية هي الأقصر."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-11T13:13:22.430Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1003, 1, 'الرابطة الأقصر تكون فيها الإلكترونات المشتركة أكثر والتجاذب أقوى، فقوة الرابطة تتناسب عكسيًا مع طولها.', '["يوجد ارتباط واضح: الثلاثية أقصر وأقوى من الأحادية.","","الرابطة الأطول أضعف، فالعلاقة ليست طردية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-11T13:13:22.430Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.')
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check, reviewer_notes) values
(1004, 2, 'طاقة التفكك هي الطاقة اللازمة لكسر رابطة معينة، والرابطة الأقوى تحتاج طاقة أكبر، فالعلاقة طردية.', '["التعريف صحيح لكن العلاقة معكوسة؛ الرابطة الأقوى أصعب كسرًا.","كسر الروابط يمتص طاقة ولا يطلقها، والعلاقة طردية لا عكسية.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-11T13:13:22.431Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1005, 1, 'أقصر رابطة هي رابطة N₂ (110 pm) وهي ثلاثية، فهي الأقوى وطاقة تفككها الأكبر (945 kJ/mol تقريبًا).', '["F₂ رابطته أحادية وهي الأطول (143 pm) فطاقة تفككها الأقل.","","O₂ رابطته ثنائية أطول (121 pm) فهي أضعف من N₂."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-11T13:13:22.431Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1006, 0, 'إذا كانت طاقة التفكيك الممتصة أكبر من طاقة التكوين المنطلقة فالمحصلة امتصاص طاقة، أي أن التفاعل ماص.', '["","الطاقتان غير متساويتين، فلا بد من تغير في الطاقة.","الطارد يحدث عندما تكون طاقة التفكيك أقل من طاقة التكوين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-10-11T13:13:22.431Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1007, 2, 'الرابطة في C≡N⁻ ثلاثية (ثلاثة أزواج مشتركة)، فهي أقصر وأقوى من الرابطة الأحادية C–N في H₃C–NH₂.', '["تشابه الذرتين لا يعني تساوي الرابطة؛ عدد الأزواج المشتركة مختلف.","الرابطة الأحادية هي الأطول والأضعف.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-11T13:13:22.432Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1008, null, null, null, '(أ) كلما زاد عدد الأزواج المشتركة (من 1 إلى 3) قصرت الرابطة (154 ← 134 ← 120 pm). (ب) كلما قصرت الرابطة زادت طاقة تفككها (348 ← 614 ← 839 kJ/mol)، فالعلاقة عكسية. (ج) الرابطة الأقوى تحتاج طاقة أكبر لتفكيكها، فقوة الرابطة تتناسب طرديًا مع طاقة تفككها؛ وعليه C≡C هي الأقصر والأقوى.', '["زيادة الأزواج المشتركة تقصّر الرابطة","العلاقة عكسية بين الطول وطاقة التفكك","العلاقة طردية بين القوة وطاقة التفكك","الاستشهاد بأرقام الجدول"]'::jsonb, '[]'::jsonb, '[{"element":"الاستنتاج (أ)","marks":1},{"element":"الاستنتاج (ب) مع الأرقام","marks":2},{"element":"الاستنتاج (ج)","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة دقيقة بجميع العناصر"},{"level":"3 درجات","description":"إجابة صحيحة ينقصها عنصر واحد"},{"level":"2 درجتان","description":"إجابة صحيحة جزئيًا بعنصرين"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عكس العلاقة بين الطول وطاقة التفكك","الاستنتاج دون الاستشهاد بالبيانات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-11T13:13:22.435Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1009, null, null, null, 'الترتيب التصاعدي: F₂ < O₂ < N₂. التعليل: رابطة F₂ أحادية (زوج مشترك واحد) فهي الأطول والأضعف، ورابطة O₂ ثنائية (زوجان) أقصر وأقوى، ورابطة N₂ ثلاثية (ثلاثة أزواج) هي الأقصر والأقوى، وكلما زادت قوة الرابطة زادت طاقة تفككها.', '["الترتيب الصحيح F₂ < O₂ < N₂","نوع الرابطة في كل جزيء","الربط بين عدد الأزواج والطول والقوة وطاقة التفكك"]'::jsonb, '[]'::jsonb, '[{"element":"الترتيب","marks":1},{"element":"أنواع الروابط","marks":1},{"element":"التعليل بالعلاقة","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة دقيقة بجميع العناصر"},{"level":"3 درجات","description":"إجابة صحيحة ينقصها عنصر واحد"},{"level":"2 درجتان","description":"إجابة صحيحة جزئيًا بعنصرين"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عكس الترتيب","التعليل بالكتلة المولية بدل نوع الرابطة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-11T13:13:22.435Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1010, null, null, null, 'يحتاج تفكيك روابط المتفاعلات إلى امتصاص طاقة، وينطلق عند تكوين روابط النواتج طاقة. فإذا كانت طاقة تفكيك روابط المتفاعلات أكبر من طاقة تكوين روابط النواتج كان التفاعل ماصًا للطاقة، وإذا كانت طاقة تفكيك روابط المتفاعلات أقل من طاقة تكوين روابط النواتج كان التفاعل طاردًا للطاقة.', '["التفكيك يمتص طاقة","التكوين يطلق طاقة","الماص: التفكيك > التكوين","الطارد: التفكيك < التكوين"]'::jsonb, '[]'::jsonb, '[{"element":"امتصاص الطاقة عند التفكيك وانطلاقها عند التكوين","marks":1},{"element":"شرط التفاعل الماص","marks":1},{"element":"شرط التفاعل الطارد","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"إجابة كاملة دقيقة"},{"level":"2 درجتان","description":"إجابة ينقصها عنصر واحد"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن تكوين الروابط يمتص طاقة","وصف الحالتين كلتيهما بأنهما ماصتان (كما ورد خطأً في المذكرة)"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-11T13:13:22.435Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1011, 0, 'يبدأ الاسم ببادئة عدد ذرات العنصر الثاني (O: خماسي) مع «أكسيد»، ثم بادئة عدد ذرات العنصر الأول (N: ثنائي) واسمه: خماسي أكسيد ثنائي النيتروجين.', '["","عكس البادئتين بين العنصرين.","إهمال البادئة الدالة على وجود ذرتي نيتروجين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-11T13:13:22.454Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1012, 0, 'للكلور 4 ذرات (رباعي كلوريد)، وللكربون ذرة واحدة ولا تُستخدم البادئة «أحادي» مع العنصر الأول، فالاسم: رباعي كلوريد الكربون.', '["","لا تستخدم البادئة «أحادي» للعنصر الأول في الصيغة.","عكس ترتيب العنصرين؛ المقطع «يد» يضاف للعنصر الثاني (الكلور) لا للكربون."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-11T13:13:22.454Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1013, 0, 'O عددها 5 (خماسي أكسيد) وP عددها 2 (ثنائي الفوسفور): خماسي أكسيد ثنائي الفوسفور.', '["","تبديل البادئتين بين العنصرين.","عكس دور العنصرين؛ الأكسجين هو العنصر الثاني الذي يأخذ المقطع «يد»."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-11T13:13:22.455Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1014, 1, 'F عددها 4 (رباعي فلوريد) وN عددها 2 (ثنائي النيتروجين): رباعي فلوريد ثنائي النيتروجين.', '["إضافة المقطع «يد» إلى العنصر الأول بدل الثاني.","","عكس البادئتين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-11T13:13:22.455Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1015, 2, 'من قواعد التسمية أن العنصر الأول إذا كان منه ذرة واحدة لا تكتب قبله البادئة «أحادي».', '["البادئات أساسية في تسمية المركبات الجزيئية الثنائية، والاسم نفسه يحتوي على «سداسي».","الكبريت هنا مرتبط بست ذرات فلور، فالعبارة خاطئة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-11T13:13:22.455Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1016, 1, 'PCl₅: خمس ذرات كلور وذرة فوسفور واحدة، فالاسم خماسي كلوريد الفوسفور.', '["SO₃ فيه ثلاث ذرات أكسجين فاسمه ثلاثي أكسيد الكبريت.","","NF₃ فيه ثلاث ذرات فلور فاسمه ثلاثي فلوريد النيتروجين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-11T13:13:22.455Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1017, 2, 'عشر ذرات فلور (عشاري فلوريد) وذرتا كبريت (ثنائي الكبريت)، فالاسم عشاري فلوريد ثنائي الكبريت؛ وقد عكس الطالب البادئتين.', '["عكس دوري العنصرين؛ الفلور هو العنصر الثاني الذي يأخذ «يد».","إهمال بادئة العشرة ووضع بادئة الكبريت للفلور.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-11T13:13:22.455Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1018, null, null, null, 'SO₃: ثلاثي أكسيد الكبريت. NF₃: ثلاثي فلوريد النيتروجين. CCl₄: رباعي كلوريد الكربون. N₂O₃: ثلاثي أكسيد ثنائي النيتروجين.', '["ثلاثي أكسيد الكبريت","ثلاثي فلوريد النيتروجين","رباعي كلوريد الكربون","ثلاثي أكسيد ثنائي النيتروجين"]'::jsonb, '[]'::jsonb, '[{"element":"SO₃","marks":1},{"element":"NF₃","marks":1},{"element":"CCl₄","marks":1},{"element":"N₂O₃","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة دقيقة بجميع العناصر"},{"level":"3 درجات","description":"إجابة صحيحة ينقصها عنصر واحد"},{"level":"2 درجتان","description":"إجابة صحيحة جزئيًا بعنصرين"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["استخدام «أحادي» مع العنصر الأول","عكس البادئتين في N₂O₃"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-11T13:13:22.456Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1019, null, null, null, 'الخطوات: (1) نحدد العنصر الثاني في الصيغة ونكتب البادئة الدالة على عدد ذراته ثم جذر اسمه مع المقطع «يد». (2) نكتب البادئة الدالة على عدد ذرات العنصر الأول ثم اسمه، ولا نستخدم «أحادي» للعنصر الأول. التطبيق: P₂O₅: الأكسجين 5 ذرات ← خماسي أكسيد، والفوسفور ذرتان ← ثنائي الفوسفور؛ الاسم: خماسي أكسيد ثنائي الفوسفور.', '["بادئة العنصر الثاني وجذره مع «يد»","بادئة العنصر الأول واسمه","عدم استخدام «أحادي» للأول","التطبيق الصحيح على P₂O₅"]'::jsonb, '["O: 5 ذرات ← خماسي أكسيد","P: 2 ذرتان ← ثنائي الفوسفور","الاسم: خماسي أكسيد ثنائي الفوسفور"]'::jsonb, '[{"element":"خطوة العنصر الثاني","marks":1},{"element":"خطوة العنصر الأول وقاعدة «أحادي»","marks":1},{"element":"التطبيق على P₂O₅","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة دقيقة بجميع العناصر"},{"level":"3 درجات","description":"إجابة صحيحة ينقصها عنصر واحد"},{"level":"2 درجتان","description":"إجابة صحيحة جزئيًا بعنصرين"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["إضافة «يد» إلى العنصر الأول","نسيان بادئة الفوسفور"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-11T13:13:22.456Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1020, null, null, null, '(أ) الخطأ: عكس البادئتين؛ الصحيح: رباعي فلوريد ثنائي النيتروجين. (ب) الخطأ: استخدام «أحادي» مع العنصر الأول؛ الصحيح: ثنائي كبريتيد الكربون. (ج) الخطأ: البادئة؛ عدد ذرات الفلور 6؛ الصحيح: سداسي فلوريد الكبريت.', '["تحديد الخطأ وتصحيحه في (أ)","تحديد الخطأ وتصحيحه في (ب)","تحديد الخطأ وتصحيحه في (ج)"]'::jsonb, '[]'::jsonb, '[{"element":"(أ)","marks":2},{"element":"(ب)","marks":2},{"element":"(ج)","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"تحديد الأخطاء الثلاثة وتصحيحها"},{"level":"4 درجات","description":"اسمان صحيحان"},{"level":"2 درجتان","description":"اسم واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تصحيح الاسم دون تحديد الخطأ","الإبقاء على «أحادي» في (ب)"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-10-11T13:13:22.456Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1021, 0, 'NH₃ (ثالث هيدريد النيتروجين) يعرف بالاسم الشائع الأمونيا.', '["","الهيدرازين هو الاسم الشائع لـ N₂H₄.","الميثان هو CH₄ ولا يحتوي على نيتروجين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (56%)"}],"at":"2026-10-11T13:13:22.459Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1022, 0, 'رابع هيدريد ثنائي النيتروجين N₂H₄ اسمه الشائع الهيدرازين.', '["","الماء هو H₂O ولا يحتوي على نيتروجين.","الأمونيا هي NH₃ (ثالث هيدريد النيتروجين)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (56%)"}],"at":"2026-10-11T13:13:22.459Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1023, 2, 'ذرة أكسجين واحدة (أكسيد) وذرتا هيدروجين (ثنائي الهيدروجين): أكسيد ثنائي الهيدروجين.', '["عكس دوري العنصرين وعدد الذرات.","البادئة «ثنائي» تخص الهيدروجين لا الأكسجين.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-10-11T13:13:22.460Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1024, 2, 'N₂H₄ اسمه النظامي رابع هيدريد ثنائي النيتروجين واسمه الشائع الهيدرازين.', '["الاسم الشائع لـ H₂O هو الماء لا الأمونيا.","الاسم الشائع لـ NH₃ هو الأمونيا لا الهيدرازين.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-11T13:13:22.460Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
