(1026, 1, 'الأمونيا NH₃ (ثالث هيدريد النيتروجين) تحتوي على ثلاث ذرات هيدروجين.', '["ذرتا هيدروجين في الماء H₂O.","","4 ذرات هيدروجين في الهيدرازين N₂H₄."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-11T13:13:22.460Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1027, 1, 'الهيدرازين N₂H₄ (رابع هيدريد ثنائي النيتروجين) فيه ذرتا نيتروجين، كما تدل البادئة «ثنائي النيتروجين».', '["الأمونيا NH₃ فيها ذرة نيتروجين واحدة.","","الماء H₂O لا يحتوي على نيتروجين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-10-11T13:13:22.460Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1028, null, null, null, 'ثالث هيدريد النيتروجين: الأمونيا، NH₃. رابع هيدريد ثنائي النيتروجين: الهيدرازين، N₂H₄. أكسيد ثنائي الهيدروجين: الماء، H₂O.', '["الأمونيا NH₃","الهيدرازين N₂H₄","الماء H₂O"]'::jsonb, '[]'::jsonb, '[{"element":"الأمونيا وصيغتها","marks":2},{"element":"الهيدرازين وصيغته","marks":2},{"element":"الماء وصيغته","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"الأسماء والصيغ الثلاث صحيحة"},{"level":"4 درجات","description":"مركبان صحيحان كاملان"},{"level":"2 درجتان","description":"مركب واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الخلط بين الأمونيا والهيدرازين","كتابة N₂H₄ بالشكل NH₄"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (43%)"}],"at":"2026-10-11T13:13:22.461Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1029, null, null, null, '«رابع هيدريد» تدل على وجود أربع ذرات هيدروجين، و«ثنائي النيتروجين» تدل على وجود ذرتي نيتروجين، فالصيغة N₂H₄. واسمه الشائع: الهيدرازين.', '["رابع هيدريد ← 4 ذرات H","ثنائي النيتروجين ← 2 ذرة N","الصيغة N₂H₄","الاسم الشائع الهيدرازين"]'::jsonb, '[]'::jsonb, '[{"element":"تفسير البادئتين","marks":2},{"element":"الصيغة","marks":1},{"element":"الاسم الشائع","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة دقيقة بجميع العناصر"},{"level":"3 درجات","description":"إجابة صحيحة ينقصها عنصر واحد"},{"level":"2 درجتان","description":"إجابة صحيحة جزئيًا بعنصرين"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة الصيغة H₄N₂ دون ترتيب","تسميته الأمونيا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-10-11T13:13:22.461Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1030, null, null, null, 'الأمونيا: الاسم النظامي ثالث هيدريد النيتروجين، الصيغة NH₃، فيها ذرة N واحدة و3 ذرات H. الهيدرازين: الاسم النظامي رابع هيدريد ثنائي النيتروجين، الصيغة N₂H₄، فيه ذرتا N و4 ذرات H.', '["الاسمان النظاميان","الصيغتان","عدد الذرات في كل جزيء"]'::jsonb, '[]'::jsonb, '[{"element":"الأسماء النظامية","marks":1},{"element":"الصيغ","marks":1},{"element":"أعداد الذرات","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"إجابة كاملة دقيقة"},{"level":"2 درجتان","description":"إجابة ينقصها عنصر واحد"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الخلط بين الصيغتين","عد ذرات النيتروجين في الأمونيا اثنتين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-11T13:13:22.461Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1031, 1, 'الحمض الثنائي يتكون من عنصرين فقط: الهيدروجين وعنصر لافلزي آخر، ولا يحتوي على الأكسجين.', '["هذا تعريف الحمض الأكسجيني.","","«ثنائي» تعني عنصرين مختلفين لا ذرتي هيدروجين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-11T13:13:22.464Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1032, 0, 'HBr يتكون من عنصرين فقط: الهيدروجين والبروم، فهو حمض ثنائي.', '["","HNO₃ يحتوي على ثلاثة عناصر منها الأكسجين، فهو حمض أكسجيني.","H₂SO₄ يحتوي على أيون الكبريتات الأكسجيني، فهو حمض أكسجيني."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (43%)"}],"at":"2026-10-11T13:13:22.464Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1033, 2, 'تصنيف الحمض ثنائيًا يعتمد على عدد أنواع العناصر (عنصران)، لا على عدد ذرات الهيدروجين.', '["عدد ذرات الهيدروجين ليس معيار التصنيف؛ فـ HCl ثنائي وفيه ذرة هيدروجين واحدة.","H₂S لا يحتوي على الأكسجين إطلاقًا.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (43%)"}],"at":"2026-10-11T13:13:22.465Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1034, 0, 'يسمى الحمض الثنائي بكلمة «حمض» ثم البادئة «هيدرو» متصلة بجذر العنصر الآخر مع «يك»، مثل حمض الهيدروكلوريك.', '["","هذه طريقة تسمية الأحماض الأكسجينية.","هذه تشبه تسمية المركب الثنائي (مثل كلوريد الهيدروجين) لا الحمض."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-11T13:13:22.465Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1035, 1, 'HI يتكون من الهيدروجين واليود فقط، فهو ثنائي.', '["H₃PO₄ يحتوي على أيون الفوسفات الأكسجيني فهو أكسجيني.","","HClO₃ يحتوي على أيون الكلورات الأكسجيني فهو أكسجيني."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-11T13:13:22.465Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1036, 1, 'الحمض الثنائي مكون من الهيدروجين وعنصر لافلزي آخر فقط، فلا يحتوي على الأكسجين.', '["العنصر الآخر في الحمض الثنائي لافلز مثل Cl أو S.","","معظم الأحماض الثنائية مثل HCl وHF فيها ذرة هيدروجين واحدة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-11T13:13:22.465Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1037, 2, 'HCN يتكون من H وC وN (ثلاثة عناصر) فليس ثنائيًا، لكنه يسمى كالأحماض الثنائية لأنه لا يحتوي على الأكسجين.', '["أيون السيانيد لا يحتوي على الأكسجين فلا يكون الحمض أكسجينيًا.","السيانيد CN⁻ أيون من عنصرين وليس عنصرًا واحدًا، فالحمض من ثلاثة عناصر.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-11T13:13:22.465Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1038, null, null, null, 'الحمض الثنائي: حمض يتكون من عنصرين فقط هما الهيدروجين وعنصر لافلزي آخر، ولا يحتوي على الأكسجين. مثالان: HCl حمض الهيدروكلوريك، HF حمض الهيدروفلوريك (ويقبل HBr حمض الهيدروبروميك، HI حمض الهيدرويوديك، H₂S حمض الهيدروكبريتيك).', '["التعريف: هيدروجين + عنصر آخر فقط","عدم احتوائه على الأكسجين","مثالان صحيحان","تسمية صحيحة للمثالين"]'::jsonb, '[]'::jsonb, '[{"element":"التعريف","marks":2},{"element":"المثالان","marks":1},{"element":"تسمية المثالين","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة دقيقة بجميع العناصر"},{"level":"3 درجات","description":"إجابة صحيحة ينقصها عنصر واحد"},{"level":"2 درجتان","description":"إجابة صحيحة جزئيًا بعنصرين"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تعريفه بأنه يحتوي على ذرتي هيدروجين","التمثيل بـ H₂SO₄"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-11T13:13:22.465Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1039, null, null, null, 'العبارة خاطئة. معيار الحمض الثنائي أن يتكون من عنصرين فقط (الهيدروجين وعنصر آخر) لا أن يحتوي على ذرتي هيدروجين. وH₂SO₄ يتكون من ثلاثة عناصر (H وS وO) ويحتوي على أيون الكبريتات الأكسجيني، فهو حمض أكسجيني ويسمى حمض الكبريتيك.', '["الحكم بخطأ العبارة","المعيار الصحيح: عنصران فقط","H₂SO₄ من ثلاثة عناصر وفيه أكسجين","تصنيفه الصحيح: أكسجيني"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم","marks":1},{"element":"بيان المعيار الصحيح","marks":1},{"element":"التصنيف الصحيح مع السبب","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة دقيقة بجميع العناصر"},{"level":"3 درجات","description":"إجابة صحيحة ينقصها عنصر واحد"},{"level":"2 درجتان","description":"إجابة صحيحة جزئيًا بعنصرين"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["قبول العبارة","رفضها دون ذكر المعيار"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-11T13:13:22.466Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1040, null, null, null, 'ثنائية: HF (H وF فقط)، H₂S (H وS فقط). غير ثنائية (أكسجينية): HNO₂ لأنه يحتوي على أيون النتريت الأكسجيني (H وN وO)، وH₂CO₃ لأنه يحتوي على أيون الكربونات الأكسجيني (H وC وO).', '["HF ثنائي","H₂S ثنائي","HNO₂ أكسجيني","H₂CO₃ أكسجيني","ذكر السبب لكل منها"]'::jsonb, '[]'::jsonb, '[{"element":"تصنيف الأحماض الأربعة","marks":2},{"element":"ذكر السبب","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة دقيقة بجميع العناصر"},{"level":"3 درجات","description":"إجابة صحيحة ينقصها عنصر واحد"},{"level":"2 درجتان","description":"إجابة صحيحة جزئيًا بعنصرين"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عد H₂S غير ثنائي لاحتوائه على ذرتي H","عد H₂CO₃ ثنائيًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-11T13:13:22.466Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1041, 1, 'HCl حمض ثنائي فيسمى: حمض + هيدرو + كلور + يك = حمض الهيدروكلوريك.', '["حمض الكلوريك هو HClO₃ (حمض أكسجيني).","","المقطع «وز» لا يستخدم في تسمية الأحماض الثنائية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (60%)"}],"at":"2026-10-11T13:13:22.469Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1042, 1, 'HF يتكون من الهيدروجين والفلور فقط فاسمه حمض الهيدروفلوريك.', '["المقطع الصحيح في الأحماض الثنائية «يك» لا «وز».","","نسيان البادئة «هيدرو» الخاصة بالأحماض الثنائية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-11T13:13:22.469Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1043, 0, 'حمض + هيدرو + يود + يك = حمض الهيدرويوديك.', '["","حذف البادئة «هيدرو» يجعل الاسم يشبه أسماء الأحماض الأكسجينية.","هذه ليست طريقة تسمية الأحماض."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-11T13:13:22.469Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1044, 0, 'H₂S حمض ثنائي (هيدروجين وكبريت فقط) فاسمه حمض الهيدروكبريتيك، ولا تستخدم البادئات العددية في أسماء الأحماض.', '["","البادئات العددية (ثنائي...) لا تستخدم في تسمية الأحماض.","حمض الكبريتيك هو H₂SO₄ الأكسجيني."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (60%)"}],"at":"2026-10-11T13:13:22.469Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1045, 2, 'اسم H₂S الصحيح حمض الهيدروكبريتيك، وكتب الطالب «حمض الكبريتيك» وهو اسم H₂SO₄. أما بقية الأسماء فصحيحة.', '["حمض الهيدرويوديك اسم صحيح لـ HI.","حمض الهيدروكلوريك اسم صحيح لـ HCl.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-10-11T13:13:22.469Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1046, 2, 'تسمية الأحماض الثنائية: حمض + هيدرو + جذر العنصر + «يك».', '["المقطع «يد» يستخدم في تسمية المركبات الثنائية مثل كلوريد، لا في أسماء الأحماض.","المقطع «وز» يستخدم مع بعض الأحماض الأكسجينية المشتقة من أيونات تنتهي بـ«يت».",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-10-11T13:13:22.470Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1047, 1, 'عنصر المجموعة 17 في الدورة الثالثة هو الكلور، فالحمض HCl: حمض الهيدروكلوريك.', '["الفلور في الدورة الثانية.","","اليود في الدورة الخامسة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-11T13:13:22.470Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1048, null, null, null, 'HCl: حمض الهيدروكلوريك. HF: حمض الهيدروفلوريك. HI: حمض الهيدرويوديك. H₂S: حمض الهيدروكبريتيك.', '["حمض الهيدروكلوريك","حمض الهيدروفلوريك","حمض الهيدرويوديك","حمض الهيدروكبريتيك"]'::jsonb, '[]'::jsonb, '[{"element":"HCl","marks":1},{"element":"HF","marks":1},{"element":"HI","marks":1},{"element":"H₂S","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة دقيقة بجميع العناصر"},{"level":"3 درجات","description":"إجابة صحيحة ينقصها عنصر واحد"},{"level":"2 درجتان","description":"إجابة صحيحة جزئيًا بعنصرين"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تسمية H₂S حمض الكبريتيك","حذف البادئة «هيدرو»"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-11T13:13:22.470Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1049, null, null, null, 'الخطوات: (1) نكتب كلمة «حمض». (2) نضيف البادئة «هيدرو». (3) نضيف جذر اسم العنصر الآخر (غير الهيدروجين). (4) نضيف المقطع «يك». التطبيق: HI ← حمض + هيدرو + يود + يك = حمض الهيدرويوديك.', '["كلمة حمض","البادئة هيدرو","جذر العنصر الآخر","المقطع يك","التطبيق الصحيح"]'::jsonb, '["حمض","هيدرو","يود","يك ← حمض الهيدرويوديك"]'::jsonb, '[{"element":"الخطوات","marks":2},{"element":"التطبيق","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة دقيقة بجميع العناصر"},{"level":"3 درجات","description":"إجابة صحيحة ينقصها عنصر واحد"},{"level":"2 درجتان","description":"إجابة صحيحة جزئيًا بعنصرين"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["نسيان البادئة هيدرو","استخدام المقطع يد"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-11T13:13:22.470Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1050, null, null, null, 'لا يسمى «حمض ثنائي الهيدروكبريتيك» لأن البادئات العددية لا تستخدم في تسمية الأحماض، بل تستخدم في المركبات الجزيئية الثنائية. ولا يسمى «حمض الكبريتيك» لأن هذا اسم الحمض الأكسجيني H₂SO₄ المشتق من أيون الكبريتات، أما H₂S فحمض ثنائي لا يحتوي على الأكسجين فتلزمه البادئة «هيدرو».', '["البادئات العددية لا تستخدم في أسماء الأحماض","حمض الكبريتيك اسم H₂SO₄","H₂S ثنائي بلا أكسجين فيأخذ «هيدرو»"]'::jsonb, '[]'::jsonb, '[{"element":"رفض البادئة العددية مع السبب","marks":1},{"element":"رفض «الكبريتيك» مع السبب","marks":1},{"element":"تبرير «هيدرو»","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"إجابة كاملة دقيقة"},{"level":"2 درجتان","description":"إجابة ينقصها عنصر واحد"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الاكتفاء بذكر الاسم الصحيح دون تعليل","الخلط بين H₂S وH₂SO₄"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-11T13:13:22.470Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1051, 1, 'الحمض الأكسجيني حمض يتكون من الهيدروجين وأيون عديد الذرات يحتوي على الأكسجين (أيون أكسجيني) مثل HNO₃ الذي يحتوي على أيون النترات NO₃⁻.', '["هذا تعريف الحمض الثنائي مثل HCl وH₂S، وليس الحمض الأكسجيني.","","هذا وصف الأكسيد (مثل CO₂)، والأكسيد ليس بالضرورة حمضًا ولا يحتوي على الهيدروجين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-10-11T13:13:22.474Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1052, 2, 'HNO₂ يتكون من الهيدروجين وأيون النتريت NO₂⁻ وهو أيون أكسجيني، لذا فهو حمض أكسجيني (حمض النيتروز).', '["HBr حمض ثنائي يتكون من الهيدروجين والبروم فقط ولا يحتوي على الأكسجين.","H₂S حمض ثنائي يتكون من الهيدروجين والكبريت فقط ولا يحتوي على الأكسجين.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-10-11T13:13:22.474Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1053, 0, 'HCN لا يحتوي على الأكسجين، فهو حمض غير أكسجيني (حمض الهيدروسيانيك) رغم أنه يتكون من ثلاثة عناصر؛ أما H₂CO₃ وH₃PO₄ فيحتويان على أيونين أكسجينيين (الكربونات والفوسفات) فتصنيفهما صحيح.', '["","H₂CO₃ يحتوي على أيون الكربونات CO₃²⁻ الأكسجيني، فهو حمض أكسجيني وتصنيفه صحيح.","H₃PO₄ يحتوي على أيون الفوسفات PO₄³⁻ الأكسجيني، فهو حمض أكسجيني وتصنيفه صحيح."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (4%)"}],"at":"2026-10-11T13:13:22.474Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1054, 1, 'يدل المقطع «يك» على أن الحمض مشتق من أيون أكسجيني ينتهي اسمه بـ«ات» (الكبريتات SO₄²⁻)، بينما يدل «وز» على أيون ينتهي بـ«يت». ولا يدل المقطع على عدد الذرات.', '["عدد ذرات الهيدروجين لا يظهر في اسم الحمض الأكسجيني؛ فحمض النيتريك HNO₃ فيه ذرة هيدروجين واحدة واسمه ينتهي بـ«يك» أيضًا.","","الحمض الأكسجيني يحتوي على الأكسجين دائمًا، والمقطع «يك» يرد في أسماء الأحماض الأكسجينية والثنائية معًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-10-11T13:13:22.474Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1055, 0, 'شرط الحمض الأكسجيني أن يحتوي على أيون أكسجيني، وأيون السيانيد CN⁻ لا يحتوي على الأكسجين، لذلك يُسمى HCN بالبادئة «هيدرو» (حمض الهيدروسيانيك) كالأحماض الثنائية.', '["","عدد ذرات الهيدروجين لا يحدد نوع الحمض؛ فـ HNO₃ فيه ذرة هيدروجين واحدة وهو حمض أكسجيني.","HCN حمض يتأين في الماء ويعطي أيونات H⁺، والتأين ليس معيار التمييز بين الحمض الأكسجيني وغيره."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-11T13:13:22.475Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1056, 1, 'أيون الكلورات ClO₃⁻ أيون عديد الذرات يحتوي على الأكسجين، فيكوّن مع الهيدروجين الحمض الأكسجيني HClO₃ (حمض الكلوريك).', '["Cl⁻ أيون أحادي الذرة لا يحتوي على الأكسجين، ويكوّن الحمض الثنائي HCl.","","CN⁻ أيون عديد الذرات لكنه لا يحتوي على الأكسجين، ويكوّن HCN وهو حمض غير أكسجيني."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-10-11T13:13:22.475Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1057, 1, 'يحتوي HNO₃ على أيون النترات NO₃⁻ وHNO₂ على أيون النتريت NO₂⁻، وكلاهما أيون أكسجيني؛ لذا فكلاهما حمض أكسجيني، ويختلفان في الأيون (عدد ذرات الأكسجين فيه).', '["الحمض الثنائي يتكون من الهيدروجين وعنصر آخر فقط، وكلا الحمضين يحتوي على ثلاثة عناصر وأيون أكسجيني.","","احتواء الأيون على ذرات أكسجين أقل لا يجعل الحمض ثنائيًا؛ فـ HNO₂ ما زال يحتوي على أيون أكسجيني."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-11T13:13:22.475Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1058, null, null, null, 'الحمض الأكسجيني: حمض يحتوي على الهيدروجين وأيون أكسجيني (أيون عديد الذرات يحتوي على الأكسجين). مثالان: HNO₃ والأيون الأكسجيني فيه NO₃⁻ (النترات)؛ H₂SO₄ والأيون الأكسجيني فيه SO₄²⁻ (الكبريتات). (تقبل أمثلة أخرى صحيحة مثل HClO₃ بأيون الكلورات ClO₃⁻ أو H₃PO₄ بأيون الفوسفات PO₄³⁻).', '["التعريف: هيدروجين + أيون أكسجيني","مثال أول صحيح مع أيونه واسمه","مثال ثانٍ صحيح مع أيونه واسمه"]'::jsonb, '[]'::jsonb, '[{"element":"التعريف الصحيح","marks":2},{"element":"المثال الأول مع الأيون","marks":1},{"element":"المثال الثاني مع الأيون","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تعريف دقيق ومثالان صحيحان مع تحديد الأيون الأكسجيني واسمه في كل منهما"},{"level":"3 درجات","description":"تعريف صحيح ومثالان مع خطأ في اسم أحد الأيونين أو صيغته"},{"level":"2 درجتان","description":"تعريف صحيح دون أمثلة صحيحة، أو مثالان صحيحان مع تعريف ناقص"},{"level":"1 درجة","description":"مثال واحد صحيح فقط"},{"level":"صفر","description":"تعريف خاطئ (مثل تعريف الحمض الثنائي) ولا أمثلة صحيحة"}]'::jsonb, '["تعريف الحمض الأكسجيني بأنه «حمض يحتوي على الأكسجين» دون ذكر الأيون الأكسجيني","ذكر HCl أو H₂S مثالًا على الحمض الأكسجيني","الخلط بين النترات NO₃⁻ والنتريت NO₂⁻"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-10-11T13:13:22.475Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1059, null, null, null, 'أحماض أكسجينية: H₃PO₄ لأنه يحتوي على أيون الفوسفات PO₄³⁻ الأكسجيني؛ HClO₂ لأنه يحتوي على أيون الكلوريت ClO₂⁻ الأكسجيني. أحماض غير أكسجينية: HCl لأنه يتكون من الهيدروجين والكلور فقط (حمض ثنائي)؛ HCN لأنه لا يحتوي على الأكسجين (أيون السيانيد CN⁻ ليس أكسجينيًا) رغم احتوائه على ثلاثة عناصر.', '["H₃PO₄ أكسجيني مع السبب","HClO₂ أكسجيني مع السبب","HCl غير أكسجيني (ثنائي) مع السبب","HCN غير أكسجيني مع السبب"]'::jsonb, '[]'::jsonb, '[{"element":"تصنيف H₃PO₄ وسببه","marks":1},{"element":"تصنيف HClO₂ وسببه","marks":1},{"element":"تصنيف HCl وسببه","marks":1},{"element":"تصنيف HCN وسببه","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تصنيف الأحماض الأربعة صحيحًا مع سبب صحيح لكل منها"},{"level":"3 درجات","description":"ثلاثة أحماض مصنفة صحيحًا مع أسبابها"},{"level":"2 درجتان","description":"حمضان مصنفان صحيحًا مع السبب، أو تصنيف صحيح للجميع دون أسباب"},{"level":"1 درجة","description":"حمض واحد مصنف صحيحًا مع سببه"},{"level":"صفر","description":"تصنيف خاطئ أو لا إجابة"}]'::jsonb, '["تصنيف HCN حمضًا أكسجينيًا لأنه يتكون من ثلاثة عناصر","ذكر التصنيف دون سبب","اعتبار عدد ذرات الهيدروجين معيارًا للتصنيف"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-11T13:13:22.476Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1060, null, null, null, 'العبارة غير دقيقة. المقطعان «يك» و«وز» لا يدلان على عدد الذرات في الجزيء، بل على الأيون الأكسجيني الذي اشتُق منه الحمض: «يك» للحمض المشتق من أيون ينتهي اسمه بـ«ات» (ويحتوي على عدد أكبر من ذرات الأكسجين)، و«وز» للحمض المشتق من أيون ينتهي اسمه بـ«يت» (عدد أقل من ذرات الأكسجين). فحمض الكلوريك HClO₃ مشتق من أيون الكلورات ClO₃⁻، وحمض الكلوروز HClO₂ مشتق من أيون الكلوريت ClO₂⁻. أما الدلالة على عدد الذرات فتكون بالبادئات (أحادي، ثنائي، ثلاثي...) في تسمية المركبات الجزيئية مثل ثلاثي فلوريد الكلور ClF₃.', '["الحكم بأن العبارة غير دقيقة","«يك» ترتبط بالأيون المنتهي بـ«ات»","«وز» ترتبط بالأيون المنتهي بـ«يت»","التطبيق على HClO₃ (كلورات) وHClO₂ (كلوريت)","البادئات هي التي تدل على عدد الذرات"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم الصحيح على العبارة","marks":1},{"element":"ربط «يك» بـ«ات» و«وز» بـ«يت»","marks":2},{"element":"التطبيق على الحمضين","marks":1},{"element":"ذكر أن البادئات تدل على عدد الذرات","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"حكم صحيح مع تصحيح كامل وتطبيق صحيح على الحمضين وذكر دور البادئات"},{"level":"4 درجات","description":"حكم وتصحيح وتطبيق صحيح دون ذكر البادئات"},{"level":"3 درجات","description":"حكم صحيح وربط صحيح للمقطعين دون تطبيق على الحمضين"},{"level":"2 درجتان","description":"حكم صحيح مع تصحيح ناقص أو فيه خلط بين «ات» و«يت»"},{"level":"1 درجة","description":"الحكم الصحيح فقط"},{"level":"صفر","description":"تأييد العبارة أو لا إجابة"}]'::jsonb, '["تأييد العبارة والقول إن «يك» تعني ذرات أكثر في الجزيء كله","عكس العلاقة: ربط «يك» بالأيون المنتهي بـ«يت»","الخلط بين صيغتي الكلورات والكلوريت"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-10-11T13:13:22.476Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1061, 0, 'يحتوي HNO₃ على أيون النترات NO₃⁻ المنتهي بـ«ات»، فيُستبدل به «يك»: حمض النيتريك، ولا تستخدم البادئة «هيدرو» في الأحماض الأكسجينية.', '["","«حمض النيتروز» اسم HNO₂ المشتق من أيون النتريت NO₂⁻ المنتهي بـ«يت».","البادئة «هيدرو» خاصة بالأحماض غير الأكسجينية (الثنائية ونحوها)، ولا تستخدم مع الأحماض الأكسجينية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (60%)"}],"at":"2026-10-11T13:13:22.479Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1062, 2, 'يحتوي HClO₂ على أيون الكلوريت ClO₂⁻ المنتهي بـ«يت»، فيُستبدل به «وز»: حمض الكلوروز.', '["«حمض الكلوريك» اسم HClO₃ المشتق من أيون الكلورات ClO₃⁻.","«حمض الهيدروكلوريك» اسم الحمض الثنائي HCl الذي لا يحتوي على الأكسجين.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (60%)"}],"at":"2026-10-11T13:13:22.479Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1063, 1, 'يحتوي H₃PO₄ على أيون الفوسفات PO₄³⁻ المنتهي بـ«ات»، فيسمى حمض الفوسفوريك دون البادئة «هيدرو» ودون الإشارة إلى عدد ذرات الهيدروجين.', '["البادئة «هيدرو» لا تستخدم في تسمية الأحماض الأكسجينية.","","المقطع «وز» يستخدم للحمض المشتق من أيون ينتهي بـ«يت»، والفوسفات ينتهي بـ«ات»."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (60%)"}],"at":"2026-10-11T13:13:22.480Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1064, 0, 'اسم الأيون «كبريتيت» ينتهي بـ«يت»، فيُستبدل به «وز»: حمض الكبريتوز. أما حمض الكبريتيك فهو H₂SO₄ المشتق من الكبريتات SO₄²⁻.', '["","«حمض الكبريتيك» اسم H₂SO₄ المشتق من أيون الكبريتات SO₄²⁻ المنتهي بـ«ات».","«حمض الهيدروكبريتيك» اسم الحمض الثنائي H₂S الذي لا يحتوي على الأكسجين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-11T13:13:22.482Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1065, 2, 'H₂CO₃ يحتوي على أيون الكربونات CO₃²⁻ المنتهي بـ«ات»، فاسمه حمض الكربونيك، وهي تسمية صحيحة. أما HClO₃ فاسمه حمض الكلوريك (من الكلورات)، وHNO₂ اسمه حمض النيتروز (من النتريت).', '["HClO₃ مشتق من الكلورات ClO₃⁻ المنتهي بـ«ات»، فاسمه حمض الكلوريك لا الكلوروز.","HNO₂ مشتق من النتريت NO₂⁻ المنتهي بـ«يت»، فاسمه حمض النيتروز لا النيتريك.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-10-11T13:13:22.482Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1066, 1, 'اسم الأيون «برومات» ينتهي بـ«ات»، فيُكتب «حمض» ثم جذر اسم الأيون مع «يك»: حمض البروميك، دون البادئة «هيدرو».', '["«حمض الهيدروبروميك» اسم الحمض الثنائي HBr الذي لا يحتوي على الأكسجين.","","المقطع «وز» للحمض المشتق من أيون ينتهي بـ«يت» (البروميت)، لا من البرومات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-11T13:13:22.482Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1067, 2, 'يحتوي HNO₂ على أيون النتريت NO₂⁻ واسمه ينتهي بـ«يت»، فيُستبدل به «وز». أما «النيتريك» فللحمض HNO₃ المشتق من النترات NO₃⁻.', '["عدد ذرات الهيدروجين لا يحدد المقطع؛ فحمض النيتريك HNO₃ فيه أيضًا ذرة هيدروجين واحدة.","HNO₂ حمض أكسجيني لأنه يحتوي على أيون النتريت الأكسجيني، وليس حمضًا ثنائيًا.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-11T13:13:22.482Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1068, null, null, null, 'HClO₃: الأيون ClO₃⁻ (كلورات) ← حمض الكلوريك. H₂SO₄: الأيون SO₄²⁻ (كبريتات) ← حمض الكبريتيك. HNO₂: الأيون NO₂⁻ (نتريت) ← حمض النيتروز. H₂CO₃: الأيون CO₃²⁻ (كربونات) ← حمض الكربونيك.', '["حمض الكلوريك مع ClO₃⁻ كلورات","حمض الكبريتيك مع SO₄²⁻ كبريتات","حمض النيتروز مع NO₂⁻ نتريت","حمض الكربونيك مع CO₃²⁻ كربونات"]'::jsonb, '[]'::jsonb, '[{"element":"HClO₃","marks":1},{"element":"H₂SO₄","marks":1},{"element":"HNO₂","marks":1},{"element":"H₂CO₃","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تسمية الأحماض الأربعة صحيحة مع الأيونات"},{"level":"3 درجات","description":"ثلاثة أحماض صحيحة"},{"level":"2 درجتان","description":"حمضان صحيحان"},{"level":"1 درجة","description":"حمض واحد صحيح"},{"level":"صفر","description":"لا تسمية صحيحة"}]'::jsonb, '["استخدام البادئة «هيدرو» مع الأحماض الأكسجينية","تسمية HNO₂ حمض النيتريك","الخلط بين شحنة الكبريتات والكربونات أو صيغتيهما"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-11T13:13:22.483Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1069, null, null, null, 'الخطوات: (1) تحديد الأيون الأكسجيني في الحمض واسمه. (2) كتابة كلمة «حمض» ثم جذر اسم الأيون. (3) إذا انتهى اسم الأيون بـ«ات» يُستبدل به «يك»، وإذا انتهى بـ«يت» يُستبدل به «وز»، دون استخدام البادئة «هيدرو». التطبيق: HClO₃ أيونه ClO₃⁻ (كلورات) ← حمض الكلوريك؛ HClO₂ أيونه ClO₂⁻ (كلوريت) ← حمض الكلوروز. سبب الاختلاف: اختلاف الأيون الأكسجيني؛ فالكلورات تحتوي على ثلاث ذرات أكسجين وينتهي اسمها بـ«ات»، والكلوريت تحتوي على ذرتين وينتهي اسمها بـ«يت».', '["تحديد الأيون الأكسجيني","حمض + جذر الأيون","ات ← يك ، يت ← وز ودون «هيدرو»","تسمية HClO₃ حمض الكلوريك","تسمية HClO₂ حمض الكلوروز","تعليل الاختلاف بالأيون"]'::jsonb, '[]'::jsonb, '[{"element":"خطوات التسمية","marks":2},{"element":"تسمية الحمضين","marks":2},{"element":"تعليل الاختلاف","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"خطوات كاملة وتسمية صحيحة للحمضين وتعليل صحيح"},{"level":"4 درجات","description":"تسمية وتعليل صحيحان مع نقص في خطوة"},{"level":"3 درجات","description":"تسمية صحيحة للحمضين دون خطوات أو دون تعليل"},{"level":"2 درجتان","description":"تسمية حمض واحد صحيحة مع خطوات ناقصة"},{"level":"1 درجة","description":"ذكر قاعدة «ات ← يك» أو «يت ← وز» فقط"},{"level":"صفر","description":"لا إجابة صحيحة"}]'::jsonb, '["عكس القاعدة (ات ← وز)","تعليل الاختلاف بعدد ذرات الهيدروجين","إضافة «هيدرو» إلى الاسم"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-11T13:13:22.484Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1070, null, null, null, 'الخطأ الأول: استخدام البادئة «هيدرو» مع حمض أكسجيني؛ H₂SO₄ يحتوي على أيون الكبريتات SO₄²⁻ (ينتهي بـ«ات»)، فاسمه الصحيح حمض الكبريتيك. (حمض الهيدروكبريتيك اسم الحمض الثنائي H₂S). الخطأ الثاني: استخدام المقطع «وز» بدل «يك»؛ HNO₃ يحتوي على أيون النترات NO₃⁻ (ينتهي بـ«ات») فاسمه الصحيح حمض النيتريك، أما حمض النيتروز فهو HNO₂ المشتق من النتريت.', '["تحديد خطأ «هيدرو» في الاسم الأول","الاسم الصحيح: حمض الكبريتيك مع التعليل","تحديد خطأ المقطع في الاسم الثاني","الاسم الصحيح: حمض النيتريك مع التعليل"]'::jsonb, '[]'::jsonb, '[{"element":"تحديد الخطأ الأول وتصحيحه","marks":2},{"element":"تحديد الخطأ الثاني وتصحيحه","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"تحديد الخطأين وتصحيحهما مع التعليل"},{"level":"3 درجات","description":"تصحيح الاسمين مع تعليل ناقص لأحدهما"},{"level":"2 درجتان","description":"تحديد خطأ واحد وتصحيحه بدقة"},{"level":"1 درجة","description":"ذكر اسم صحيح واحد دون تعليل"},{"level":"صفر","description":"لا إجابة صحيحة"}]'::jsonb, '["الاكتفاء بحذف «هيدرو» وكتابة «حمض الكبريت»","تصحيح الاسم الثاني إلى «حمض الهيدرونيتريك»","عدم ربط المقطع بالأيون الأكسجيني"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-11T13:13:22.484Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1071, 2, 'البادئة «ثلاثي» تسبق «فلوريد» فتدل على ثلاث ذرات فلور، وعدم وجود بادئة قبل «الكلور» يعني ذرة كلور واحدة، ويُكتب العنصر الأول (الكلور) أولًا في الصيغة: ClF₃.', '["البادئة «ثلاثي» تعود على الفلور لا على الكلور، فعكس الطالب الأرقام السفلية.","أهمل البادئة «ثلاثي» فكتب ذرة فلور واحدة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (44%)"}],"at":"2026-10-11T13:13:22.489Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1072, 0, '«ثنائي الفوسفور» تعني ذرتي فوسفور، و«خماسي أكسيد» تعني خمس ذرات أكسجين، فالصيغة P₂O₅.', '["","عكس البادئتين فنسب «خماسي» إلى الفوسفور و«ثنائي» إلى الأكسجين.","P₂O₃ صيغة ثلاثي أكسيد ثنائي الفوسفور؛ استخدم بادئة خاطئة للأكسجين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (63%)"}],"at":"2026-10-11T13:13:22.490Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1073, 1, '«عشاري» = 10 ذرات فلور، و«ثنائي الكبريت» = ذرتا كبريت، والكبريت يُكتب أولًا: S₂F₁₀.', '["عكس الأرقام السفلية فنسب «عشاري» إلى الكبريت.","","أهمل البادئة «ثنائي» قبل الكبريت فكتب ذرة كبريت واحدة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (44%)"}],"at":"2026-10-11T13:13:22.490Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1074, 2, '«ثنائي النيتروجين» = ذرتا نيتروجين، و«أكسيد» دون بادئة = ذرة أكسجين واحدة، فالصيغة N₂O.', '["NO₂ صيغة ثنائي أكسيد النيتروجين؛ نُسبت البادئة «ثنائي» خطأً إلى الأكسجين.","أضاف بادئة «ثنائي» للأكسجين أيضًا رغم أن «أكسيد» ليست مسبوقة ببادئة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (63%)"}],"at":"2026-10-11T13:13:22.490Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1075, 1, 'ثلاثي أكسيد الكبريت يعني ذرة كبريت واحدة وثلاث ذرات أكسجين، فصيغته الصحيحة SO₃ لا S₃O؛ أما SF₆ وCCl₄ فصحيحتان.', '["سداسي فلوريد الكبريت: ذرة كبريت وست ذرات فلور، فالصيغة SF₆ صحيحة.","","رباعي كلوريد الكربون: ذرة كربون وأربع ذرات كلور، فالصيغة CCl₄ صحيحة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (3%)"}],"at":"2026-10-11T13:13:22.490Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1076, 0, 'البادئة «هيدرو» تدل على حمض غير أكسجيني يتكون من الهيدروجين واليود فقط، وشحنة أيون اليوديد −1 فيلزم ذرة هيدروجين واحدة: HI.', '["","HIO₃ حمض أكسجيني (يحتوي على أيون اليودات)، واسم الحمض المعطى بالبادئة «هيدرو» يدل على غياب الأكسجين.","أيون اليوديد I⁻ شحنته −1 فيكفيه أيون هيدروجين واحد، لا اثنان."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-11T13:13:22.490Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1077, 2, '«وز» تدل على أيون ينتهي بـ«يت» وهو الكبريتيت SO₃²⁻، وشحنته −2 فيلزم أيونا هيدروجين: H₂SO₃.', '["H₂SO₄ صيغة حمض الكبريتيك المشتق من الكبريتات SO₄²⁻.","أهمل شحنة الأيون −2 فكتب ذرة هيدروجين واحدة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-10-11T13:13:22.491Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1078, null, null, null, '(أ) P₂O₃ ، (ب) NO ، (ج) PCl₅ ، (د) HF.', '["P₂O₃","NO","PCl₅","HF"]'::jsonb, '[]'::jsonb, '[{"element":"(أ)","marks":1},{"element":"(ب)","marks":1},{"element":"(ج)","marks":1},{"element":"(د)","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"الصيغ الأربع صحيحة"},{"level":"3 درجات","description":"ثلاث صيغ صحيحة"},{"level":"2 درجتان","description":"صيغتان صحيحتان"},{"level":"1 درجة","description":"صيغة واحدة صحيحة"},{"level":"صفر","description":"لا صيغة صحيحة"}]'::jsonb, '["كتابة P₃O₂ بعكس البادئتين","كتابة N₂O أو NO₂ لأحادي أكسيد النيتروجين","كتابة HFO أو H₂F لحمض الهيدروفلوريك"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (35%)"}],"at":"2026-10-11T13:13:22.491Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1079, null, null, null, 'البادئات (أحادي، ثنائي، ثلاثي، رباعي، خماسي، سداسي...) تحدد عدد ذرات كل عنصر، فتُكتب رقمًا سفليًا بعد رمز العنصر الذي تسبقه، مثل رباعي أكسيد ثنائي النيتروجين N₂O₄. أما المقطعان «يك» و«وز» فلا يشيران إلى عدد الذرات، بل إلى الأيون الأكسجيني: حمض النيتريك مشتق من النترات NO₃⁻ فصيغته HNO₃، وحمض النيتروز مشتق من النتريت NO₂⁻ فصيغته HNO₂. فالمقطع يحدد أي الأيونين نختار (وبالتالي عدد ذرات الأكسجين في الأيون)، ثم نكتب عدد ذرات الهيدروجين بما يعادل شحنة الأيون.', '["البادئات تحدد عدد ذرات كل عنصر (رقم سفلي)","مثال صحيح على البادئات","«يك/وز» تدل على الأيون الأكسجيني لا على عدد الذرات","HNO₃ لحمض النيتريك","HNO₂ لحمض النيتروز"]'::jsonb, '[]'::jsonb, '[{"element":"دور البادئات مع مثال","marks":2},{"element":"تصحيح العبارة","marks":1},{"element":"صيغتا الحمضين","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"توضيح دور البادئات بمثال وتصحيح العبارة وكتابة الصيغتين صحيحتين"},{"level":"4 درجات","description":"كل ما سبق مع نقص المثال أو خطأ في صيغة واحدة"},{"level":"3 درجات","description":"تصحيح العبارة وكتابة الصيغتين دون توضيح البادئات"},{"level":"2 درجتان","description":"كتابة الصيغتين فقط أو توضيح البادئات فقط"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"لا إجابة صحيحة"}]'::jsonb, '["تأييد العبارة","كتابة HNO₂ لحمض النيتريك","ربط البادئة بالعنصر الخطأ"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-10-11T13:13:22.491Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1080, null, null, null, 'الصيغة الأولى: عكس الطالب البادئتين؛ «ثنائي الفوسفور» تعني ذرتي فوسفور، و«ثلاثي أكسيد» تعني ثلاث ذرات أكسجين، فالصيغة الصحيحة P₂O₃. الصيغة الثانية: H₂S صيغة حمض الهيدروكبريتيك (حمض ثنائي بلا أكسجين)، أما «حمض الكبريتيك» فاسم حمض أكسجيني ينتهي بـ«يك» فهو مشتق من أيون الكبريتات SO₄²⁻، وشحنته −2 فيلزمه ذرتا هيدروجين: H₂SO₄.', '["تحديد خطأ عكس البادئتين","الصيغة الصحيحة P₂O₃","تحديد أن H₂S حمض ثنائي بلا أكسجين","الصيغة الصحيحة H₂SO₄ مع ربطها بالكبريتات"]'::jsonb, '[]'::jsonb, '[{"element":"تحليل الخطأ الأول وتصحيحه","marks":2},{"element":"تحليل الخطأ الثاني وتصحيحه","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"تحديد الخطأين وتصحيحهما مع التعليل"},{"level":"3 درجات","description":"تصحيح الصيغتين مع تعليل ناقص"},{"level":"2 درجتان","description":"تصحيح صيغة واحدة مع التعليل"},{"level":"1 درجة","description":"كتابة صيغة صحيحة واحدة دون تعليل"},{"level":"صفر","description":"لا إجابة صحيحة"}]'::jsonb, '["تصحيح الصيغة الثانية إلى H₂SO₃","الاكتفاء بعكس الأرقام دون تعليل","عدم ربط «يك» بالأيون المنتهي بـ«ات»"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-11T13:13:22.491Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1081, 1, 'مجموع إلكترونات التكافؤ = 5 (N) + 3 × 1 (H) = 8 إلكترونات، أي 4 أزواج.', '["احتسب إلكترونات تكافؤ النيتروجين فقط وأهمل ذرات الهيدروجين الثلاث.","","احتسب لكل ذرة هيدروجين إلكترونين (5 + 3 × 2) بدل إلكترون تكافؤ واحد."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-10-11T13:13:22.495Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1082, 2, 'مجموع إلكترونات التكافؤ = 5 + 3 × 1 = 8، وعدد الأزواج = 8 ÷ 2 = 4 أزواج (3 رابطة وزوج حر).', '["3 أزواج هي الأزواج الرابطة فقط، وأُهمل الزوج الحر على ذرة الفوسفور.","استُعمل عدد إلكترونات تكافؤ الفوسفور (5) عددًا للأزواج.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-10-11T13:13:22.495Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1083, 0, 'يمتلك الهيدروجين إلكترون تكافؤ واحدًا ويستقر بإلكترونين، فيكوّن رابطة واحدة فقط (يشارك بزوج واحد)، ولا يمكنه الارتباط بأكثر من ذرة ليكون مركزيًا.', '["","سبب كون الهيدروجين جانبيًا هو قدرته على تكوين رابطة واحدة فقط، لا كهروسالبيته؛ والنيتروجين أعلى كهروسالبية منه.","ذرة الهيدروجين في هذه الجزيئات لا تحمل أي زوج حر؛ يحيط بها زوج الرابطة فقط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-11T13:13:22.496Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1084, 1, 'حول الفوسفور ثلاثة أزواج رابطة (6 إلكترونات) وزوج حر واحد (إلكترونان)، فالمجموع 8 إلكترونات وتتحقق قاعدة الثمانية.', '["احتسب الأزواج الرابطة فقط وأهمل الزوج الحر على الفوسفور.","","أضاف زوجًا حرًا زائدًا على الفوسفور؛ مجموع الإلكترونات في الجزيء كله 8 فقط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-10-11T13:13:22.496Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1085, 2, 'يقع النيتروجين والفوسفور في المجموعة 15، فلكل منهما 5 إلكترونات تكافؤ؛ لذا يكوّن كل منهما ثلاث روابط أحادية مع H ويبقى عليه زوج حر واحد.', '["النيتروجين في الدورة الثانية والفوسفور في الدورة الثالثة؛ التشابه سببه المجموعة لا الدورة.","الكتلة لا تحدد تركيب لويس، وكتلة الفوسفور (31) تزيد كثيرًا على كتلة النيتروجين (14).",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-10-11T13:13:22.496Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1086, 0, 'في NH₃ ثمانية إلكترونات تكافؤ: ثلاثة أزواج رابطة (N–H) وزوج حر واحد على N، فيحيط بالنيتروجين 8 إلكترونات، وهذا يطابق التركيب (أ).', '["","التركيب (ب) يستعمل 6 إلكترونات فقط، فيُهمل الزوج الحر ولا يكتمل الثماني حول N.","التركيب (ج) يستعمل 10 إلكترونات، وهو أكثر من مجموع إلكترونات التكافؤ (8)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-11T13:13:22.496Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1087, 1, 'مجموع الإلكترونات 8، استعمل الطالب 6 منها في الروابط وأهمل الإلكترونين الباقيين اللذين يكوّنان زوجًا حرًا على N، فلم تتحقق قاعدة الثمانية حول النيتروجين.', '["النيتروجين هو الذرة المركزية الصحيحة؛ لأن الهيدروجين يكون جانبيًا دائمًا.","","الروابط N–H أحادية صحيحة؛ فالهيدروجين لا يكوّن إلا رابطة أحادية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-11T13:13:22.497Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(1088, null, null, null, 'الخطوات: (1) مجموع إلكترونات التكافؤ = 5 + 3 × 1 = 8 إلكترونات. (2) عدد الأزواج = 8 ÷ 2 = 4 أزواج. (3) الذرة المركزية N، وذرات H جانبية لأنها تكوّن رابطة واحدة فقط. (4) نضع زوجًا رابطًا بين N وكل ذرة H فنستعمل 3 أزواج. (5) يبقى زوج واحد يوضع زوجًا حرًا على N، فيحيط بالنيتروجين 8 إلكترونات وبكل هيدروجين إلكترونان.
